def candidates(title: int) -> set[int]:
    s = str(title)
    out = set()
    # named operators only: drop one digit; swap adjacent digits
    for i in range(len(s)):
        drop = s[:i] + s[i+1:]
        if drop and drop[0] != "0":
            out.add(int(drop))
    for i in range(len(s) - 1):
        swap = s[:i] + s[i+1] + s[i] + s[i+2:]
        if swap[0] != "0":
            out.add(int(swap))
    return {c for c in out if 1 <= c <= 50 and c != title}

def bare(token: str) -> str:
    value = token.strip().lower().replace(" et seq.", "").replace(" et seq", "").replace(" note", "")
    value = re.sub(r"\([^()]*\)", "", value).strip()
    return value.split("|")[0].strip()

def survivors(pools, usc_corpus, level, key, token):
    value = bare(token)
    out = set()
    if distinctive(value) and len(usc_corpus.get(value, ())) == 1:
        out |= {("usc", t) for (t, s) in pools[f"usc_{level}"].get(key, ()) if s == value}
    out |= {("act", k) for (k, s) in pools[f"act_{level}"].get(key, ()) if s == value}
    return out

def main() -> None:
    rows, failed, pools, usc_corpus = load()
    print(f"rows {len(rows)}  failed {len(failed)}")

    # --- 1. bare section lists ---------------------------------------------
    tally = collections.Counter()
    recovered = collections.defaultdict(list)
    for r in failed:
        tokens = section_tokens(r["authority_text"])
        if tokens is None:
            continue
        tally["shaped"] += 1
        for level, key in (("rin", r["rin"]), ("ag", r["rin"][:4])):
            per = [survivors(pools, usc_corpus, level, key, t) for t in tokens]
            if any(len(s) > 1 for s in per):
                tally[f"ambiguous-{level}"] += 1
                break
            if all(len(s) == 1 for s in per):
                keys = {next(iter(s)) for s in per}
                if len(keys) == 1:
                    tally[f"resolved-{level}"] += 1
                    recovered[(r["authority_text"], next(iter(keys)), level)].append(r["rin"])
                else:
                    tally["tokens-disagree"] += 1
                break
        else:
            tally["silent"] += 1
    print("\n== bare section lists:", dict(tally))
    print(
        "   recovered rows:",
        sum(len(v) for v in recovered.values()),
        "distinct:",
        len({k[0] for k in recovered}),
        "schemes:",
        collections.Counter(k[1][0] for k, v in recovered.items() for _ in v),
    )
    for (text, hit, level), rins in sorted(recovered.items(), key=lambda kv: -len(kv[1]))[:20]:
        print(f"   {len(rins):3d}  [{level}] {hit}  {text!r}  (e.g. {rins[0]})")

    # --- 2. title-less code citations ("USC 44101") -------------------------
    labelled = re.compile(
        r"^U\.?\s?S\.?\s?C\.?(?:\s?A\.?)?\s+(?P<sec>\d{1,5}[A-Za-z]{0,3}(?:-\d{1,4}[A-Za-z]?)?)"
        r"(?:\([^()]{1,10}\))*(?P<note>\s+note)?[\s.,;]*$",
        re.IGNORECASE,
    )
    tally2 = collections.Counter()
    rec2 = collections.defaultdict(list)
    for r in failed:
        m = labelled.match(r["authority_text"].strip().strip("\"“”' "))
        if m is None:
            continue
        tally2["shaped"] += 1
        section = m.group("sec").lower()
        if not distinctive(section) or len(usc_corpus.get(section, ())) != 1:
            tally2["not-corpus-unique"] += 1
            continue
        for level, key in (("rin", r["rin"]), ("ag", r["rin"][:4])):
            hits = {t for (t, s) in pools[f"usc_{level}"].get(key, ()) if s == section}
            if len(hits) == 1:
                tally2[f"resolved-{level}"] += 1
                rec2[(r["authority_text"], next(iter(hits)), level)].append(r["rin"])
                break
            if hits:
                tally2[f"ambiguous-{level}"] += 1
                break
        else:
            tally2["silent"] += 1
    print("\n== title-less USC:", dict(tally2), "recovered", sum(len(v) for v in rec2.values()))
    for (text, hit, level), rins in sorted(rec2.items(), key=lambda kv: -len(kv[1]))[:12]:
        print(f"   {len(rins):3d}  [{level}] title {hit}  {text!r}  (e.g. {rins[0]})")

    # --- 3. label-less pairs ("49 46105", "8 1252 note") --------------------
    pair = re.compile(
        r"^(?P<title>\d{1,2})\s+(?P<sec>\d{2,5}[A-Za-z]{0,3})(?:\([^()]{1,10}\))*"
        r"(?P<note>\s+note)?(?:\s+et\s+seq\.?)?[\s.,;]*$"
    )
    tally3 = collections.Counter()
    rec3 = collections.defaultdict(list)
    for r in failed:
        m = pair.match(r["authority_text"].strip().strip("\"“”' "))
        if m is None:
            continue
        tally3["shaped"] += 1
        title, section = int(m.group("title")), m.group("sec").lower()
        for level, key in (("rin", r["rin"]), ("ag", r["rin"][:4])):
            usc_hit = (title, section) in pools[f"usc_{level}"].get(key, ())
            stat_hit = section.isdigit() and (title, int(section)) in pools[f"stat_{level}"].get(key, ())
            if usc_hit and stat_hit:
                tally3[f"both-schemes-{level}"] += 1
                break
            if usc_hit or stat_hit:
                tally3[f"resolved-{level}"] += 1
                rec3[(r["authority_text"], ("usc" if usc_hit else "stat", title, section), level)].append(r["rin"])
                break
        else:
            tally3["silent"] += 1
    print("\n== label-less pairs:", dict(tally3), "recovered", sum(len(v) for v in rec3.values()))
    for (text, hit, level), rins in sorted(rec3.items(), key=lambda kv: -len(kv[1]))[:12]:
        print(f"   {len(rins):3d}  [{level}] {hit}  {text!r}  (e.g. {rins[0]})")

    # --- 4. volume-less Statutes pages ("Stat. 2936") -----------------------
    statless = re.compile(r"^Stat\.?\s+(?P<page>\d{2,5})[\s.,;]*$", re.IGNORECASE)
    tally4 = collections.Counter()
    rec4 = collections.defaultdict(list)
    for r in failed:
        m = statless.match(r["authority_text"].strip().strip("\"“”' "))
        if m is None:
            continue
        tally4["shaped"] += 1
        page = int(m.group("page"))
        for level, key in (("rin", r["rin"]), ("ag", r["rin"][:4])):
            hits = {v for (v, p) in pools[f"stat_{level}"].get(key, ()) if p == page}
            if len(hits) == 1:
                tally4[f"resolved-{level}"] += 1
                rec4[(r["authority_text"], next(iter(hits)), level)].append(r["rin"])
                break
            if hits:
                tally4[f"ambiguous-{level}"] += 1
                break
        else:
            tally4["silent"] += 1
    print("\n== volume-less Stat pages:", dict(tally4), "recovered", sum(len(v) for v in rec4.values()))
    for (text, hit, level), rins in sorted(rec4.items(), key=lambda kv: -len(kv[1])):
        print(f"   {len(rins):3d}  [{level}] volume {hit}  {text!r}  (e.g. {rins[0]})")

    total = (
        sum(len(v) for v in recovered.values())
        + sum(len(v) for v in rec2.values())
        + sum(len(v) for v in rec3.values())
        + sum(len(v) for v in rec4.values())
    )
    print(f"\nTOTAL recoverable rows across the four shapes: {total}")

def sub_shape(text: str) -> str:
    s = text.strip().strip('"“”‘’ ')
    low = s.lower()

    if not s:
        return "empty"
    if COURT_RULE.search(s):
        return "court-rule"
    if DC.search(s):
        return "dc-instrument"
    if STATE_CODE.search(s):
        return "state-code"

    bare = bool(BARE_NUMS.match(s))
    if bare:
        # split the bare-number family by what the number LOOKS like
        digits = re.findall(r"\d+", s)
        if OMB_CONTROL.match(s):
            return "bare:omb-control-shape"
        if re.match(r"^\s*(?:[Ss]ecs?\.?|[Ss]ections?|§+)\s", s):
            return "bare:marked-section"
        if len(digits) == 1:
            n = digits[0]
            if len(n) >= 4 and 1789 <= int(n) <= 2035:
                return "bare:year-shaped"
            return f"bare:single-number-{len(n)}digit"
        return "bare:multi-number"

    if DESIGNATOR_ONLY.match(s):
        return "designator-only"
    if ANAPHORA.search(s) and not ACTWORD.search(re.sub(r"\bthe\s+Act\b|\bsaid\s+Act\b|\bthis\s+Act\b|\bthat\s+Act\b", "", s, flags=re.IGNORECASE)):
        return "anaphoric-act"
    if DATEISH.search(s) or DATE_WORD.search(s):
        return "date-fragment"
    if BILL.search(s):
        return "bill-number"
    if PL_LABEL.search(s):
        return "pl-label"
    if USC_LABEL.search(s):
        return "usc-label"
    if CFR_LABEL.search(s):
        return "cfr-label"
    if STAT_LABEL.search(s):
        return "stat-label"
    if FR_LABEL.search(s) and re.search(r"\d", s):
        return "fr-label"
    if ACTWORD.search(s):
        return "act-prose"
    words = re.findall(r"[A-Za-z]{2,}", s)
    caps = ABBREV.findall(s)
    if caps and not [w for w in words if w.lower() not in {c.lower() for c in caps} and len(w) > 3]:
        return "abbreviation"
    if HAS_ALPHA_WORD.search(s):
        return "other-prose"
    return "residue"

def act_year(key: str) -> int | None:
    years = [int(m.group(0)) for m in re.finditer(r"\b(?:18|19|20)\d{2}\b", key)]
    return max(years) if years else None

def readable(text: str) -> tuple[bool, str]:
    """Whether the grammar reads a typed citation out of the whole value."""

    citations = parse_authority_citation(text)
    kinds = {c.authority_type for c in citations}
    if kinds == {"other"} or kinds == {"unstated"}:
        return False, ""
    return True, ",".join(sorted(kinds))

def main() -> None:
    rows = pq.read_table(TABLE).to_pylist()
    failed = [r for r in rows if r["parse_status"] == "failed" and r["authority_type"] == "other"]
    by_text: dict[str, int] = collections.Counter(r["authority_text"] for r in failed)
    print(f"failed(other): {len(failed)} rows, {len(by_text)} distinct")

    claimed: set[str] = set()
    for name, pattern, replacement in CANDIDATES:
        wins: dict[str, tuple[str, str]] = {}
        for text in by_text:
            if text in claimed:
                continue
            repaired, count = pattern.subn(replacement, text, count=1)
            if not count or repaired == text:
                continue
            ok, kinds = readable(repaired)
            if ok:
                wins[text] = (repaired, kinds)
        rowcount = sum(by_text[t] for t in wins)
        print(f"\n== {name}: {rowcount} rows, {len(wins)} distinct ==")
        for text, (repaired, kinds) in sorted(wins.items(), key=lambda kv: -by_text[kv[0]])[:14]:
            print(f"   {by_text[text]:4d}  {text!r} -> {repaired!r}  [{kinds}]")
        claimed |= set(wins)

    print(f"\nTOTAL distinct claimed: {len(claimed)}, rows: {sum(by_text[t] for t in claimed)}")

def rin_variants(value: str) -> set[str]:
    """Candidates from named damage operators, never from a guess."""

    out: set[str] = set()
    base = value
    if re.match(r"^\d{4}[\s_]\w{4}$", value):
        base = value[:4] + "-" + value[5:]
        out.add(base)
    out.add(re.sub(r"\s+", "", base))
    body = base[5:] if len(base) > 5 and base[4] == "-" else ""
    if len(body) == 4:
        for index in (0, 1):  # letters
            for digit, letter in _HOMOGLYPHS:
                if body[index] == digit:
                    out.add(base[:5] + body[:index] + letter + body[index + 1:])
        for index in (2, 3):  # digits
            for digit, letter in _HOMOGLYPHS:
                if body[index] == letter:
                    out.add(base[:5] + body[:index] + digit + body[index + 1:])
    return {candidate for candidate in out if candidate != value}

def audit_fedreg_rins() -> None:
    if not FEDREG.exists() or not AGENDA.exists():
        print("federal_register or agenda parquet absent; skipping")
        return
    tokens: collections.Counter = collections.Counter()
    for value in pq.read_table(FEDREG, columns=["regulation_id_numbers_json"]).column(0).to_pylist():
        if not value:
            continue
        try:
            items = json.loads(value)
        except (TypeError, ValueError):
            continue
        for item in items or ():
            tokens[item] += 1
    roster = {
        rin.upper() for rin in pq.read_table(AGENDA, columns=["rin"]).column(0).to_pylist()
    }
    invalid = {k: v for k, v in tokens.items() if not is_regulation_identifier_number(k)}
    corroborated: collections.Counter = collections.Counter()
    shaped_only: collections.Counter = collections.Counter()
    alien: collections.Counter = collections.Counter()
    for token, count in invalid.items():
        value = token.strip().upper().replace("–", "-").replace("—", "-")
        wellformed = {
            normalize_rin(c) for c in rin_variants(value) if is_regulation_identifier_number(c)
        }
        survivors = wellformed & roster
        if len(survivors) == 1:
            corroborated[token] = count
        elif wellformed:
            shaped_only[token] = count
        else:
            alien[token] = count
    print("\n== B. federal_register.regulation_id_numbers_json ==")
    print(f"   {len(tokens)} distinct tokens, {sum(tokens.values())} occurrences")
    print(f"   invalid by the pinned RIN shape: {sum(invalid.values())} / {len(invalid)} distinct")
    print(f"   agenda roster: {len(roster)} RINs")
    print(f"   CORROBORATED (exactly one roster survivor): "
          f"{sum(corroborated.values())} / {len(corroborated)}")
    for token, count in corroborated.most_common(8):
        value = token.strip().upper()
        survivor = next(iter({normalize_rin(c) for c in rin_variants(value)
                              if is_regulation_identifier_number(c)} & roster))
        print(f"      {count:3d}  {token!r} -> {survivor!r}")
    print(f"   REFUSED, operator reaches a well-formed RIN the roster does not hold: "
          f"{sum(shaped_only.values())} / {len(shaped_only)}")
    print(f"      e.g. {sorted(shaped_only, key=lambda k: -shaped_only[k])[:8]}")
    print(f"   REFUSED, no operator reaches a RIN: {sum(alien.values())} / {len(alien)}")
    omb = {k: v for k, v in alien.items() if re.match(r"^\d{4}-\d{4}$", k)}
    print(f"      of which OMB control numbers filed as RINs: {sum(omb.values())} / {len(omb)}"
          f"  e.g. {sorted(omb)[:6]}")
    print(f"      remainder: {sorted(set(alien) - set(omb))}")

