def key(s):
    m = re.match(r"^(\d+)(.*)$", s)
    return (int(m.group(1)), m.group(2)) if m else None

def exists(t, s):
    if (t, s) in LIVE:
        return True
    k = key(s)
    if k is None:
        return False
    for klo, khi in rng_by_title.get(t, ()):
        if klo <= k <= khi:
            return True
    return False

def candidates(t, s):
    """Small-edit neighbours of (t, s), tagged by the edit that produced them."""
    out = {}

    def add(kind, tt, ss):
        if (tt, ss) != (t, s) and exists(tt, ss):
            out.setdefault((tt, ss), set()).add(kind)

    # leading-zero pad
    if re.match(r"^0\d", s):
        add("zero-pad", t, s.lstrip("0"))
    # subsection letter restored / dropped
    m = re.match(r"^(\d+)$", s)
    if m:
        for suf in SUFFIXES:
            add("suffix-restored", t, s + suf)
    m = re.match(r"^(\d+)[a-z]+$", s)
    if m:
        add("suffix-dropped", t, m.group(1))
    # digit edits on the numeric stem
    m = re.match(r"^(\d+)(.*)$", s)
    if m:
        num, tail = m.group(1), m.group(2)
        for i in range(len(num) - 1):          # transposition
            if num[i] != num[i + 1]:
                add("transposed", t, num[:i] + num[i + 1] + num[i] + num[i + 2:] + tail)
        for i in range(len(num)):              # deletion
            if len(num) > 1:
                add("digit-dropped", t, num[:i] + num[i + 1:] + tail)
        for i in range(len(num) + 1):          # insertion
            for d in "0123456789":
                add("digit-added", t, num[:i] + d + num[i:] + tail)
        for i in range(len(num)):              # substitution
            for d in "0123456789":
                if d != num[i]:
                    add("digit-changed", t, num[:i] + d + num[i + 1:] + tail)
    # wrong title
    for tt in list(range(1, 55)):
        if tt != t:
            add("other-title", tt, s)
    return out

def cands(t, s):
    out = collections.defaultdict(set)

    def add(k, ss):
        if ss != s and (t, ss) in LIVE:
            out[ss].add(k)
    m = re.match(r"^(\d+)(.*)$", s)
    if not m:
        return out
    num, tail = m.group(1), m.group(2)
    for i in range(len(num) - 1):
        if num[i] != num[i + 1]:
            add("transposed", num[:i] + num[i + 1] + num[i] + num[i + 2:] + tail)
    if len(num) > 1:
        for i in range(len(num)):
            add("digit-dropped", num[:i] + num[i + 1:] + tail)
    for i in range(len(num) + 1):
        for d in "0123456789":
            add("digit-added", num[:i] + d + num[i:] + tail)
    for i in range(len(num)):
        for d in "0123456789":
            if d != num[i]:
                add("digit-changed", num[:i] + d + num[i + 1:] + tail)
    if re.fullmatch(r"\d+", s):
        for suf in SUF:
            add("suffix-restored", s + suf)
    mm = re.fullmatch(r"(\d+)([a-z]+)", s)
    if mm:
        add("suffix-dropped", mm.group(1))
    return out

def key(s):
    m = re.match(r"^(\d+)(.*)$", s)
    return (int(m.group(1)), m.group(2)) if m else None

def sec_exists(t, s, appendix=False):
    if appendix:
        if (t, s) in ann_app:
            return True
        k = key(s)
        return bool(k) and any(a <= k <= b for a, b in rng_app.get(t, ()))
    if (t, s) in LIVE:
        return True
    k = key(s)
    return bool(k) and any(a <= k <= b for a, b in rng_by_title.get(t, ()))

def near(t, s):
    out = collections.defaultdict(set)

    def add(kind, tt, ss):
        if (tt, ss) != (t, s) and sec_exact(tt, ss):
            out[(tt, ss)].add(kind)

    if re.match(r"^0\d", s):
        add("zero-pad", t, s.lstrip("0"))
    if re.fullmatch(r"\d+", s):
        for suf in SUFFIXES:
            add("suffix-restored", t, s + suf)
    m = re.fullmatch(r"(\d+)([a-z]+)", s)
    if m:
        add("suffix-dropped", t, m.group(1))
    m = re.match(r"^(\d+)(.*)$", s)
    if m:
        num, tail = m.group(1), m.group(2)
        for i in range(len(num) - 1):
            if num[i] != num[i + 1]:
                add("transposed", t, num[:i] + num[i + 1] + num[i] + num[i + 2:] + tail)
        if len(num) > 1:
            for i in range(len(num)):
                add("digit-dropped", t, num[:i] + num[i + 1:] + tail)
        for i in range(len(num) + 1):
            for d in "0123456789":
                add("digit-added", t, num[:i] + d + num[i:] + tail)
        for i in range(len(num)):
            for d in "0123456789":
                if d != num[i]:
                    add("digit-changed", t, num[:i] + d + num[i + 1:] + tail)
    for tt in range(1, 55):
        if tt != t:
            add("other-title", tt, s)
    return out

def sha256(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as fh:
        for chunk in iter(lambda: fh.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()

def annual_tables(directory: Path):
    """The two annual mappings, built exactly the way the module builds them."""

    table = pq.read_table(directory / "usc-oracle-annual-sections.parquet")
    sections: dict[tuple[int, bool, str], list[int]] = {}
    for year, title, appendix, section in zip(
        table.column("year").to_pylist(),
        table.column("title").to_pylist(),
        table.column("appendix").to_pylist(),
        table.column("section").to_pylist(),
        strict=True,
    ):
        sections.setdefault((title, appendix, normalize_section(section)), []).append(year)
    sections = {key: tuple(sorted(years)) for key, years in sections.items()}

    table = pq.read_table(directory / "usc-oracle-annual-ranges.parquet")
    ranges: dict[tuple[int, bool], list] = {}
    for year, title, appendix, low, high in zip(
        table.column("year").to_pylist(),
        table.column("title").to_pylist(),
        table.column("appendix").to_pylist(),
        table.column("lo").to_pylist(),
        table.column("hi").to_pylist(),
        strict=True,
    ):
        low_key, high_key = _section_key(normalize_section(low)), _section_key(normalize_section(high))
        if low_key and high_key:
            ranges.setdefault((title, appendix), []).append((low_key, high_key, year))
    ranges = {key: tuple(spans) for key, spans in ranges.items()}
    return sections, ranges

def flip_lines(rows):
    for rin, pub, text, title, section, appendix, verdict, attested, whole, year, v1, v2 in sorted(rows):
        yield TAB.join([rin, pub, str(year), str(title), str(section), str(appendix),
                        text.replace("\t", " "), (whole or "").replace("\t", " ")])

