def _normalized_search_words(values: Sequence[str]) -> set[str]:
    words: set[str] = set()
    for value in values:
        normalized = unicodedata.normalize("NFKD", value.casefold()).encode(
            "ascii", "ignore"
        ).decode("ascii")
        words.update(re.findall(r"[a-z0-9]+", normalized))
