) -> RegistryInputPin:
    matches = [pin for pin in release.inputs if pin.sha256 == resource.source_digest]
    if len(matches) != 1:
        raise ValueError(
            f"agency identity resource {resource.iri} does not select one input pin"
        )
    return matches[0]

