class ParsedCensusFinanceResource:
    """A parsed, digest-pinned Census finance code list."""

    source: CensusFinanceSource
    retrieved_at: str
    source_sha256: str
    source_byte_length: int
    codes: tuple[CensusFinanceCode, ...]
    gaps: tuple[str, ...]

    def by_code(self) -> dict[str, CensusFinanceCode]:
        """Index the publisher-issued code for resources that carry one."""

        code_kind = {
            "censusFunctionItemCodes": "censusFunctionItemCode",
            "censusDataFlagCodes": "censusDataFlagCode",
        }.get(self.source.resource_name)
        if code_kind is None:
            raise CensusFinanceSourceDriftError(
                f"{self.source.resource_name} publishes no stable per-row code"
            )
        result: dict[str, CensusFinanceCode] = {}
        for entry in self.codes:
            matches = [identifier for identifier in entry.identifiers if identifier.kind == code_kind]
            if len(matches) != 1:
                raise CensusFinanceSourceDriftError(
                    f"{self.source.resource_name} row must retain exactly one {code_kind}"
                )
            result[matches[0].value] = entry
        return result

