def _decode_html(payload: bytes) -> str:
    try:
        return payload.decode("utf-8")
    except UnicodeDecodeError as error:
        raise CensusFinanceSourceDriftError("captured page is not UTF-8") from error

def _feed(parser: _LandmarkTableParser, decoded: str) -> None:
    try:
        parser.feed(decoded)
        parser.close()
    except CensusFinanceResourceError:
        raise
    except Exception as error:
        raise CensusFinanceSourceDriftError("captured page is malformed HTML") from error

def _make_identifier(*, value: str, kind: str, page: AcquiredCensusFinancePage) -> ControlledIdentifier:
    return ControlledIdentifier(
        value=value,
        kind=kind,
        authority_uri=CENSUS_IDENTIFIER_AUTHORITY_URI,
        source_uri=page.pin.source.source_url,
        observed_at=page.pin.retrieved_at,
        effective_at=None,
        source_digest=page.sha256,
    )

def parse_census_data_flag_codes(page: AcquiredCensusFinancePage) -> ParsedCensusFinanceResource:
    """Parse the exact ASPEP data flag codes, keeping the publisher's sections."""

    source = CENSUS_DATA_FLAG_CODES_SOURCE
    if page.pin.source != source:
        raise CensusFinanceSourceDriftError("page was not acquired against the data-flag-codes source")
    decoded = _decode_html(_read_acquired_payload(page))
    parser = _LandmarkTableParser(h1_attr="class", h1_value="cmp-title__text")
    _feed(parser, decoded)

    # census.gov's AEM template renders the title landmark twice with
    # identical text (a visible heading plus a duplicate for another
    # breakpoint); require at least one match rather than exactly one.
    if parser.h1_match_count < 1 or parser.h1_text != source.title:
        raise CensusFinanceSourceDriftError(f"page must contain at least one {source.title!r} heading")
    if parser.table_open_count != 1:
        raise CensusFinanceSourceDriftError("page must contain exactly one data flags table")

    codes: list[CensusFinanceCode] = []
    seen_codes: set[str] = set()
    section: str | None = None
    for ordinal, row in enumerate(parser.rows):
        if len(row) == 1:
            is_th, text = row[0]
            if not is_th:
                raise CensusFinanceSourceDriftError(
                    f"data flag row {ordinal} is a lone cell that is not a section header"
                )
            if text not in _DATA_FLAG_SECTIONS:
                raise CensusFinanceSourceDriftError(f"data flag section header {text!r} is not a known section")
            section = text
            continue
        if len(row) != 2:
            raise CensusFinanceSourceDriftError(f"data flag row {ordinal} must contain one or two cells")
        (code_is_th, code), (definition_is_th, definition) = row
        if code_is_th or definition_is_th:
            raise CensusFinanceSourceDriftError(f"data flag row {ordinal} cells must not be header cells")
        if section is None:
            raise CensusFinanceSourceDriftError(f"data flag row {ordinal} appears before any section header")
        if _DATA_FLAG_CODE.fullmatch(code) is None:
            raise CensusFinanceSourceDriftError(f"data flag row {ordinal} has a malformed code {code!r}")
        if not definition.strip():
            raise CensusFinanceSourceDriftError(f"data flag row {ordinal} has an empty definition")
        if code in seen_codes:
            raise CensusFinanceSourceDriftError(f"data flag code {code!r} is duplicated")
        seen_codes.add(code)
        codes.append(
            CensusFinanceCode(
                resource_name="censusDataFlagCodes",
                use="deterministicMetadata",
                publisher_label=definition,
                source_url=source.source_url,
                identifiers=(_make_identifier(value=code, kind="censusDataFlagCode", page=page),),
                section=section,
            )
        )

    if len(codes) != source.expected_count:
        raise CensusFinanceSourceDriftError(
            f"data flag code count drift: expected {source.expected_count}, parsed {len(codes)}"
        )

    return ParsedCensusFinanceResource(
        source=source,
        retrieved_at=page.pin.retrieved_at,
        source_sha256=page.sha256,
        source_byte_length=page.byte_length,
        codes=tuple(codes),
        gaps=CENSUS_FINANCE_PORTFOLIO_GAPS,
    )

def assemble_census_finance_portfolio(
    resources: Sequence[ParsedCensusFinanceResource],
) -> CensusFinancePortfolio:
    """Require both distinct Census resources and retain the mapping-only gaps."""

    by_name = {resource.source.resource_name: resource for resource in resources}
    expected_names = {"censusFunctionItemCodes", "censusDataFlagCodes"}
    if len(resources) != 2 or set(by_name) != expected_names:
        raise CensusFinanceSourceDriftError(
            "Census finance portfolio requires exactly the census function and data flag resources"
        )
    return CensusFinancePortfolio(
        census_function_item_codes=by_name["censusFunctionItemCodes"],
        census_data_flag_codes=by_name["censusDataFlagCodes"],
        gaps=CENSUS_FINANCE_PORTFOLIO_GAPS,
    )

