    raw_reference = mapping.get("state_budget_line_item")
    if not isinstance(raw_reference, str) or not raw_reference.strip():
        raise CensusFinanceMappingError("mapping must carry a non-empty state_budget_line_item reference")

    census_assignment: CensusFinanceMappingAssignment | None = None
    raw_function_code = mapping.get("census_function_item_code")
    if raw_function_code is not None:
        if not isinstance(raw_function_code, str):
            raise CensusFinanceMappingError("census_function_item_code must be a string")
        code = portfolio.census_function_item_codes.by_code().get(raw_function_code)
        if code is None:
            raise CensusFinanceMappingError(f"unknown Census function item code {raw_function_code!r}")
        census_assignment = _mapping_assignment("census_function_item_code", code)

    return ValidatedCensusFinanceMapping(
        state_native_reference=raw_reference,
        census_function_item=census_assignment,
        gaps=CENSUS_FINANCE_PORTFOLIO_GAPS,
    )

