            raise CFRListOfSubjectsError("CFR subject index source_url must not carry a query or fragment")
        if parsed.path != f"/federal-register/cfr/subject-title-{self.cfr_title:02d}.html":
            raise CFRListOfSubjectsError("CFR subject index source_url does not match its declared title")
        if _SHA256.fullmatch(self.expected_sha256) is None:
            raise CFRListOfSubjectsError("CFR subject index expected_sha256 must be sha256:<64 lowercase hex>")
        if self.expected_byte_length <= 0:
            raise CFRListOfSubjectsError("CFR subject index expected_byte_length must be positive")
        if not self.retrieved_at.endswith("Z"):
            raise CFRListOfSubjectsError("CFR subject index retrieved_at must be a UTC timestamp")
        if not (1 <= self.cfr_title <= 50):
            raise CFRListOfSubjectsError("CFR title must be between 1 and 50")
        if "current as of" not in self.revision_note:
            raise CFRListOfSubjectsError("CFR subject index revision note must record the publisher's revision date")

def __post_init__(self) -> None:
    parsed = urlsplit(self.source_url)
    if (
        parsed.scheme != "https"
        or parsed.hostname != "www.archives.gov"
        or parsed.username is not None
        or parsed.password is not None
    ):
        raise CFRListOfSubjectsError(
            "CFR subject index source_url must be the official credential-free archives.gov endpoint"
        )
    if parsed.query or parsed.fragment:
        raise CFRListOfSubjectsError("CFR subject index source_url must not carry a query or fragment")
    if parsed.path != f"/federal-register/cfr/subject-title-{self.cfr_title:02d}.html":
        raise CFRListOfSubjectsError("CFR subject index source_url does not match its declared title")
    if _SHA256.fullmatch(self.expected_sha256) is None:
        raise CFRListOfSubjectsError("CFR subject index expected_sha256 must be sha256:<64 lowercase hex>")
    if self.expected_byte_length <= 0:
        raise CFRListOfSubjectsError("CFR subject index expected_byte_length must be positive")
    if not self.retrieved_at.endswith("Z"):
        raise CFRListOfSubjectsError("CFR subject index retrieved_at must be a UTC timestamp")
    if not (1 <= self.cfr_title <= 50):
        raise CFRListOfSubjectsError("CFR title must be between 1 and 50")
    if "current as of" not in self.revision_note:
        raise CFRListOfSubjectsError("CFR subject index revision note must record the publisher's revision date")

def parse_cfr_subject_index(
    payload: bytes,
    *,
    pin: CfrSubjectIndexPin,
) -> tuple[CfrPartSubjects, ...]:
    """Parse one archives.gov subject-index page into publisher part assignments.

    Fail-closed in both directions. The payload must match the pin's digest
    and byte length exactly, and every ``<dt>`` that names a CFR citation must
    yield a title and a part or the parse raises -- an unmatched entry is
    never skipped. Entries whose declared title disagrees with the pin raise
    too, so a page fetched under the wrong title cannot be silently absorbed.
    """

    digest = sha256_digest(payload)
    if digest != pin.expected_sha256:
        raise CFRSourceDriftError(
            f"CFR subject index title {pin.cfr_title} digest {digest} does not match the pinned {pin.expected_sha256}"
        )
    if len(payload) != pin.expected_byte_length:
        raise CFRSourceDriftError(
            f"CFR subject index title {pin.cfr_title} is {len(payload)} bytes; pinned {pin.expected_byte_length}"
        )

    body = payload.decode("utf-8", errors="replace")
    parts: list[CfrPartSubjects] = []
    for match in _SUBJECT_DT_DD.finditer(body):
        entry = _subject_text(match.group("dt"))
        if not entry or "CFR" not in entry.upper():
            continue
        if entry.lower().startswith(_SUBJECT_LEAKED_TAG):
            entry = entry[len(_SUBJECT_LEAKED_TAG) :].lstrip()
        head = _SUBJECT_HEAD.match(entry)
        if head is None:
            raise CFRSourceDriftError(
                f"CFR subject index title {pin.cfr_title} has an unparsable part entry: {entry[:120]!r}"
            )
        declared_title = int(head.group("title"))
        if declared_title != pin.cfr_title:
            raise CFRSourceDriftError(
                f"CFR subject index for title {pin.cfr_title} contains a title {declared_title} entry"
            )
        # Fifth documented publisher irregularity, and the consequential one:
        # 32 part headings across 14 pages are marked up as <dd> rather than
        # <dt>. Left alone, the mistyped part vanishes AND its terms are
        # wrongly attributed to the part above it. Recover them as the part
        # headings they plainly are, rather than admitting them as terms.
        pending: list[tuple[str, str, list[str]]] = [
            (head.group("part").rstrip("."), head.group("heading").strip().rstrip("."), [])
        ]
        for raw_dd in _SUBJECT_DD.findall(match.group("dds")):
            value = _subject_text(raw_dd)
            if not value or value.upper() == "N/A":
                continue
            if value.lower().startswith(_SUBJECT_LEAKED_TAG):
                value = value[len(_SUBJECT_LEAKED_TAG) :].lstrip()
            nested = _SUBJECT_HEAD.match(value) if "CFR" in value.upper() else None
            if nested is not None and int(nested.group("title")) == declared_title:
                pending.append(
                    (
                        nested.group("part").rstrip("."),
                        nested.group("heading").strip().rstrip("."),
                        [],
                    )
                )
                continue
            pending[-1][2].append(value.rstrip("."))
        for part_number, heading, collected in pending:
            if not collected:
                continue
            parts.append(
                CfrPartSubjects(
                    cfr_title=declared_title,
                    cfr_part=part_number,
                    part_heading=heading,
                    terms=tuple(collected),
                )
            )
    if not parts and pin.cfr_title not in CFR_RESERVED_TITLES:
        raise CFRSourceDriftError(f"CFR subject index title {pin.cfr_title} yielded no part assignments")
    if parts and pin.cfr_title in CFR_RESERVED_TITLES:
        raise CFRSourceDriftError(
            f"CFR title {pin.cfr_title} is reserved but its subject index carries {len(parts)} parts"
        )
    return tuple(parts)

def cfr_list_of_subjects_assignment_evidence_bytes(
    parsed: FederalRegisterDocumentAssignments,
) -> bytes:
    """Serialize the source evidence deterministically."""

    return canonical_json(cfr_list_of_subjects_assignment_evidence(parsed)).encode("utf-8") + b"\n"

src/refspec/registry/citation_grammar.py.source_code:
def usc_title_is_possible(title: int | None) -> bool | None:
    """1-54, excluding never-enacted 53. None when there is no title to judge."""

    if title is None:
        return None
    return 1 <= title <= USC_TITLE_COUNT and title not in USC_RESERVED_TITLES

def states_nothing(text: object) -> bool:
    """Whether a field value is a placeholder rather than a statement."""

    value = _WRAPPING_QUOTES.sub("", str(text or ""))
    if value.casefold() in UNSTATED_SENTINELS:
        return True
    remainder, stripped = _ZERO_TITLE_LABEL.subn("", value, count=1)
    return bool(stripped) and (
        remainder.casefold() in UNSTATED_SENTINELS or _ALL_ZEROS.fullmatch(remainder) is not None
    )

def _part_is_plausible(part: str | None) -> bool | None:
    if part is None:
        return None
    return len([c for c in part if c.isdigit()]) <= _MAX_PLAUSIBLE_PART_DIGITS

def _canonical_part(part: str | None) -> str | None:
    """Strip leading zeros: the part is a JOIN KEY, and "0718" must meet "718"."""

    if part is None:
        return None
    return part.lstrip("0") or "0"

def _usc_section(value: str | None) -> str | None:
    """Lowercase a section token, drop subsection detail, strip a zero pad."""

    if value is None:
        return None
    text = re.sub(r"\([^)]*\)", "", value.strip().lower())
    return _ZERO_PADDED_SECTION.sub("", text) or None

def _statute_lettered_page(match: re.Match[str]) -> tuple[str, int]:
    """What a lettered Statutes page states, and the offset it accounts for.

    One page ("2763A-326") or a range of them ("2763A-326 to 2763A-328"), and
    the two answers travel together: the page text and the coverage end are
    the same decision seen twice, and computing them apart is how the end
    leaf came to be consumed without being carried.

    The ordering rule is the U.S.C. one, for the same reason — an end leaf
    that does not follow its start is not a range, and reading it either way
    would be an invention. A range whose end names a DIFFERENT base is
    declined on the same terms: "1501A" and "2763A" are appendices of
    different acts, and a span across them is not a span. A declined tail
    stays uncovered, so the row is partial and the characters remain visible.
    """

    base, leaf = match.group("base").upper(), match.group("leaf")
    end, end_base = match.group("leaf_end"), match.group("end_base")
    declined = (
        end is None or int(end) <= int(leaf) or (end_base is not None and end_base.upper() != base)
    )
    if declined:
        return f"{base}-{leaf}", match.end("leaf")
    return f"{base}-{leaf} to {base}-{end}", match.end("leaf_end")

def _spans_owning_their_comma(text: str) -> tuple[tuple[int, int], ...]:
    """Where a comma in ``text`` belongs to a date or an act name, not a list."""

    return tuple(
        match.span() for pattern in _COMMAS_THAT_BELONG_TO_A_NAME for match in pattern.finditer(text)
    )

def parse_eo_compilation_locators(text: str) -> tuple[EoCompilationLocator, ...]:
    """Read every Title 3 compilation locator, identifying nothing."""

    normalized = _normalize_dashes(text)
    return tuple(
        EoCompilationLocator(
            compilation_start=match.group("start"),
            compilation_end=_compilation_end(match),
            page=match.group("page"),
        )
        for match in _EO_COMPILATION.finditer(normalized)
    )

def _excise_compilations(text: str) -> str:
    """Blank out compilation locators so the CFR grammar cannot read them.

    "3 CFR, 1977 Comp., p. 123" is not a CFR citation, and left in place it
    parses as title 3, part 1977 — plausible on every axis and entirely
    fabricated. Spans are replaced with spaces so every other citation keeps
    its offsets.
    """

    def _blank(match: re.Match[str]) -> str:
        return " " * (match.end() - match.start())

    return _EO_COMPILATION.sub(_blank, text)

def _repair_whole_value_label(text: str) -> str:
    """Apply at most one named whole-value label repair, or return the text."""

    for pattern, replacement, _name in _WHOLE_VALUE_LABEL_REPAIRS:
        repaired, count = pattern.subn(replacement, text, count=1)
        if count:
            return repaired
    return text

def _longest_name_before(before: str, act_names: Container[str]) -> str | None:
    words = before.split()
    for length in range(min(_MAX_ACT_NAME_WORDS, len(words)), 0, -1):
        candidate = " ".join(words[-length:])
        if normalize_popular_name(candidate) in act_names:
            return _NAME_EDGE.sub("", candidate)
    return None

def _longest_name_after(after: str, act_names: Container[str]) -> str | None:
    # "Sec 1886(d) of the Social Security Act": the subsection parenthetical
    # sits between the section number and "of the", and requiring adjacency
    # silently failed every such citation — 25 of the commonest single form
    # alone. Parentheticals are skipped, bounded so a sentence in parentheses
    # is not.
    after = re.sub(r"^(?:\s*\([^()]{1,12}\))+", "", after)
    opening = _ACT_SECTION_OF_THE.match(after)
    if opening is None:
        return None
    words = after[opening.end() :].split()
    for length in range(min(_MAX_ACT_NAME_WORDS, len(words)), 0, -1):
        candidate = " ".join(words[:length])
        if normalize_popular_name(candidate) in act_names:
            return _NAME_EDGE.sub("", candidate)
    return None

def parse_supreme_court_citation(citation: object, source_url: object) -> SupremeCourtCitation:
    """Read a citation under the scheme its own source URL declares.

    The URL is the discriminator, not a heuristic over the citation text: the
    publisher serves a bound opinion from a volume-paginated filename and a
    slip opinion from a docket-numbered one. A citation whose shape disagrees
    with its URL is left unread rather than forced into either scheme.
    """

    text = "" if citation is None else str(citation).strip()
    url = "" if source_url is None else str(source_url)
    bound = _BOUND_OPINION_FILENAME.search(url) is not None
    if bound:
        match = _US_REPORTS_CITATION.match(text)
        if match is None:
            return SupremeCourtCitation(scheme="unread")
        return SupremeCourtCitation(
            scheme="us_reports",
            us_reports_volume=int(match.group("volume")),
            us_reports_page=int(match.group("page")),
        )
    match = _PRELIMINARY_PRINT_LOCATOR.match(text)
    if match is None:
        return SupremeCourtCitation(scheme="unread")
    return SupremeCourtCitation(
        scheme="preliminary_print",
        preliminary_print_volume=int(match.group("volume")),
        preliminary_print_part=int(match.group("part")),
    )

src/refspec/registry/claim_release_expor.source_code:
def _source_path(root: Path, filename: str) -> Path:
    path = root / filename
    if path.is_symlink() or not path.is_file():
        raise RegistryClaimReleaseError(
            f"pinned registry source is missing or unsafe: {path}"
        )
    return path

def _language_scope(extractions: tuple[RdfClaimExtraction, ...]) -> dict[str, object]:
    return {
        "included": ["en", "en-*", "untagged"],
        "mode": "englishOnly",
        "omittedBlankNodeClaimCount": sum(
            value.omitted_blank_node_claim_count for value in extractions
        ),
        "omittedNonEnglishLiteralCount": sum(
            value.omitted_non_english_literal_count for value in extractions
        ),
        "omittedUnsupportedTermCount": sum(
            value.omitted_unsupported_term_count for value in extractions
        ),
    }

def _limitations(extractions: tuple[RdfClaimExtraction, ...]) -> tuple[dict[str, str], ...]:
    result = [
        {
            "description": (
                "The release includes English and untagged literals; exact raw "
                "captures retain non-English literals outside the claim table."
            ),
            "id": ENGLISH_LIMITATION_ID,
        }
    ]
    if any(value.omitted_blank_node_claim_count for value in extractions):
        result.append(
            {
                "description": (
                    "RDF statements containing blank nodes remain in the pinned raw "
                    "capture because registry claims require durable IRI subjects and "
                    "IRI or literal objects."
                ),
                "id": RDF_BLANK_NODE_LIMITATION_ID,
            }
        )
    return tuple(sorted(result, key=lambda row: row["id"]))

def export_gemet_4_2_3_claim_release(
    source_root: Path,
    output: Path,
) -> RegistryClaimReleaseView:
    """Export the exact pinned, decompressed GEMET 4.2.3 RDF/XML release."""

    release = GEMET_RELEASE_4_2_3
    source_path = _source_path(source_root, GEMET_LOCAL_NAME)
    parsed = parse_gemet_file(
        source_path,
        source_url=release.source_url,
        expected_sha256=release.expected_sha256,
        expected_byte_length=release.expected_byte_length,
    )
    extraction = extract_rdf_claims(
        parse_rdf_graph(
            source_path.read_bytes(),
            rdf_format="xml",
            public_id=release.source_url,
        ),
        release_id=GEMET_CLAIM_RELEASE_ID,
        source_locator=release.source_url,
        source_digest=release.expected_sha256,
        logical_path=f"raw/{GEMET_LOCAL_NAME}",
        recipe_id=GEMET_RECIPE_ID,
    )
    counts = _predicate_counts(extraction.claims)
    mapping_count = sum(counts[predicate] for predicate in SKOS_MAPPING_PREDICATE_IRIS)
    expected = {
        "collectionMemberships": (str(SKOS.member), 16_178),
        "groupMemberships": (str(SKOS.inScheme), 5_651),
        "mappingRelations": ("mapping", 9_658),
        "subgroupRelations": (
            "http://www.eionet.europa.eu/gemet/2004/06/gemet-schema.rdf#subGroupOf",
            32,
        ),
    }
    observed = {
        name: mapping_count if predicate == "mapping" else counts[predicate]
        for name, (predicate, _count) in expected.items()
    }
    mismatches = {
        name: {"actual": observed[name], "expected": count}
        for name, (_predicate, count) in expected.items()
        if observed[name] != count
    }
    if mismatches:
        raise RegistryClaimReleaseError(
            f"GEMET claim release structure counts differ: {mismatches}"
        )
    return build_registry_claim_release(
        output,
        release_id=GEMET_CLAIM_RELEASE_ID,
        release_key="gemet-4.2.3",
        issued="2021-12-06",
        release_scope={
            "complete": True,
            "mode": "publisherRelease",
            "population": "GEMET 4.2.3 decompressed RDF/XML",
        },
        language_scope=_language_scope((extraction,)),
        recipes=(
            {
                "description": (
                    "Verify and parse the pinned decompressed RDF/XML; retain every "
                    "IRI claim and every English or untagged literal without "
                    "normalization."
                ),
                "id": GEMET_RECIPE_ID,
                "implementation": "refspec.registry.claim_release_exports",
                "version": "1.0",
            },
        ),
        limitations=_limitations((extraction,)),
        claims=extraction.claims,
        raw_inputs=(
            RegistryRawInput(
                path=source_path,
                logical_path=f"raw/{GEMET_LOCAL_NAME}",
                source_locator=release.source_url,
                role="decompressedPublisherSource",
            ),
        ),
        metadata={
            "attribution": release.attribution,
            "claimCount": len(extraction.claims),
            "collectionMembershipCount": observed["collectionMemberships"],
            "conceptCount": len(parsed.concepts),
            "groupMembershipCount": observed["groupMemberships"],
            "licenseIri": release.license_iri,
            "mappingRelationCount": observed["mappingRelations"],
            "publisher": release.publisher,
            "sourceTripleCount": extraction.source_triple_count,
            "subgroupRelationCount": observed["subgroupRelations"],
            "version": release.version,
        },
    )

src/refspec/registry/courtlistener_codes.source_code:
def sha256_digest(payload: bytes) -> str:
    """Return the canonical RefSpec SHA-256 spelling."""

    return "sha256:" + hashlib.sha256(payload).hexdigest()

def _validate_courtlistener_url(value: str, field: str) -> None:
    parsed = urlsplit(value)
    if parsed.scheme != "https" or parsed.hostname not in COURTLISTENER_HOSTS:
        raise CourtListenerAcquisitionError(f"{field} must be an official HTTPS courtlistener.com URL")
    if parsed.username is not None or parsed.password is not None:
        raise CourtListenerAcquisitionError(f"{field} must not contain credentials")

class CourtListenerJurisdictionsSnapshotPin:
    """Exact identity of one captured jurisdictions page."""

    source_url: str
    retrieved_at: str
    expected_sha256: str
    expected_byte_length: int

    def __post_init__(self) -> None:
        _validate_courtlistener_url(self.source_url, "source_url")
        if self.source_url != COURTLISTENER_JURISDICTIONS_URL:
            raise CourtListenerAcquisitionError("source_url must be the official Available Jurisdictions help page")
        if _DIGEST.fullmatch(self.expected_sha256) is None:
            raise CourtListenerAcquisitionError("expected_sha256 must be a lowercase sha256:<64 hex> digest")
        if self.expected_byte_length <= 0:
            raise CourtListenerAcquisitionError("expected_byte_length must be positive")
        if not self.retrieved_at.strip():
            raise CourtListenerAcquisitionError("retrieved_at must not be empty")

def __post_init__(self) -> None:
    _validate_courtlistener_url(self.source_url, "source_url")
    if self.source_url != COURTLISTENER_JURISDICTIONS_URL:
        raise CourtListenerAcquisitionError("source_url must be the official Available Jurisdictions help page")
    if _DIGEST.fullmatch(self.expected_sha256) is None:
        raise CourtListenerAcquisitionError("expected_sha256 must be a lowercase sha256:<64 hex> digest")
    if self.expected_byte_length <= 0:
        raise CourtListenerAcquisitionError("expected_byte_length must be positive")
    if not self.retrieved_at.strip():
        raise CourtListenerAcquisitionError("retrieved_at must not be empty")

class CourtListenerPageFetcher(Protocol):
    """Small transport boundary for the official jurisdictions help page."""

    def fetch(self, source_url: str, *, timeout_seconds: float) -> FetchedCourtListenerPage:
        """Fetch the page while preserving its exact body bytes."""

def _validate_html_payload(payload: bytes) -> None:
    lowered = payload[:64_000].lower()
    if any(marker in lowered for marker in _CHALLENGE_MARKERS):
        raise CourtListenerSourceDriftError(
            "courtlistener.com returned a challenge or interstitial page instead of the jurisdictions table"
        )
    if b"<html" not in lowered and b"<!doctype html" not in lowered:
        raise CourtListenerSourceDriftError("jurisdictions capture is not an HTML document")

def _verify_payload(
    payload: bytes,
    pin: CourtListenerJurisdictionsSnapshotPin,
    *,
    location: str,
) -> tuple[str, int]:
    _validate_html_payload(payload)
    byte_length = len(payload)
    if byte_length != pin.expected_byte_length:
        raise CourtListenerSourceDriftError(
            f"{location} byte length drift: expected {pin.expected_byte_length}, got {byte_length}"
        )
    actual_sha256 = sha256_digest(payload)
    if actual_sha256 != pin.expected_sha256:
        raise CourtListenerSourceDriftError(
            f"{location} digest drift: expected {pin.expected_sha256}, got {actual_sha256}"
        )
    return actual_sha256, byte_length

def acquire_courtlistener_jurisdictions_page(
    pin: CourtListenerJurisdictionsSnapshotPin,
    store_dir: Path,
    *,
    source_path: Path | None = None,
    fetcher: CourtListenerPageFetcher | None = None,
    timeout_seconds: float = 30.0,
) -> AcquiredCourtListenerJurisdictionsPage:
    """Acquire one exact jurisdictions page through a provider-neutral boundary."""

    if timeout_seconds <= 0:
        raise CourtListenerAcquisitionError("timeout_seconds must be positive")
    if source_path is not None and fetcher is not None:
        raise CourtListenerAcquisitionError("provide source_path or fetcher, not both")
    digest_hex = pin.expected_sha256.removeprefix("sha256:")
    final_path = Path(store_dir) / "sha256" / digest_hex / "courtlistener-jurisdictions.html"
    if final_path.exists() or final_path.is_symlink():
        return _verify_existing(final_path, pin)

    if source_path is not None:
        local_path = Path(source_path)
        if local_path.is_symlink() or not local_path.is_file():
            raise CourtListenerAcquisitionError(f"local jurisdictions source is not a regular file: {local_path}")
        return _publish_payload(
            local_path.read_bytes(),
            pin,
            final_path,
            content_type="text/html",
            acquisition_mode="local",
            resolved_url=None,
            local_source_path=local_path.resolve(),
        )

    if fetcher is None:
        raise CourtListenerAcquisitionError(
            "jurisdictions page is not cached; provide source_path or an injected fetcher"
        )
    fetched = fetcher.fetch(pin.source_url, timeout_seconds=timeout_seconds)
    if fetched.status_code != 200:
        raise CourtListenerAcquisitionError(f"could not acquire {pin.source_url}: HTTP {fetched.status_code}")
    _validate_resolved_url(fetched.resolved_url)
    media_type = fetched.content_type.partition(";")[0].strip().lower()
    if media_type not in {"text/html", "application/xhtml+xml"}:
        raise CourtListenerSourceDriftError(f"jurisdictions page content type drifted to {fetched.content_type!r}")
    return _publish_payload(
        fetched.body,
        pin,
        final_path,
        content_type=fetched.content_type,
        acquisition_mode="fetcher",
        resolved_url=fetched.resolved_url,
        local_source_path=None,
    )

class _JurisdictionsTableParser(HTMLParser):
    """Walk exactly one ``table.settings-table`` and collect its raw cell text.

    The parser never interprets any other part of the help page. It tracks a
    flat thead/tbody/tr/td state (no cell in this table nests another table),
    so any real structural change -- an added or removed column, a nested
    table, a missing ``tbody`` -- surfaces as a cell-count or header mismatch
    the caller rejects as drift rather than a silent parse.
    """

    def __init__(self) -> None:
        super().__init__(convert_charrefs=True)
        self.table_match_count = 0
        self.header_rows: list[list[str]] = []
        self.body_rows: list[list[str]] = []

        self._in_table = False
        self._in_thead = False
        self._in_tbody = False
        self._in_row = False
        self._in_cell = False
        self._cell_chunks: list[str] = []
        self._row_cells: list[str] = []

    def handle_starttag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
        attr_map = dict(attrs)
        if tag == "table":
            classes = frozenset((attr_map.get("class") or "").split())
            if {"settings-table", "table"}.issubset(classes):
                self.table_match_count += 1
                self._in_table = True
            return
        if not self._in_table:
            return
        if tag == "thead":
            self._in_thead = True
        elif tag == "tbody":
            self._in_tbody = True
        elif tag == "tr" and (self._in_thead or self._in_tbody):
            self._in_row = True
            self._row_cells = []
        elif tag in ("td", "th") and self._in_row:
            self._in_cell = True
            self._cell_chunks = []

    def handle_data(self, data: str) -> None:
        if self._in_cell:
            self._cell_chunks.append(data)

    def handle_endtag(self, tag: str) -> None:
        if not self._in_table:
            return
        if tag in ("td", "th") and self._in_cell:
            self._row_cells.append(_normalize_text(self._cell_chunks))
            self._in_cell = False
        elif tag == "tr" and self._in_row:
            if self._in_thead:
                self.header_rows.append(self._row_cells)
            elif self._in_tbody:
                self.body_rows.append(self._row_cells)
            self._in_row = False
        elif tag == "thead":
            self._in_thead = False
        elif tag == "tbody":
            self._in_tbody = False
        elif tag == "table":
            self._in_table = False

def handle_starttag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
    attr_map = dict(attrs)
    if tag == "table":
        classes = frozenset((attr_map.get("class") or "").split())
        if {"settings-table", "table"}.issubset(classes):
            self.table_match_count += 1
            self._in_table = True
        return
    if not self._in_table:
        return
    if tag == "thead":
        self._in_thead = True
    elif tag == "tbody":
        self._in_tbody = True
    elif tag == "tr" and (self._in_thead or self._in_tbody):
        self._in_row = True
        self._row_cells = []
    elif tag in ("td", "th") and self._in_row:
        self._in_cell = True
        self._cell_chunks = []

def handle_data(self, data: str) -> None:
    if self._in_cell:
        self._cell_chunks.append(data)

def handle_endtag(self, tag: str) -> None:
    if not self._in_table:
