def _canonical_json(value: object) -> bytes:
    return json.dumps(
        value,
        ensure_ascii=False,
        separators=(",", ":"),
        sort_keys=True,
    ).encode("utf-8")

def _require_nonempty_text(value: str | None, field: str) -> str:
    if value is None:
        raise IcpsrSubjectError(f"{field} is missing")
    text = value.strip()
    if not text:
        raise IcpsrSubjectError(f"{field} must not be empty")
    return text

