            observations=cast(
                tuple[Mapping[str, Any], ...],
                deep_freeze_json(rebuilt.observations),
            ),
            source_artifacts=cast(
                Mapping[str, bytes],
                deep_freeze_json(rebuilt.source_artifacts),
            ),
            logical_digest=logical_digest,
        )

