def _reconciliation_by_resource(
    packages: CRSSourcePackages,
) -> dict[str, CRSResourceReconciliation]:
    packages.require_reconciled()
    by_resource = {reconciliation.resource_name: reconciliation for reconciliation in packages.reconciliations}
    if len(by_resource) != len(packages.reconciliations) or set(by_resource) != {
        "legislativeSubjectTerms",
        "policyAreas",
    }:
        raise CRSIdentityError("CRS source-concept releases require one reconciliation for each source package")
    return by_resource

def _require_exact_reconciliation_binding(
    *,
    resource_name: str,
    source: SourceControlledResourceBundle,
    reconciliation: CRSResourceReconciliation,
) -> Mapping[str, Any]:
    manifest_id = source.resource_manifest.get("id")
    local_record_id_set_digest = source.coverage_report.get("localRecordIdSetDigest")
    local_record_content_set_digest = source.coverage_report.get("localRecordContentSetDigest")
    if reconciliation.resource_name != resource_name:
        raise CRSIdentityError(f"CRS {resource_name} reconciliation names another resource")
    if reconciliation.requires_human_review or reconciliation.status == "reviewRequired":
        raise CRSIdentityError(f"CRS {resource_name} reconciliation still requires human review")
    if reconciliation.current_manifest_id != manifest_id:
        raise CRSIdentityError(f"CRS {resource_name} reconciliation names the wrong source manifest")
    if reconciliation.current_local_record_id_set_digest != local_record_id_set_digest:
        raise CRSIdentityError(f"CRS {resource_name} reconciliation local-record identity digest drifted")
    if reconciliation.current_local_record_content_set_digest != local_record_content_set_digest:
        raise CRSIdentityError(f"CRS {resource_name} reconciliation local-record content digest drifted")
    return reconciliation.as_dict()

def _selected_observation_ids(
    source: SourceControlledResourceBundle,
    *,
    categories: frozenset[str],
) -> tuple[str, ...]:
    identifiers: list[str] = []
    for index, observation in enumerate(source.observations):
        category = observation.get("category")
        identifier = observation.get("id")
        if category in categories:
            if not isinstance(identifier, str) or not identifier:
                raise CRSIdentityError(f"CRS source observation {index} lacks an identifier")
            identifiers.append(identifier)
    if not identifiers:
        raise CRSIdentityError("CRS source-concept selection must contain at least one observation")
    if len(identifiers) != len(set(identifiers)):
        raise CRSIdentityError("CRS source observations repeat an identifier")
    return tuple(sorted(identifiers))

def _require_exact_categories(
    source: SourceControlledResourceBundle,
    *,
    expected: frozenset[str],
    resource_name: str,
) -> None:
    categories = {observation.get("category") for observation in source.observations}
    if categories != set(expected):
        raise CRSIdentityError(
            f"CRS {resource_name} categories changed: expected {sorted(expected)!r}, "
            f"received {sorted(str(value) for value in categories)!r}"
        )

def _build_release(
    source: SourceControlledResourceBundle,
    *,
    semantic_ring: SemanticRing,
    categories: frozenset[str],
    selection_policy: Mapping[str, str],
    reconciliation_record: Mapping[str, Any],
) -> SourceConceptReleaseBundle:
    selected_observation_ids = _selected_observation_ids(
        source,
        categories=categories,
    )
    selected_ids = frozenset(selected_observation_ids)
    selected_source_artifacts = {
        str(observation["sourceArtifact"]) for observation in source.observations if observation["id"] in selected_ids
    }
    return build_source_concept_release_bundle(
        source,
        semantic_ring=semantic_ring,
        selected_observation_ids=selected_observation_ids,
        selection_policy=selection_policy,
        rights_metadata=tuple(
            {
                "type": "RightsMetadata",
                "rightsStatus": "notStated",
                "sourceArtifact": source_artifact,
                "sourceDigest": sha256_digest(source.source_artifacts[source_artifact]),
            }
            for source_artifact in sorted(selected_source_artifacts)
        ),
        reconciliation_record=reconciliation_record,
    )

class CRSIdentityLink:
    """A human decision that two capture rows continue one local record."""

    current_observation_id: str
    previous_local_record_id: str
    reason: str

    def __post_init__(self) -> None:
        if not self.current_observation_id.strip() or not self.reason.strip():
            raise CRSIdentityError("CRS identity link observation and reason must not be empty")
        try:
            validate_uuid7_urn(
                self.previous_local_record_id,
                label="previous_local_record_id",
            )
        except SourceIdentityError as error:
            raise CRSIdentityError(str(error)) from error

    def as_dict(self) -> dict[str, str]:
        return {
            "currentObservationId": self.current_observation_id,
            "previousLocalRecordId": self.previous_local_record_id,
            "reason": self.reason,
        }

def __post_init__(self) -> None:
    if not self.current_observation_id.strip() or not self.reason.strip():
        raise CRSIdentityError("CRS identity link observation and reason must not be empty")
    try:
        validate_uuid7_urn(
            self.previous_local_record_id,
            label="previous_local_record_id",
        )
    except SourceIdentityError as error:
        raise CRSIdentityError(str(error)) from error

def as_dict(self) -> dict[str, str]:
    return {
        "currentObservationId": self.current_observation_id,
        "previousLocalRecordId": self.previous_local_record_id,
        "reason": self.reason,
    }

def __post_init__(self) -> None:
    try:
        review_uuid = validate_uuid7_urn(self.review_id, label="review_id")
        SourceCaptureEvent(
            fetch_id=review_uuid.removeprefix("urn:uuid:"),
            fetched_at=self.reviewed_at,
        )
    except SourceIdentityError as error:
        raise CRSIdentityError(f"CRS identity review is invalid: {error}") from error
    reviewer = urlsplit(self.reviewed_by)
    if not reviewer.scheme or reviewer.username is not None or reviewer.password is not None:
        raise CRSIdentityError("CRS identity review reviewed_by must be an absolute IRI")
    if not self.resource_name.strip() or not self.reason.strip():
        raise CRSIdentityError("CRS identity review resource and reason must not be empty")
    digest_hex = self.proposal_change_digest.removeprefix("sha256:")
    if (
        not self.proposal_change_digest.startswith("sha256:")
        or len(digest_hex) != 64
        or any(character not in "0123456789abcdef" for character in digest_hex)
    ):
        raise CRSIdentityError("CRS identity review must name a SHA-256 proposal digest")
    current_ids = [link.current_observation_id for link in self.identity_links]
    previous_ids = [link.previous_local_record_id for link in self.identity_links]
    if len(current_ids) != len(set(current_ids)) or len(previous_ids) != len(set(previous_ids)):
        raise CRSIdentityError("CRS identity review links must be one-to-one")

def as_dict(self) -> dict[str, Any]:
    return {
        "id": self.review_id,
        "resourceName": self.resource_name,
        "proposalChangeDigest": self.proposal_change_digest,
        "reviewedAt": self.reviewed_at,
        "reviewedBy": self.reviewed_by,
        "identityLinks": [link.as_dict() for link in self.identity_links],
        "reason": self.reason,
    }

class CRSSchemeAuthorityPin:
    """Pinned packaged bytes for one LoC subject-scheme authority record."""

    scheme: CRSSourceScheme
    retrieved_at: str
    fetch_id: str
    expected_sha256: str
    expected_byte_length: int
    packaged_filename: str

    def __post_init__(self) -> None:
        if not self.expected_sha256.startswith("sha256:") or len(self.expected_sha256) != 71:
            raise CRSSourceDriftError("LoC scheme authority pin must contain a SHA-256 digest")
        if self.expected_byte_length <= 0:
            raise CRSSourceDriftError("LoC scheme authority pin byte length must be positive")
        try:
            SourceCaptureEvent(fetch_id=self.fetch_id, fetched_at=self.retrieved_at)
        except SourceIdentityError as error:
            raise CRSSourceDriftError(f"LoC scheme authority fetch event is invalid: {error}") from error
        if Path(self.packaged_filename).name != self.packaged_filename:
            raise CRSSourceDriftError("LoC scheme authority packaged filename must be one path component")

def __post_init__(self) -> None:
    if not self.expected_sha256.startswith("sha256:") or len(self.expected_sha256) != 71:
        raise CRSSourceDriftError("LoC scheme authority pin must contain a SHA-256 digest")
    if self.expected_byte_length <= 0:
        raise CRSSourceDriftError("LoC scheme authority pin byte length must be positive")
    try:
        SourceCaptureEvent(fetch_id=self.fetch_id, fetched_at=self.retrieved_at)
    except SourceIdentityError as error:
        raise CRSSourceDriftError(f"LoC scheme authority fetch event is invalid: {error}") from error
    if Path(self.packaged_filename).name != self.packaged_filename:
        raise CRSSourceDriftError("LoC scheme authority packaged filename must be one path component")

class CRSSchemeAuthorityCapture:
    """One verified LoC scheme record and its exact response bytes."""

    pin: CRSSchemeAuthorityPin
    payload: bytes

    @property
    def source_artifact(self) -> str:
        """Return the official authority-record URL used as the artifact ID."""

        return self.pin.scheme.authority_record_url

    def manifest_descriptor(self) -> dict[str, str]:
        """Describe the scheme identity without promoting its terms."""

        return {
            "id": self.pin.scheme.scheme_iri,
            "code": self.pin.scheme.code,
            "label": self.pin.scheme.label,
            "sourceArtifact": self.source_artifact,
            "sourceFetchId": self.pin.fetch_id,
            "sourceObservedAt": self.pin.retrieved_at,
        }

def source_artifact(self) -> str:
    """Return the official authority-record URL used as the artifact ID."""

    return self.pin.scheme.authority_record_url

def manifest_descriptor(self) -> dict[str, str]:
    """Describe the scheme identity without promoting its terms."""

    return {
        "id": self.pin.scheme.scheme_iri,
        "code": self.pin.scheme.code,
        "label": self.pin.scheme.label,
