def canonical_json(value: object) -> str:
    """Serialize JSON deterministically for identifiers and comparisons."""
    return json.dumps(
        value,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
        allow_nan=False,
    )

