def _require_release_graph_validation_receipt(
    receipt: Mapping[str, Any],
) -> frozenset[str]:
    """Require one modeled, passing receipt from the combined release gate."""

    if receipt.get("type") != (
        "urn:ref:type:ReleaseGraphValidationReceipt"
    ):
        raise ReferenceRuntimeError(
            "managed vocabulary storage requires a "
            "ReleaseGraphValidationReceipt"
        )
    diagnostics = binding.validate([dict(receipt)])
    if diagnostics:
        raise ReferenceRuntimeError(
            "ReleaseGraphValidationReceipt fails REF JSON Binding 1.0: "
            + " | ".join(
                diagnostic.render() for diagnostic in diagnostics
            )
        )
    require_payload_digest(receipt)
    if receipt.get("operationalState") != "passed":
        raise ReferenceRuntimeError(
            "ReleaseGraphValidationReceipt is not passed"
        )
    verdicts = receipt.get("verdicts")
    if (
        not isinstance(verdicts, Mapping)
        or not verdicts
        or any(value != "pass" for value in verdicts.values())
    ):
        raise ReferenceRuntimeError(
            "managed vocabulary storage requires every modeled release-gate "
            "verdict to pass"
        )
    covered = receipt.get("coveredRulespecIdentifiers")
    if not isinstance(covered, list) or any(
        not isinstance(value, str) for value in covered
    ):
        raise ReferenceRuntimeError(
            "ReleaseGraphValidationReceipt lacks covered Rulespec "
            "identifiers"
        )
    return frozenset(covered)

