def bind_ranked_candidates(
    ranked_concept_ids: Sequence[str],
    *,
    channel: str,
    concept_catalog: Mapping[str, Mapping[str, Any]],
    expression_ids_by_concept: Mapping[str, Sequence[str]],
) -> list[dict[str, Any]]:
    """Bind candidate-channel results to exact corpus and lookup lineage."""
    _require_text(channel, "channel")
    bound: list[dict[str, Any]] = []
    for rank, concept_id in enumerate(ranked_concept_ids, start=1):
        catalog = concept_catalog.get(concept_id)
        if catalog is None:
            raise ReferenceRuntimeError(f"candidate {concept_id!r} is absent from the pinned catalog")
        expressions = tuple(expression_ids_by_concept.get(concept_id, ()))
        if not expressions:
            raise ReferenceRuntimeError(f"candidate {concept_id!r} has no indexed expression lineage")
        text_fields = (
            "conceptIri",
            "schemeIri",
            "facet",
        )
        for key in text_fields:
            _require_text(catalog.get(key), f"catalog[{concept_id}].{key}")
        references: dict[str, Mapping[str, Any]] = {}
        for key, versioned in (
            ("referenceResourceRelease", True),
            ("registryImportSnapshot", False),
            ("expressionCorpusSnapshot", False),
            ("lookupIndexManifest", False),
        ):
            reference = _require_mapping(
                catalog.get(key),
                f"catalog[{concept_id}].{key}",
            )
            _require_reference(
                reference,
                f"catalog[{concept_id}].{key}",
                versioned=versioned,
            )
            references[key] = reference
        if (
            references["expressionCorpusSnapshot"]["id"]
            == references["lookupIndexManifest"]["id"]
        ):
            raise ReferenceRuntimeError(
                f"candidate {concept_id!r} conflates expressionCorpusSnapshot "
                "with lookupIndexManifest"
            )
        bound.append(
            {
                "conceptId": concept_id,
                **{key: catalog[key] for key in text_fields},
                **{
                    key: dict(reference)
                    for key, reference in references.items()
                },
                "indexedExpressionIds": list(expressions),
                "channel": channel,
                "rank": rank,
            }
        )
    return bound

