def _legacy_iri(
    value: object,
    *,
    namespace: str,
) -> str:
    text = _require_text(value, "legacy identity")
    if urlsplit(text).scheme:
        return text
    # This is a quarantine identifier, not a newly minted registered concept.
    return f"{namespace}{text}"

