class ReferenceRuntimeStore:
    """Small immutable file store for normalized rows and REF records."""

    root: Path

    def write_migration_vocabulary_rows(
        self,
        *,
        labels: Sequence[ConceptLabel],
        relations: Sequence[ConceptRelation],
        participants: Sequence[ConceptEventParticipant],
        release_membership: Mapping[str, Mapping[str, Any]] | None = None,
    ) -> Mapping[str, Path]:
        """Write the retired fixed-path layout for an explicit migration test."""

        assert_managed_vocabulary_row_integrity(
            labels,
            relations,
            participants,
            release_membership=release_membership,
        )
        paths = {
            "concept_labels": self.root / "concept_labels.parquet",
            "concept_relations": self.root / "concept_relations.parquet",
            "concept_event_participants": (
                self.root / "concept_event_participants.parquet"
            ),
        }
        if any(path.exists() for path in paths.values()):
            raise ReferenceRuntimeError(
                "migration vocabulary rows are write-once and cannot be overwritten"
            )
        write_parquet_rows(
            paths["concept_labels"],
            columns=CONCEPT_LABEL_COLUMNS,
            rows=(row.to_row() for row in labels),
        )
        write_parquet_rows(
            paths["concept_relations"],
            columns=CONCEPT_RELATION_COLUMNS,
            rows=(row.to_row() for row in relations),
        )
        write_parquet_rows(
            paths["concept_event_participants"],
            columns=CONCEPT_EVENT_PARTICIPANT_COLUMNS,
            rows=(row.to_row() for row in participants),
        )
        return paths

    def write_vocabulary_rows(
        self,
        *,
        release_digest: str,
        release_graph_validation_receipt: Mapping[str, Any],
        labels: Sequence[ConceptLabel],
        relations: Sequence[ConceptRelation],
        participants: Sequence[ConceptEventParticipant],
        release_membership: Mapping[str, Mapping[str, Any]] | None = None,
    ) -> Mapping[str, Path]:
        """Persist rows only after the exact combined graph gate passed."""

        covered = _require_release_graph_validation_receipt(
            release_graph_validation_receipt
        )
        release_iris = {
            row.release_iri for row in (*labels, *relations, *participants)
        }
        missing_releases = release_iris - covered
        if missing_releases:
            raise ReferenceRuntimeError(
                "ReleaseGraphValidationReceipt does not cover row releases "
                f"{sorted(missing_releases)!r}"
            )
        assert_managed_vocabulary_row_integrity(
            labels,
            relations,
            participants,
            release_membership=release_membership,
        )
        normalized_release_digest = _require_digest(
            release_digest,
            "release_digest",
        )
        release_directory = (
            self.root
            / "releases"
            / normalized_release_digest.removeprefix("sha256:")
        )
        self.root.mkdir(parents=True, exist_ok=True)
        paths = {
            "concept_labels": release_directory / "concept_labels.parquet",
            "concept_relations": release_directory / "concept_relations.parquet",
            "concept_event_participants": (
                release_directory / "concept_event_participants.parquet"
            ),
            "release_graph_validation_receipt": (
                release_directory / "release_graph_validation_receipt.json"
            ),
        }
        existing = {name: path.is_file() for name, path in paths.items()}
        if any(existing.values()):
            if not all(existing.values()):
                raise ReferenceRuntimeError(
                    "immutable release row set is incomplete and cannot be overwritten"
                )
            actual = self.read_vocabulary_rows(
                release_digest=normalized_release_digest
            )
            expected = {
                "concept_labels": [row.to_row() for row in labels],
                "concept_relations": [row.to_row() for row in relations],
                "concept_event_participants": [
                    row.to_row() for row in participants
                ],
            }
            if actual != expected:
                raise ReferenceRuntimeError(
                    "release digest is already bound to different vocabulary rows"
                )
            expected_receipt = (
                canonical_json(dict(release_graph_validation_receipt))
                + "\n"
            )
            if (
                paths["release_graph_validation_receipt"].read_text(
                    encoding="utf-8"
                )
                != expected_receipt
            ):
                raise ReferenceRuntimeError(
                    "release digest is already bound to a different "
                    "ReleaseGraphValidationReceipt"
                )
            return paths
        write_parquet_rows(
            paths["concept_labels"],
            columns=CONCEPT_LABEL_COLUMNS,
            rows=(row.to_row() for row in labels),
        )
        write_parquet_rows(
            paths["concept_relations"],
            columns=CONCEPT_RELATION_COLUMNS,
            rows=(row.to_row() for row in relations),
        )
        write_parquet_rows(
            paths["concept_event_participants"],
            columns=CONCEPT_EVENT_PARTICIPANT_COLUMNS,
            rows=(row.to_row() for row in participants),
        )
        paths["release_graph_validation_receipt"].write_text(
            canonical_json(dict(release_graph_validation_receipt)) + "\n",
            encoding="utf-8",
        )
        return paths

    def read_vocabulary_rows(
        self,
        *,
        release_digest: str | None = None,
    ) -> Mapping[str, list[dict[str, Any]]]:
        directory = self.root
        if release_digest is not None:
            directory = (
                self.root
                / "releases"
                / _require_digest(
                    release_digest,
                    "release_digest",
                ).removeprefix("sha256:")
            )
        rows = {
            name: read_parquet_rows(directory / f"{name}.parquet")
            for name in (
                "concept_labels",
                "concept_relations",
                "concept_event_participants",
            )
        }
        for name in (
            "concept_labels",
            "concept_relations",
            "concept_event_participants",
        ):
            for row in rows[name]:
                migration = str(row.get("migration_only") or "").casefold()
                if migration not in {"true", "false"}:
                    raise ReferenceRuntimeError(f"{name}.migration_only must be true or false")
                row["migration_only"] = migration == "true"
        for row in rows["concept_event_participants"]:
            complete = str(row.get("complete_membership") or "").casefold()
            if complete not in {"true", "false"}:
                raise ReferenceRuntimeError("concept_event_participants.complete_membership must be true or false")
            row["complete_membership"] = complete == "true"
            ordinal = str(row.get("ordinal") or "").strip()
            if not ordinal.isdigit():
                raise ReferenceRuntimeError("concept_event_participants.ordinal must be a non-negative integer")
            row["ordinal"] = int(ordinal)
        return rows

    def put_record(
        self,
        record_type: str,
        payload: Mapping[str, Any],
        *,
        binding_validator: Callable[
            [Sequence[Mapping[str, Any]]],
            None,
        ]
        | None = None,
        linked_records: Sequence[Mapping[str, Any]] = (),
        digest_field: str | None = None,
    ) -> Path:
        """Persist one validated, content-addressed immutable REF record.

        The explicit validator receives the record plus every linked record
        needed for REF JSON Binding graph checks.  Requiring it here prevents a
        digest-correct but schema-invalid mapping from entering the immutable
        store.
        """
        expected_type = REF_RECORD_TYPES.get(record_type)
        if expected_type is None:
            raise ReferenceRuntimeError("record_type must name a supported REF JSON Binding record")
        actual_type = _require_iri(payload.get("type"), "record.type")
        if actual_type != expected_type:
            raise ReferenceRuntimeError(
                f"record_type {record_type!r} requires payload type {expected_type!r}, got {actual_type!r}"
            )
        if binding_validator is None:
            raise ReferenceRuntimeError("put_record requires an explicit REF JSON Binding validator")
        reject_legacy_conforming_payload(payload)
        require_payload_digest(payload, digest_field=digest_field)
        bundle = (*linked_records, payload)
        try:
            binding_validator(bundle)
        except ReferenceRuntimeError:
            raise
        except Exception as exc:
            raise ReferenceRuntimeError(f"REF JSON Binding validator rejected the record bundle: {exc}") from exc
        record_id = _require_text(payload.get("id"), "record.id")
        resolved_digest_field = digest_field or (
            "contentDigest"
            if payload.get("type")
            in {
                "urn:ref:type:EnrichmentProfile",
                "urn:ref:type:OutputProfile",
            }
            else "canonicalPayloadDigest"
        )
        if (
            expected_type
            == "urn:ref:type:PublicationReleaseManifest"
            and (
                payload.get("releaseState") == "complete"
                or payload.get("consumerEligible") is True
            )
        ):
            receipts = [
                record
                for record in linked_records
                if record.get("type")
                == "urn:ref:type:ReleaseGraphValidationReceipt"
            ]
            if len(receipts) != 1:
                raise ReferenceRuntimeError(
                    "a complete publication release requires exactly one "
                    "gate-issued ReleaseGraphValidationReceipt"
                )
            _require_release_graph_validation_receipt(receipts[0])
            publication_reference = {
                "id": _require_iri(payload.get("id"), "record.id"),
                "digest": str(payload[resolved_digest_field]),
            }
            validated_records = receipts[0].get("refRecordDigests")
            if (
                not isinstance(validated_records, list)
                or publication_reference not in validated_records
            ):
                raise ReferenceRuntimeError(
                    "ReleaseGraphValidationReceipt does not cover the exact "
                    "publication release"
                )
            if receipts[0].get("rulespecGraph") != payload.get(
                "rulespecReleaseGraph"
            ):
                raise ReferenceRuntimeError(
                    "ReleaseGraphValidationReceipt does not bind the "
                    "publication's exact Rulespec graph"
                )
        digest = str(payload[resolved_digest_field]).removeprefix("sha256:")
        safe_id = re.sub(r"[^A-Za-z0-9_.-]+", "_", record_id)
        directory = self.root / "records" / record_type
        directory.mkdir(parents=True, exist_ok=True)
        path = directory / f"{safe_id}-{digest}.json"
        encoded = (
            json.dumps(
                dict(payload),
                ensure_ascii=False,
                sort_keys=True,
                indent=2,
                allow_nan=False,
            )
            + "\n"
        )
        if path.exists():
            if path.read_text(encoding="utf-8") != encoded:
                raise ReferenceRuntimeError(f"immutable record path already contains different bytes: {path}")
            return path
        for existing_path in directory.glob("*.json"):
            try:
                existing_record = json.loads(
                    existing_path.read_text(encoding="utf-8")
                )
            except (OSError, json.JSONDecodeError) as exc:
                raise ReferenceRuntimeError(
                    f"immutable record store contains unreadable bytes: {existing_path}"
                ) from exc
            if (
                isinstance(existing_record, Mapping)
                and existing_record.get("id") == record_id
            ):
                raise ReferenceRuntimeError(
                    f"stable record id {record_id!r} is already bound to "
                    "different content"
                )
        path.write_text(encoded, encoding="utf-8")
        return path

def write_vocabulary_rows(
    self,
