def label_node_iri(resource: str, *, value: str, role: str, language: str, source_path: str) -> URIRef:
    """Mint the producer's ``urn:ref:atlas-label:<hex>`` IRI for one label row."""

    digest = ATLAS_VALIDATE.canonical_sha256(
        {
            "language": language,
            "resource": resource,
