def _module_name_for_path(path: Path) -> str:
    relative = path.relative_to(ROOT / "src").with_suffix("")
    parts = list(relative.parts)
    if parts[-1] == "__init__":
        parts.pop()
    return ".".join(parts)

tools/generate_atlas_v3_full.py::_projec.source_code:
def _project_imports(path: Path) -> frozenset[str]:
    """Read local import edges from one Python module without executing it."""

    module_name = _module_name_for_path(path)
    package_parts = module_name.split(".")[:-1]
    imports: set[str] = set()
    tree = ast.parse(path.read_bytes(), filename=str(path))
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            imports.update(alias.name for alias in node.names if alias.name.startswith("refspec"))
            continue
        if not isinstance(node, ast.ImportFrom):
            continue
        if node.level:
            keep = len(package_parts) - (node.level - 1)
            if keep < 0:
                continue
            base_parts = package_parts[:keep]
            if node.module:
                base_parts.extend(node.module.split("."))
            base = ".".join(base_parts)
        else:
            base = node.module or ""
        if not base.startswith("refspec"):
            continue
        imports.add(base)
        for alias in node.names:
            if alias.name != "*":
                imports.add(f"{base}.{alias.name}")
    return frozenset(imports)

