def _require_absolute_iri(value: object, *, context: str) -> str:
    if not isinstance(value, str) or ATLAS_VALIDATE.ABSOLUTE_IRI_RE.fullmatch(value) is None:
        raise ValueError(f"{context} must be an absolute IRI")
    return value

