def _atlas_local_name(value: Any, *, context: str) -> str:
    iri = str(value)
    namespace = str(ATLAS)
    if not iri.startswith(namespace) or len(iri) == len(namespace):
        raise ValueError(f"{context} is not an Atlas vocabulary term: {iri}")
    return iri[len(namespace) :]

