def _reject_duplicate_keys(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
    value: dict[str, Any] = {}
    for key, item in pairs:
        if key in value:
            _fail(f"duplicate JSON key {key!r}")
        value[key] = item
    return value

def load_json(path: Path) -> Mapping[str, Any]:
    """Load one JSON object while rejecting duplicate object keys."""

    try:
        value = json.loads(path.read_text(encoding="utf-8"), object_pairs_hook=_reject_duplicate_keys)
    except (OSError, UnicodeDecodeError, json.JSONDecodeError) as error:
        raise RegistryDescriptorError(f"cannot load {path}: {error}") from error
    if not isinstance(value, Mapping):
        _fail(f"{path} must contain a JSON object")
    return value

def canonical_json_bytes(value: Any) -> bytes:
    """Return the platform's compact, key-sorted UTF-8 JSON encoding."""

    return json.dumps(
        value,
        ensure_ascii=False,
        allow_nan=False,
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")

def _string(value: Any, location: str) -> str:
    if not isinstance(value, str) or not value or value != value.strip():
        _fail(f"{location} must be a non-empty trimmed string")
    return value

def _digest(value: Any, location: str) -> str:
    result = _string(value, location)
    if not _DIGEST.fullmatch(result):
        _fail(f"{location} must be a lowercase SHA-256 digest")
    return result

def _list(value: Any, location: str) -> Sequence[Any]:
    if isinstance(value, (str, bytes)) or not isinstance(value, Sequence):
        _fail(f"{location} must be a list")
    return value

def _verify_embedded_digest(
    document: Mapping[str, Any],
    *,
    digest_field: str,
    identity_field: str | None,
    identity_prefix: str | None,
    location: str,
) -> str:
    claimed = _digest(document.get(digest_field), f"{location}.{digest_field}")
    excluded = {digest_field}
    if identity_field is not None:
        excluded.add(identity_field)
    basis = {key: value for key, value in document.items() if key not in excluded}
    actual = canonical_sha256(basis)
    if claimed != actual:
        _fail(f"{location}.{digest_field} differs: claimed={claimed}, actual={actual}")
    if identity_field is not None:
        if identity_prefix is None:
            _fail(f"{location} identity prefix is not configured")
        expected_identity = identity_prefix + claimed.removeprefix("sha256:")
        # Catalog and index use stable identities derived from their semantic digest.
        actual_identity = _string(document.get(identity_field), f"{location}.{identity_field}")
        if actual_identity != expected_identity:
            _fail(f"{location}.{identity_field} differs: expected={expected_identity}, actual={actual_identity}")
    return claimed

def _validated_inputs(
    catalog: Mapping[str, Any],
    index: Mapping[str, Any],
    profiles: Mapping[str, Any],
) -> tuple[
    dict[str, Mapping[str, Any]],
    dict[str, str],
    dict[str, frozenset[str]],
    dict[str, set[str]],
    dict[str, str],
]:
    catalog_digest = _verify_embedded_digest(
        catalog,
        digest_field="catalogDigest",
        identity_field="catalogId",
        identity_prefix="urn:ref:resource-catalog:",
        location="resource catalog",
    )
    index_digest = _verify_embedded_digest(
        index,
        digest_field="indexDigest",
        identity_field="indexId",
        identity_prefix="urn:ref:atlas-index:",
        location="atlas index",
    )
    profile_digest = _verify_embedded_digest(
        profiles,
        digest_field="profileDigest",
        identity_field=None,
        identity_prefix=None,
        location="registry resource profiles",
    )
    if index.get("resourceCatalogDigest") != catalog_digest:
        _fail("atlas index does not pin the supplied resource catalog digest")
    if profiles.get("format") != PROFILE_FORMAT or profiles.get("schemaVersion") != SCHEMA_VERSION:
        _fail("registry resource profiles must use the Atlas 3.1 profile format")
    if profiles.get("namespace") != str(ATLAS):
        _fail(f"registry resource profiles must use namespace {ATLAS}")

    profile_for_kind: dict[str, str] = {}
    rings_for_profile: dict[str, frozenset[str]] = {}
    profile_rows = _list(profiles.get("profiles"), "registry resource profiles.profiles")
    for position, raw_profile in enumerate(profile_rows):
        location = f"registry resource profiles.profiles[{position}]"
        if not isinstance(raw_profile, Mapping):
            _fail(f"{location} must be an object")
        profile = _string(raw_profile.get("profile"), f"{location}.profile")
        if profile not in RESOURCE_PROFILES:
            _fail(f"{location}.profile is unsupported: {profile!r}")
        if profile in rings_for_profile:
            _fail(f"duplicate registry resource profile {profile!r}")
        rings = frozenset(
            _string(value, f"{location}.applicableSemanticRings[{index}]")
            for index, value in enumerate(
                _list(raw_profile.get("applicableSemanticRings"), f"{location}.applicableSemanticRings")
            )
        )
        if not rings <= SEMANTIC_RINGS:
            _fail(f"{location}.applicableSemanticRings contains unsupported values")
        rings_for_profile[profile] = rings
        for kind_position, value in enumerate(_list(raw_profile.get("resourceKinds"), f"{location}.resourceKinds")):
            kind = _string(value, f"{location}.resourceKinds[{kind_position}]")
            if kind in profile_for_kind:
                _fail(f"resource kind {kind!r} is assigned to more than one profile")
            profile_for_kind[kind] = profile
    if set(rings_for_profile) != RESOURCE_PROFILES:
        _fail(
            "registry resource profiles differ; "
            f"missing={sorted(RESOURCE_PROFILES - set(rings_for_profile))}, "
            f"extra={sorted(set(rings_for_profile) - RESOURCE_PROFILES)}"
        )

    resources: dict[str, Mapping[str, Any]] = {}
    catalog_kinds: set[str] = set()
    for position, raw_resource in enumerate(_list(catalog.get("resources"), "resource catalog.resources")):
        location = f"resource catalog.resources[{position}]"
        if not isinstance(raw_resource, Mapping):
            _fail(f"{location} must be an object")
        resource_id = _string(raw_resource.get("resourceId"), f"{location}.resourceId")
        if resource_id in resources:
            _fail(f"duplicate resource catalog resourceId {resource_id!r}")
        kind = _string(raw_resource.get("resourceKind"), f"{location}.resourceKind")
        _string(raw_resource.get("title"), f"{location}.title")
        if kind not in profile_for_kind:
            _fail(f"resource kind {kind!r} has no Atlas 3.1 profile")
        resources[resource_id] = raw_resource
        catalog_kinds.add(kind)
    if catalog_kinds != set(profile_for_kind):
        _fail(
            "profile resource-kind coverage differs from the catalog; "
            f"missing={sorted(catalog_kinds - set(profile_for_kind))}, "
            f"stale={sorted(set(profile_for_kind) - catalog_kinds)}"
        )

    rings_by_resource: dict[str, set[str]] = defaultdict(set)
    rows = _list(index.get("rows"), "atlas index.rows")
    for position, raw_row in enumerate(rows):
        location = f"atlas index.rows[{position}]"
        if not isinstance(raw_row, Mapping):
            _fail(f"{location} must be an object")
        resource_id = _string(raw_row.get("resourceId"), f"{location}.resourceId")
        if resource_id not in resources:
            _fail(f"{location}.resourceId {resource_id!r} is absent from the catalog")
        ring = _string(raw_row.get("semanticRing"), f"{location}.semanticRing")
        if ring not in SEMANTIC_RINGS:
            _fail(f"{location}.semanticRing is unsupported: {ring!r}")
        profile = profile_for_kind[str(resources[resource_id]["resourceKind"])]
        if ring not in rings_for_profile[profile]:
            _fail(f"{location} ring {ring!r} is not supported by profile {profile!r}")
        rings_by_resource[resource_id].add(ring)

    inputs = {
        "atlasIndexDigest": index_digest,
        "registryResourceProfilesDigest": profile_digest,
        "resourceCatalogDigest": catalog_digest,
    }
    return resources, profile_for_kind, rings_for_profile, rings_by_resource, inputs

def serialize_nquads(graph: Graph) -> bytes:
    """Serialize one graph as sorted, unique, blank-node-free N-Quads."""

    rows: list[str] = []
    for subject, predicate, obj in graph:
        if any(isinstance(term, BNode) for term in (subject, predicate, obj)):
            _fail("registry descriptor graph must not contain blank nodes")
        rows.append(nquads_line(subject, predicate, obj, GRAPH_IRI))
    if len(rows) != len(set(rows)):
        _fail("registry descriptor graph contains duplicate statements")
    return ("\n".join(sorted(rows)) + "\n").encode("utf-8")

def _arguments() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    mode = parser.add_mutually_exclusive_group()
    mode.add_argument("--check", action="store_true", help="verify checked artifacts (default)")
    mode.add_argument("--write", action="store_true", help="write the generated artifacts")
    return parser.parse_args()

tools/generate_crs_source_concept_releas.source_code:
def _plain(value: Any) -> Any:
    if isinstance(value, Mapping):
        return {str(key): _plain(child) for key, child in value.items()}
    if isinstance(value, (list, tuple)):
        return [_plain(child) for child in value]
    return value

def _canonical_bytes(value: object) -> bytes:
    from refspec.storage import canonical_json

    return (canonical_json(_plain(value)) + "\n").encode("utf-8")

def _release_items(releases: Any) -> tuple[tuple[str, str, str, Any], ...]:
    return (
        (
            "legislativeSubjects",
            "legislative-subjects",
            "subject",
            releases.legislative_subjects,
        ),
        (
            "legislativeEntities",
            "legislative-entities",
            "entity",
            releases.legislative_entities,
        ),
        ("policyAreas", "policy-areas", "subject", releases.policy_areas),
    )

def generated_files(releases: Any) -> dict[str, bytes]:
    """Return every checked path and byte from three release bundles."""

    files: dict[str, bytes] = {}
    for _name, path, _ring, release in _release_items(releases):
        for relative, payload in release.artifact_bytes().items():
            files[f"{path}/{relative}"] = payload
    files[EVIDENCE_FILE] = _canonical_bytes(_evidence(releases))
    return dict(sorted(files.items()))

def _actual_files(root: Path) -> dict[str, bytes]:
    if root.is_symlink() or not root.is_dir():
        raise CRSSourceConceptGenerationError(f"generated evidence directory is missing or unsafe: {root}")
    result: dict[str, bytes] = {}
    for item in root.rglob("*"):
        if item.is_symlink():
            raise CRSSourceConceptGenerationError(f"generated evidence contains a symlink: {item}")
        if item.is_file():
            result[item.relative_to(root).as_posix()] = item.read_bytes()
    return dict(sorted(result.items()))

def _compare_files(
    *,
    actual: Mapping[str, bytes],
    expected: Mapping[str, bytes],
    label: str,
) -> None:
    if set(actual) != set(expected):
        missing = sorted(set(expected) - set(actual))
        extra = sorted(set(actual) - set(expected))
        raise CRSSourceConceptGenerationError(f"{label} file set differs; missing={missing!r}, extra={extra!r}")
    changed = [path for path in expected if actual[path] != expected[path]]
    if changed:
        raise CRSSourceConceptGenerationError(f"{label} bytes differ for {changed!r}")

def _read_evidence(root: Path) -> Mapping[str, Any]:
    path = root / EVIDENCE_FILE
    if path.is_symlink() or not path.is_file():
        raise CRSSourceConceptGenerationError(f"generated evidence lacks {EVIDENCE_FILE}")
    payload = path.read_bytes()
    try:
        value = json.loads(payload)
    except (UnicodeDecodeError, json.JSONDecodeError) as error:
        raise CRSSourceConceptGenerationError(f"{EVIDENCE_FILE} must be valid UTF-8 JSON") from error
    if not isinstance(value, Mapping):
        raise CRSSourceConceptGenerationError(f"{EVIDENCE_FILE} must contain one object")
    if _canonical_bytes(value) != payload:
        raise CRSSourceConceptGenerationError(f"{EVIDENCE_FILE} bytes are not canonical")
    required = {
        "schemaVersion",
        "evidenceKind",
        "captureDate",
        "generator",
        "summary",
        "releases",
    }
    if set(value) != required or value.get("schemaVersion") != "1.0":
        raise CRSSourceConceptGenerationError(f"{EVIDENCE_FILE} shape or version is unsupported")
    if (
        value.get("evidenceKind") != "crsSourceConceptReleases"
        or value.get("captureDate") != "2026-07-30"
        or value.get("generator") != "tools/generate_crs_source_concept_releases.py"
    ):
        raise CRSSourceConceptGenerationError(f"{EVIDENCE_FILE} names another evidence product")
    return value

def _packages_from_views(views: Mapping[str, Any]) -> Any:
    from refspec.registry.packages.crs_source_packages import (
        CRSResourceReconciliation,
        CRSSourcePackages,
    )

    subjects = views["legislativeSubjects"]
    entities = views["legislativeEntities"]
    policy = views["policyAreas"]
    if subjects.source_bundle.artifact_bytes() != entities.source_bundle.artifact_bytes():
        raise CRSSourceConceptGenerationError(
            "legislative subject and entity releases do not share one exact source capture"
        )
    if (
        subjects.reconciliation_record is None
        or entities.reconciliation_record is None
        or policy.reconciliation_record is None
    ):
        raise CRSSourceConceptGenerationError("each CRS release must bind its exact reconciliation record")
    if _plain(subjects.reconciliation_record) != _plain(entities.reconciliation_record):
        raise CRSSourceConceptGenerationError("legislative subject and entity reconciliation records differ")
    legislative_reconciliation = CRSResourceReconciliation.from_dict(_plain(subjects.reconciliation_record))
    policy_reconciliation = CRSResourceReconciliation.from_dict(_plain(policy.reconciliation_record))
    packages = CRSSourcePackages(
        legislative_subject_terms=subjects.source_bundle,
        policy_areas=policy.source_bundle,
        reconciliations=(legislative_reconciliation, policy_reconciliation),
    )
    packages.require_reconciled()
    return packages

def releases_from_materialized(root: Path) -> Any:
    """Rebuild current release objects from externally pinned checked evidence."""

    from refspec.registry.packages.crs_source_concept_releases import (
        build_crs_source_concept_releases,
    )

    return build_crs_source_concept_releases(_packages_from_views(_open_materialized(root)))

def releases_from_capture_root(capture_root: Path) -> Any:
    """Build current releases from the exact retained Congress.gov pages."""

    from refspec.registry.packages.crs_source_concept_releases import (
        build_crs_source_concept_releases,
    )
    from refspec.registry.packages.crs_source_packages import (
        build_crs_source_packages_from_capture_root,
    )

    if capture_root.is_symlink() or not capture_root.is_dir():
        raise CRSSourceConceptGenerationError(f"retained CRS capture root is missing or unsafe: {capture_root}")
    packages = build_crs_source_packages_from_capture_root(capture_root)
    packages.require_reconciled()
    return build_crs_source_concept_releases(packages)

def _safe_output(path: Path) -> Path:
    absolute = path.absolute()
    if absolute == Path(absolute.anchor) or absolute.parent == absolute:
        raise CRSSourceConceptGenerationError("generated evidence output must not be a filesystem root")
    if absolute.is_symlink():
        raise CRSSourceConceptGenerationError("generated evidence output must not be a symlink")
    if absolute.exists() and not absolute.is_dir():
        raise CRSSourceConceptGenerationError("generated evidence output must be a directory path")
    return absolute

def write_materialized(output: Path, releases: Any) -> Path:
    """Atomically replace one generated evidence directory and verify it."""

    destination = _safe_output(output)
    destination.parent.mkdir(parents=True, exist_ok=True)
    temporary_parent = Path(
        tempfile.mkdtemp(
            prefix=f".{destination.name}-generate-",
            dir=destination.parent,
        )
    )
    staging = temporary_parent / "staging"
    staging.mkdir()
    backup_parent: Path | None = None
    try:
        for relative, payload in generated_files(releases).items():
            path = staging / relative
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_bytes(payload)
        check_materialized(staging, source_releases=releases)
        if destination.exists():
            backup_parent = Path(
                tempfile.mkdtemp(
                    prefix=f".{destination.name}-previous-",
                    dir=destination.parent,
                )
            )
            os.replace(destination, backup_parent / "previous")
        try:
            os.replace(staging, destination)
        except BaseException:
            if backup_parent is not None and (backup_parent / "previous").exists():
                os.replace(backup_parent / "previous", destination)
            raise
        if backup_parent is not None:
            shutil.rmtree(backup_parent)
            backup_parent = None
        check_materialized(destination, source_releases=releases)
        return destination
    finally:
        shutil.rmtree(temporary_parent, ignore_errors=True)
        if backup_parent is not None:
            if not destination.exists() and (backup_parent / "previous").exists():
                os.replace(backup_parent / "previous", destination)
            shutil.rmtree(backup_parent, ignore_errors=True)

def _selected_source(args: argparse.Namespace, *, for_write: bool) -> Any | None:
    if args.capture_root is not None:
        return releases_from_capture_root(args.capture_root)
    if args.source_evidence is not None:
        return releases_from_materialized(args.source_evidence)
    if DEFAULT_CAPTURE_ROOT.is_dir():
        return releases_from_capture_root(DEFAULT_CAPTURE_ROOT)
    if for_write:
        if args.output.is_dir():
            return releases_from_materialized(args.output)
        raise CRSSourceConceptGenerationError("--write needs the retained capture root or --source-evidence")
    return None

def _selection_line(releases: Any) -> str:
    return ", ".join(
        f"{name}={release.release_id} ({release.manifest_digest})"
        for name, _path, _ring, release in _release_items(releases)
    )

