def _publisher_source_scheme_subjects(view: PublisherView) -> frozenset[str]:
    """Return explicit and referenced publisher-native scheme IRIs."""
    return frozenset(
        {
            *view.schemes,
            *(scheme for _, scheme in view.memberships),
            *(scheme for _, scheme in view.top_concept_of),
            *(scheme for scheme, _ in view.has_top_concept),
        }
    )

def _select_publisher_concepts(
    view: PublisherView,
    included_concept_iris: frozenset[str],
) -> PublisherView:
    """Select an explicitly bounded concept capture without interpreting its fields."""
    if not included_concept_iris:
        return view
    missing = sorted(included_concept_iris - view.concepts)
    if missing:
        raise ValueError(f"included publisher concepts are absent from the pinned bytes: {missing}")

    concepts = included_concept_iris
    memberships = frozenset(row for row in view.memberships if row[0] in concepts)
    scheme_iris = {scheme for _, scheme in memberships}
    schemes = frozenset(scheme for scheme in view.schemes if scheme in scheme_iris)
    top_concept_of = frozenset(row for row in view.top_concept_of if row[0] in concepts)
    has_top_concept = frozenset(row for row in view.has_top_concept if row[1] in concepts)
    source_scheme_references = {
        *scheme_iris,
        *(scheme for _, scheme in top_concept_of),
        *(scheme for scheme, _ in has_top_concept),
    }
    resources = concepts | schemes | source_scheme_references

    def selected_literals(
        values: Mapping[str, frozenset[LiteralValue]],
    ) -> dict[str, frozenset[LiteralValue]]:
        return {subject: rows for subject, rows in values.items() if subject in resources}

    pref = selected_literals(view.pref_labels)
    alt = selected_literals(view.alt_labels)
    hidden = selected_literals(view.hidden_labels)
    resource_annotations = frozenset(row for row in view.resource_annotations if row[0] in resources)
    annotation_targets = frozenset(target for _, _, target in resource_annotations)
    retained_claim_subjects = resources | annotation_targets
    return PublisherView(
        concepts=concepts,
        schemes=schemes,
        pref_labels=pref,
        alt_labels=alt,
        hidden_labels=hidden,
        notations=selected_literals(view.notations),
        annotations=frozenset(row for row in view.annotations if row[0] in resources),
        resource_annotations=resource_annotations,
        resource_annotation_target_claim_counts={
            target: view.resource_annotation_target_claim_counts.get(target, 0)
            for subject, _, target in view.resource_annotations
            if subject in resources
        },
        literal_claims=frozenset(row for row in view.literal_claims if row[0] in retained_claim_subjects),
        iri_claims=frozenset(row for row in view.iri_claims if row[0] in retained_claim_subjects),
        reified_statements=frozenset(row for row in view.reified_statements if row.subject_iri in concepts),
        pref_label_count_all_languages=sum(len(values) for values in pref.values()),
        alt_label_count_all_languages=sum(len(values) for values in alt.values()),
        hidden_label_count_all_languages=sum(len(values) for values in hidden.values()),
        relations=frozenset(row for row in view.relations if row[0] in concepts),
        memberships=memberships,
        top_concept_of=top_concept_of,
        has_top_concept=has_top_concept,
        resource_predicate_counts={
            row: count for row, count in view.resource_predicate_counts.items() if row[0] in resources
        },
        defects=view.defects,
        resource_input_digests={
            resource: digests for resource, digests in view.resource_input_digests.items() if resource in resources
        },
        input_content_digests=view.input_content_digests,
        unevaluated_claims=view.unevaluated_claims,
        declared_out_of_scope_blank_node_claims=(view.declared_out_of_scope_blank_node_claims),
        declared_out_of_scope_subjects=view.declared_out_of_scope_subjects,
        resource_locators={
            resource: locator for resource, locator in view.resource_locators.items() if resource in resources
        },
        expected_native_payloads={
            resource: payload for resource, payload in view.expected_native_payloads.items() if resource in resources
        },
        expected_relation_payloads=view.expected_relation_payloads,
        expected_mapping_evidence=view.expected_mapping_evidence,
        resource_input_digest_values={
            resource: digest for resource, digest in view.resource_input_digest_values.items() if resource in resources
        },
        source_digest_is_native_payload_digest=(view.source_digest_is_native_payload_digest),
    )

def _json_without_duplicate_keys(payload: bytes, label: str) -> Any:
    """Parse UTF-8 JSON and reject duplicate object fields."""

    def reject_duplicates(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
        result: dict[str, Any] = {}
        for key, value in pairs:
            if key in result:
                raise ValueError(f"{label} repeats JSON field {key!r}")
            result[key] = value
        return result

    return json.loads(payload, object_pairs_hook=reject_duplicates)

def _canonical_json_bytes(value: Any) -> bytes:
    return json.dumps(
        value,
        ensure_ascii=False,
        allow_nan=False,
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")

def _required_text(value: Any, label: str) -> str:
    if not isinstance(value, str) or not value.strip():
        raise ValueError(f"{label} must be non-empty text")
    return value

def _mapping_rows(value: Any, label: str) -> list[Mapping[str, Any]]:
    if not isinstance(value, list) or any(not isinstance(row, Mapping) for row in value):
        raise ValueError(f"{label} must be an array of objects")
    return list(value)

def _single_pin(
    spec: SourceSpec,
    payloads: Mapping[SourcePin, bytes],
) -> tuple[SourcePin, bytes]:
    if len(spec.inputs) != 1:
        raise ValueError(f"{spec.name} requires exactly one publisher input")
    pin = spec.inputs[0]
    return pin, payloads[pin]

def _pin_with_role(
    spec: SourceSpec,
    payloads: Mapping[SourcePin, bytes],
    role: str,
) -> tuple[SourcePin, bytes]:
    matches = [(pin, payloads[pin]) for pin in spec.inputs if pin.role == role]
    if len(matches) != 1:
        raise ValueError(f"{spec.name} requires exactly one {role!r} input")
    return matches[0]

def _source_observation_id(
    *,
    resource_id: str,
    source_artifact: str,
    source_path: str,
    identifiers: Sequence[Mapping[str, Any]],
    package_version: str | None = None,
) -> str:
    identity: dict[str, Any] = {
        "resourceId": resource_id,
        "sourceArtifact": source_artifact,
        "sourcePath": source_path,
        "identifiers": [
            {
                "value": item["value"],
                "kind": item["kind"],
                "authorityUri": item["authorityUri"],
            }
            for item in identifiers
        ],
    }
    if package_version is not None:
        identity = {"packageVersion": package_version, **identity}
    digest = hashlib.sha256(_canonical_json_bytes(identity)).hexdigest()
    return f"urn:ref:source-observation:{resource_id}:{digest}"

def _html_fragment_text(value: str) -> str:
    """Return exact visible text from one bounded HTML fragment."""
    without_tags = re.sub(r"<[^>]+>", " ", value)
    return re.sub(r"\s+", " ", html.unescape(without_tags)).strip()

def _pattern_template_fields(template: str) -> frozenset[str]:
    """Return the named fields referenced by one bounded format template."""
    fields: set[str] = set()
    try:
        parsed = string.Formatter().parse(template)
        for _, field_name, _, _ in parsed:
            if field_name is None:
                continue
            if not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", field_name):
                raise ValueError(f"pattern-row template field must be one plain name: {field_name!r}")
            fields.add(field_name)
    except ValueError as error:
        raise ValueError(f"invalid pattern-row template {template!r}: {error}") from error
    return frozenset(fields)

def _render_pattern_text(template: str, fields: Mapping[str, Any]) -> str:
    """Render one text template and reject missing or non-scalar values."""
    try:
        value = template.format_map(fields)
    except (KeyError, ValueError) as error:
        raise ValueError(f"could not render pattern-row template {template!r}: {error}") from error
    if not isinstance(value, str):  # pragma: no cover - str.format_map promises text
        raise ValueError(f"pattern-row template did not render text: {template!r}")
    return value

def _render_pattern_value(value: Any, fields: Mapping[str, Any]) -> Any:
    """Render a JSON-shaped value while preserving whole-field JSON types."""
    if isinstance(value, str):
        exact = _EXACT_PATTERN_FIELD.fullmatch(value)
        if exact is not None:
            field_name = exact.group(1)
            if field_name not in fields:
                raise ValueError(f"pattern-row template names unknown field {field_name!r}")
            return fields[field_name]
        return _render_pattern_text(value, fields)
    if isinstance(value, list):
        return [_render_pattern_value(item, fields) for item in value]
    if isinstance(value, Mapping):
        return {str(key): _render_pattern_value(child, fields) for key, child in value.items()}
    return value

def _pattern_json_template_fields(template_json: str, label: str) -> frozenset[str]:
    """Parse a JSON template and return every referenced row field."""
    try:
        value = _json_without_duplicate_keys(template_json.encode("utf-8"), label)
    except (UnicodeError, ValueError) as error:
        raise ValueError(f"{label} is not valid JSON: {error}") from error
    fields: set[str] = set()

    def visit(item: Any) -> None:
        if isinstance(item, str):
            fields.update(_pattern_template_fields(item))
        elif isinstance(item, list):
            for child in item:
                visit(child)
        elif isinstance(item, Mapping):
            for child in item.values():
                visit(child)

    visit(value)
    return frozenset(fields)

def _normalize_pattern_field(value: Any, operation: str, label: str) -> Any:
    """Apply one stock, source-independent field normalization."""
    if operation == "none-if-empty":
        if value is None or (isinstance(value, str) and not value):
            return None
        return value
    if operation.startswith("none-if-equals:"):
        sentinel = operation.removeprefix("none-if-equals:")
        return None if value == sentinel else value
    if operation == "presence-boolean":
        return value is not None
    if operation.startswith("boolean-values:"):
        try:
            true_value, false_value = operation.removeprefix("boolean-values:").split(":", 1)
        except ValueError as error:
            raise ValueError(f"{label} boolean-values normalization requires true and false text") from error
        if value == true_value:
            return True
        if value == false_value:
            return False
        raise ValueError(f"{label} expected {true_value!r} or {false_value!r}, observed {value!r}")
    if not isinstance(value, str):
        raise ValueError(f"{label} normalization {operation!r} requires text, observed {type(value).__name__}")
    if operation == "strip":
        return value.strip()
    if operation == "rstrip":
        return value.rstrip()
    if operation.startswith("rstrip-chars:"):
        characters = operation.removeprefix("rstrip-chars:")
        if not characters:
            raise ValueError(f"{label} rstrip-chars normalization has no characters")
        return value.rstrip(characters)
    if operation == "collapse-whitespace":
        return " ".join(value.split())
    if operation == "html-visible-text":
        return _html_fragment_text(value)
    if operation == "remove-html-sup":
        return re.sub(r"<sup\b[^>]*>.*?</sup>", "", value, flags=re.DOTALL)
    if operation == "html-unescape":
        return html.unescape(value)
    if operation == "markdown-bold":
        match = re.fullmatch(r"\*\*(.+)\*\*", value.strip())
        if match is None:
            raise ValueError(f"{label} is not one bold Markdown value: {value!r}")
        return match.group(1).strip()
    if operation == "casefold":
        return value.casefold()
    if operation == "integer":
        try:
            return int(value)
        except ValueError as error:
            raise ValueError(f"{label} is not an integer: {value!r}") from error
    raise ValueError(f"{label} declares unsupported normalization {operation!r}")

def _fixed_width_layout_column(value: Any, label: str) -> str:
    """Read one declared column from a bounded fixed-width row block."""
    required = {
        "block",
        "column",
        "continuationMinIndent",
        "footerPattern",
        "header",
        "pageTitle",
        "revisionPattern",
    }
    if not isinstance(value, Mapping) or set(value) != required:
        raise ValueError(f"{label} fixed-width layout requires {sorted(required)}")
    if (
        not all(
            isinstance(value[field], str)
            for field in (
                "block",
                "column",
                "footerPattern",
                "header",
                "pageTitle",
                "revisionPattern",
            )
        )
        or not isinstance(value["continuationMinIndent"], int)
        or value["column"] not in {"title", "description"}
    ):
        raise ValueError(f"{label} fixed-width layout parameters have invalid types")
    header = value["header"]
    title_column = header.find("Title")
    description_column = header.find("Description")
    if title_column <= 0 or description_column <= title_column:
        raise ValueError(f"{label} fixed-width header has invalid column positions")
    try:
        footer_pattern = re.compile(value["footerPattern"])
        revision_pattern = re.compile(value["revisionPattern"])
    except re.error as error:
        raise ValueError(f"{label} fixed-width metadata pattern is invalid") from error

    columns: dict[str, list[str]] = {"title": [], "description": []}
    active_column: str | None = None
    page_continuation_window = False

    def add_fixed_width_line(line: str) -> None:
        nonlocal active_column
        title = line[title_column:description_column].strip()
        description = line[description_column:].strip()
        if title:
            columns["title"].append(title)
            active_column = "title"
        if description:
            columns["description"].append(description)
            active_column = "description"

    lines = value["block"].splitlines()
    if not lines:
        raise ValueError(f"{label} fixed-width row block is empty")
    add_fixed_width_line(lines[0])
    if active_column is None:
        raise ValueError(f"{label} fixed-width row has no title or description")

    for line in lines[1:]:
        stripped = line.strip()
        if not stripped:
            page_continuation_window = False
            continue
        if footer_pattern.fullmatch(stripped) is not None:
            continue
        if stripped == value["pageTitle"]:
            continue
        if revision_pattern.fullmatch(stripped) is not None:
            page_continuation_window = True
            continue
        indent = len(line) - len(line.lstrip(" "))
        if page_continuation_window:
            if indent < value["continuationMinIndent"] or active_column is None:
                raise ValueError(f"{label} fixed-width page continuation has invalid indentation")
            columns[active_column].append(stripped)
            continue
        if indent not in {title_column, description_column}:
            raise ValueError(f"{label} fixed-width row has an unrecognized continuation: {stripped!r}")
        add_fixed_width_line(line)

    return " ".join(columns[value["column"]])

def _pattern_claims(
    selector: PatternRowSelector,
    fields: Mapping[str, Any],
) -> Mapping[str, tuple[str, ...]]:
    """Render the declared claim map without accepting hidden claim kinds."""
    claims: dict[str, list[str]] = defaultdict(list)
    for claim, template in selector.claim_map:
        if claim not in _PATTERN_CLAIMS:
            raise ValueError(f"pattern-row claim map names unsupported claim {claim!r}")
        value = _render_pattern_text(template, fields)
        claims[claim].append(value)
    return {claim: tuple(values) for claim, values in claims.items()}

def _read_pattern_rows(
    spec: SourceSpec,
    payloads: Mapping[SourcePin, bytes],
) -> PublisherView:
    """Read declared UTF-8 row patterns without source-name dispatch."""
    selector = spec.pattern_row
    if selector is None:
        raise ValueError(f"{spec.name} has no pattern-row selector")
    if not selector.patterns:
        raise ValueError(f"{spec.name} pattern-row selector declares no input patterns")
    if selector.identity_mode not in {
        "publisher-iri",
        "source-key-derived",
        "source-local-record",
    }:
        raise ValueError(f"{spec.name} pattern-row identity mode is unsupported: {selector.identity_mode!r}")
    claim_names = [claim for claim, _ in selector.claim_map]
    required_claims = {"preferred_label", "source_path"}
    missing_claims = required_claims - set(claim_names)
    if selector.identity_mode == "source-local-record":
        missing_claims |= {"observed_at"} - set(claim_names)
    if missing_claims:
        raise ValueError(f"{spec.name} pattern-row claim map omits {sorted(missing_claims)}")
    if claim_names.count("preferred_label") != 1:
        raise ValueError(f"{spec.name} pattern-row requires one preferred_label claim")
    if claim_names.count("source_path") != 1:
        raise ValueError(f"{spec.name} pattern-row requires one source_path claim")

    try:
        payload_template = _json_without_duplicate_keys(
            selector.native_payload_template_json.encode("utf-8"),
            f"{spec.name} native payload template",
        )
    except (UnicodeError, ValueError) as error:
        raise ValueError(f"{spec.name} native payload template is invalid: {error}") from error
    if not isinstance(payload_template, Mapping):
        raise ValueError(f"{spec.name} native payload template must be an object")
    if set(payload_template) != set(selector.native_payload_fields):
        raise ValueError(
            f"{spec.name} native payload field declaration differs from its template -- "
            f"declared {sorted(selector.native_payload_fields)}, observed "
            f"{sorted(payload_template)}"
        )

    declared_template_fields: set[str] = set()
    for template in (
        selector.row_key,
        selector.identity_template,
        selector.source_locator_template,
        *(template for _, template in selector.claim_map),
    ):
        declared_template_fields.update(_pattern_template_fields(template))
    declared_template_fields.update(
        _pattern_json_template_fields(
            selector.native_payload_template_json,
            f"{spec.name} native payload template",
        )
    )
    for pattern_index, declaration in enumerate(selector.patterns):
        if declaration.native_payload_template_json is None:
            if declaration.native_payload_fields:
                raise ValueError(
                    f"{spec.name} pattern {pattern_index} declares native payload fields "
                    "without a pattern payload template"
                )
            continue
        pattern_payload = _json_without_duplicate_keys(
            declaration.native_payload_template_json.encode("utf-8"),
            f"{spec.name} pattern {pattern_index} native payload template",
        )
        if not isinstance(pattern_payload, Mapping):
            raise ValueError(f"{spec.name} pattern {pattern_index} native payload template must be an object")
        if set(pattern_payload) != set(declaration.native_payload_fields):
            raise ValueError(
                f"{spec.name} pattern {pattern_index} native payload field declaration "
                f"differs from its template -- declared "
                f"{sorted(declaration.native_payload_fields)}, observed "
                f"{sorted(pattern_payload)}"
            )
        declared_template_fields.update(
            _pattern_json_template_fields(
                declaration.native_payload_template_json,
                f"{spec.name} pattern {pattern_index} native payload template",
            )
        )
    for derived in (
        *selector.derived_fields,
        *(derived for pattern in selector.patterns for derived in pattern.derived_fields),
    ):
        declared_template_fields.update(
            _pattern_json_template_fields(
                derived.template_json,
                f"{spec.name} derived field {derived.field!r}",
            )
        )

    records: list[_ApiCaptureRecord] = []
    seen_keys: set[str] = set()
    for pattern_index, declaration in enumerate(selector.patterns):
        pattern_payload_template = payload_template
        if declaration.native_payload_template_json is not None:
            parsed_pattern_payload = _json_without_duplicate_keys(
                declaration.native_payload_template_json.encode("utf-8"),
                f"{spec.name} pattern {pattern_index} native payload template",
            )
            if not isinstance(parsed_pattern_payload, Mapping):  # validated above
                raise ValueError(f"{spec.name} pattern {pattern_index} native payload template must be an object")
            pattern_payload_template = parsed_pattern_payload
        try:
            input_pattern = re.compile(declaration.input_pattern)
            region_pattern = re.compile(
                declaration.region_pattern,
                re.DOTALL | re.MULTILINE,
            )
            row_pattern = re.compile(
                declaration.row_pattern,
                re.DOTALL | re.MULTILINE,
            )
            compiled_filters = tuple(
                (row_filter, re.compile(row_filter.pattern)) for row_filter in declaration.row_filters
            )
        except re.error as error:
            raise ValueError(f"{spec.name} pattern {pattern_index} has invalid regular expression: {error}") from error
        if "region" not in region_pattern.groupindex:
            raise ValueError(f"{spec.name} pattern {pattern_index} region must define a 'region' group")
        selected_inputs = [
            (pin, match) for pin in spec.inputs if (match := input_pattern.fullmatch(pin.path)) is not None
        ]
        if len(selected_inputs) != declaration.expected_input_count:
            raise ValueError(
                f"{spec.name} pattern {pattern_index} expected "
                f"{declaration.expected_input_count} inputs, found {len(selected_inputs)}"
            )
        pattern_row_count = 0
        for pin, input_match in selected_inputs:
            if pin.source_iri is None:
                raise ValueError(f"{spec.name} publisher input has no source IRI")
            try:
                text = payloads[pin].decode("utf-8")
            except UnicodeDecodeError as error:
                raise ValueError(f"{spec.name} input {pin.path!r} is not UTF-8") from error
            regions = list(region_pattern.finditer(text))
            if len(regions) != declaration.expected_region_count:
                raise ValueError(
                    f"{spec.name} pattern {pattern_index} input {pin.path!r} expected "
                    f"{declaration.expected_region_count} regions, found {len(regions)}"
                )
            for region_ordinal, region in enumerate(regions):
                row_matches = list(row_pattern.finditer(region.group("region")))
                for match_ordinal, match in enumerate(row_matches):
                    constants = dict(declaration.constants)
                    if len(constants) != len(declaration.constants):
                        raise ValueError(f"{spec.name} pattern {pattern_index} repeats a constant name")
                    fields: dict[str, Any] = {
                        "input_path": pin.path,
                        "input_role": pin.role or "",
                        "source_iri": pin.source_iri,
                        "source_digest": pin.sha256,
                        "input_ordinal": spec.inputs.index(pin),
                        "region_ordinal": region_ordinal,
                        "match_ordinal": match_ordinal,
                        "match_ordinal_one_based": match_ordinal + 1,
                        "pattern_ordinal": pattern_row_count,
                        "pattern_ordinal_one_based": pattern_row_count + 1,
                        "ordinal": len(records),
                        "ordinal_one_based": len(records) + 1,
                        **constants,
                    }
                    captured_sets = (
                        input_match.groupdict(),
                        {key: value for key, value in region.groupdict().items() if key != "region"},
                        match.groupdict(),
                    )
                    captured_names: set[str] = set()
                    for captured in captured_sets:
                        overlaps = set(fields) & set(captured)
                        if overlaps:
                            raise ValueError(
                                f"{spec.name} pattern {pattern_index} captures duplicate fields {sorted(overlaps)}"
                            )
                        fields.update(captured)
                        captured_names.update(captured)
                    for normalizer in declaration.normalizers:
                        if normalizer.field not in fields:
                            raise ValueError(f"{spec.name} normalizes unknown field {normalizer.field!r}")
                        for operation in normalizer.operations:
                            fields[normalizer.field] = _normalize_pattern_field(
                                fields[normalizer.field],
                                operation,
                                f"{spec.name} field {normalizer.field!r}",
                            )
                    keep = True
                    for row_filter, compiled_filter in compiled_filters:
                        value = fields.get(row_filter.field)
                        matched = isinstance(value, str) and (compiled_filter.fullmatch(value) is not None)
                        if matched != row_filter.include:
                            keep = False
                    if not keep:
                        continue
                    for derived in (
                        *selector.derived_fields,
                        *declaration.derived_fields,
                    ):
                        if derived.field in fields:
                            raise ValueError(f"{spec.name} derived field repeats {derived.field!r}")
                        template = _json_without_duplicate_keys(
                            derived.template_json.encode("utf-8"),
                            f"{spec.name} derived field {derived.field!r}",
                        )
                        rendered = _render_pattern_value(template, fields)
                        if derived.operation == "canonical-json-sha256":
                            fields[derived.field] = (
                                derived.prefix + hashlib.sha256(_canonical_json_bytes(rendered)).hexdigest()
                            )
                        elif derived.operation == "template":
                            if not isinstance(rendered, str):
                                raise ValueError(f"{spec.name} template-derived field {derived.field!r} is not text")
                            fields[derived.field] = derived.prefix + rendered
                        elif derived.operation == "uri-component":
                            if not isinstance(rendered, str):
                                raise ValueError(f"{spec.name} URI-component field {derived.field!r} is not text")
                            fields[derived.field] = derived.prefix + urllib.parse.quote(
                                rendered,
                                safe="",
                            )
                        elif derived.operation == "uuid7":
                            if (
                                not isinstance(rendered, Mapping)
                                or set(rendered) != {"recordedAt", "seed"}
                                or not isinstance(rendered["recordedAt"], str)
                                or not isinstance(rendered["seed"], Mapping)
                            ):
                                raise ValueError(
                                    f"{spec.name} UUIDv7 field {derived.field!r} "
                                    "requires recordedAt text and a seed object"
                                )
                            fields[derived.field] = derived.prefix + _source_uuid7(
                                rendered["recordedAt"],
                                rendered["seed"],
                            )
                        elif derived.operation == "source-local-resource-iri":
                            if (
                                not isinstance(rendered, Mapping)
                                or set(rendered) != {"namespace", "recordedAt", "sourceIri", "sourceKey"}
                                or not all(isinstance(value, str) for value in rendered.values())
                            ):
                                raise ValueError(
                                    f"{spec.name} source-local identity field "
                                    f"{derived.field!r} requires namespace, recordedAt, "
                                    "sourceIri, and sourceKey text"
                                )
                            fields[derived.field] = derived.prefix + _source_local_resource_iri(
                                rendered["namespace"],
                                rendered["recordedAt"],
                                rendered["sourceIri"],
                                rendered["sourceKey"],
                            )
                        elif derived.operation == "fixed-width-layout-column":
                            fields[derived.field] = derived.prefix + _fixed_width_layout_column(
                                rendered,
                                f"{spec.name} fixed-width field {derived.field!r}",
                            )
                        else:
                            raise ValueError(
                                f"{spec.name} derived field {derived.field!r} uses "
                                f"unsupported operation {derived.operation!r}"
                            )
                    used_fields = {
                        *declared_template_fields,
                        *(row_filter.field for row_filter in declaration.row_filters),
                    }
                    unaccounted = captured_names - used_fields - set(selector.declared_unevaluated_fields)
                    if unaccounted:
                        raise ValueError(
                            f"{spec.name} pattern {pattern_index} captures fields without a "
                            f"claim or explicit residue declaration: {sorted(unaccounted)}"
                        )

                    key = _render_pattern_text(selector.row_key, fields)
                    if not key:
                        raise ValueError(f"{spec.name} pattern-row key is empty")
                    if key in seen_keys:
                        raise ValueError(f"{spec.name} repeats publisher row key {key!r}")
                    seen_keys.add(key)
                    claims = _pattern_claims(selector, fields)
                    label = claims["preferred_label"][0]
                    if not label:
                        raise ValueError(f"{spec.name} row {key!r} has an empty label")
                    source_path = claims["source_path"][0]
                    source_locator = _render_pattern_text(
                        selector.source_locator_template,
                        fields,
                    )
                    notations = tuple(dict.fromkeys(value for value in claims.get("notation", ()) if value))
                    if selector.identity_mode == "source-local-record":
                        observed_at = claims["observed_at"][0]
                        identity_hint = claims.get("identity_hint", (label,))[0]
                        seed = {
                            "source": source_locator,
                            "path": source_path,
                            "notations": list(notations),
                            "identityHint": identity_hint,
                        }
                        identity_fields = {
                            **fields,
                            "source_uuid7": _source_uuid7(observed_at, seed),
                        }
                        resource = _render_pattern_text(
                            selector.identity_template,
                            identity_fields,
                        )
                    else:
                        resource = _render_pattern_text(
                            selector.identity_template,
                            fields,
                        )
                    native_payload = _render_pattern_value(pattern_payload_template, fields)
                    if not isinstance(native_payload, Mapping):
                        raise ValueError(f"{spec.name} row {key!r} native payload is not an object")
                    definitions = claims.get("definition", ())
                    if len(definitions) > 1:
                        raise ValueError(f"{spec.name} row {key!r} declares multiple definitions")
                    records.append(
                        _ApiCaptureRecord(
                            resource=resource,
                            preferred_label=label,
                            alternate_labels=claims.get("alternate_label", ()),
                            notations=notations,
                            source_locator=source_locator,
                            source_digest=(
                                "sha256:" + hashlib.sha256(_canonical_json_bytes(native_payload)).hexdigest()
                            ),
                            native_payload=native_payload,
                            definition=(definitions[0] if definitions and definitions[0] else None),
                        )
                    )
                    pattern_row_count += 1
        if pattern_row_count != declaration.expected_row_count:
            raise ValueError(
                f"{spec.name} pattern {pattern_index} expected "
                f"{declaration.expected_row_count} rows, found {pattern_row_count}"
            )
    if len(records) != selector.expected_count:
        raise ValueError(f"{spec.name} expected {selector.expected_count} total pattern rows, found {len(records)}")
    unevaluated_claims = tuple(
        f"authenticated publisher field or region is explicitly unevaluated: {field_name}"
        for field_name in selector.declared_unevaluated_fields
    )
    return _api_capture_view(
        records,
        spec,
        payloads,
        unevaluated_claims=unevaluated_claims,
    )

def _selector_claims(
    claim_map: Sequence[tuple[str, str]],
    fields: Mapping[str, Any],
    label: str,
) -> tuple[str, tuple[str, ...], str | None, str]:
    """Resolve the common label, notation, definition, and source-path claims."""
    claims: dict[str, list[Any]] = defaultdict(list)
    for claim, field_name in claim_map:
        if field_name not in fields:
            raise ValueError(f"{label} claim {claim!r} names unknown field {field_name!r}")
        value = fields[field_name]
        if value is not None and value != "":
            claims[claim].append(value)
    if len(claims["preferred_label"]) != 1:
        raise ValueError(f"{label} requires exactly one preferred_label claim")
    if len(claims["source_path"]) != 1:
        raise ValueError(f"{label} requires exactly one source_path claim")
    definitions = claims["definition"]
    if len(definitions) > 1:
        raise ValueError(f"{label} declares multiple definitions")
    preferred = _required_text(claims["preferred_label"][0], f"{label} label")
    source_path = _required_text(claims["source_path"][0], f"{label} source path")
    notations = tuple(_required_text(value, f"{label} notation") for value in claims["notation"])
    definition = _required_text(definitions[0], f"{label} definition") if definitions else None
    unknown = sorted(set(claims) - {"preferred_label", "notation", "definition", "source_path"})
    if unknown:
        raise ValueError(f"{label} declares unsupported claims {unknown}")
    return preferred, notations, definition, source_path

def _selector_resource(
    *,
    identity_mode: str,
    identity_template: str,
    identity_token: str | None,
    recorded_at: str | None,
    fields: Mapping[str, Any],
    row_key: str,
    preferred_label: str,
    notations: Sequence[str],
    source_locator: str,
    source_path: str,
    label: str,
) -> str:
    """Apply one fixed identity rule without dispatching on a construction unit."""
    if row_key not in fields:
        raise ValueError(f"{label} identity names unknown row key {row_key!r}")
    key = _required_text(fields[row_key], f"{label} row key")
    render_fields = {**fields, "quoted_key": urllib.parse.quote(key, safe="")}
    if identity_mode in {"publisher-iri", "publisher-key"}:
        resource = _render_pattern_text(identity_template, render_fields)
        return _required_text(resource, f"{label} resource identity")
    if identity_mode == "registry-source-key":
        if identity_token is None or recorded_at is None:
            raise ValueError(f"{label} registry-source-key identity requires identity_token and recorded_at")
        source_iri = _required_text(
            fields.get("identity_source_iri", fields.get("input_source_iri")),
            f"{label} identity source IRI",
        )
        source_key = _required_text(
            _render_pattern_text(identity_template, render_fields),
            f"{label} identity source key",
        )
        return _source_local_resource_iri(
            identity_token,
            recorded_at,
            source_iri,
            source_key,
        )
    if identity_mode == "source-local-record":
        if identity_token is None or recorded_at is None:
            raise ValueError(f"{label} source-local identity requires identity_token and recorded_at")
        return _source_concept_iri(
            token=identity_token,
            recorded_at=recorded_at,
            source_locator=source_locator,
            source_path=source_path,
            notations=notations,
            identity_hint=preferred_label,
        )
    raise ValueError(f"{label} has unsupported identity mode {identity_mode!r}")

def _xml_field_value(
    record: Any,
    declaration: XmlRecordField,
    namespaces: Mapping[str, str],
    label: str,
) -> Any:
    """Read one declared XML field without importing a registry parser."""
    if declaration.xpath is None and declaration.attribute is None:
        value = declaration.constant
    elif declaration.attribute is not None:
        target = (
            record
            if declaration.xpath in (None, ".")
            else record.find(
                declaration.xpath,
                namespaces,
            )
        )
        value = None if target is None else target.attrib.get(declaration.attribute)
    else:
        target = record.find(declaration.xpath or ".", namespaces)
        value = None if target is None else "".join(target.itertext())
    if value is None:
        if declaration.required:
            raise ValueError(f"{label} required XML field {declaration.field!r} is absent")
        return None
    if declaration.capture_pattern is not None:
        match = re.search(declaration.capture_pattern, str(value), re.DOTALL)
        if match is None:
            raise ValueError(f"{label} field {declaration.field!r} did not match its capture")
        value = match.groupdict().get("value") or (match.group(1) if match.groups() else match.group(0))
    for operation in declaration.normalizers:
        value = _normalize_pattern_field(value, operation, f"{label}.{declaration.field}")
    if declaration.required and value in (None, ""):
        raise ValueError(f"{label} required XML field {declaration.field!r} is empty")
    return value

def _read_xml_record_selector(
    spec: SourceSpec,
    payloads: Mapping[SourcePin, bytes],
) -> PublisherView:
    """Read one XML record family from XPath and capture declarations."""
    selector = spec.xml_record
    if selector is None:
        raise ValueError(f"{spec.name} has no XML record selector")
    pin, payload = _pin_with_role(spec, payloads, selector.input_role)
    if b"<!ENTITY" in payload[:8192].upper():
        raise ValueError(f"{spec.name} XML must not declare custom entities")
    try:
        root = ElementTree.fromstring(payload)
    except ElementTree.ParseError as error:
        raise ValueError(f"{spec.name} input is not well-formed XML") from error
    namespaces = dict(selector.namespaces)
    selected = root.findall(selector.record_xpath, namespaces)
    if not selected:
        raise ValueError(f"{spec.name} XML record XPath selected no rows")
    records: list[_ApiCaptureRecord] = []
    raw_expansion_count = 0
    seen_expansions: set[str] = set()
    for ordinal, node in enumerate(selected):
        if selector.expected_record_tags and tuple(child.tag for child in node) != (selector.expected_record_tags):
            raise ValueError(f"{spec.name} XML record {ordinal} child tags changed")
        base_fields = {
            declaration.field: _xml_field_value(
                node,
                declaration,
                namespaces,
                f"{spec.name}[{ordinal}]",
            )
            for declaration in selector.fields
        }
        row_fields: list[dict[str, Any]] = []
        if selector.expansion_field is None:
            row_fields.append(dict(base_fields))
        else:
            if selector.expansion_pattern is None:
                raise ValueError(f"{spec.name} XML expansion has no capture pattern")
            source = base_fields.get(selector.expansion_field)
            if not isinstance(source, str):
                raise ValueError(f"{spec.name} XML expansion source must be text")
            try:
                matches = list(re.finditer(selector.expansion_pattern, source, re.DOTALL))
            except re.error as error:
                raise ValueError(f"{spec.name} XML expansion pattern is invalid") from error
            raw_expansion_count += len(matches)
            for match in matches:
                value = match.groupdict().get(selector.expansion_group)
                if value is None:
                    raise ValueError(f"{spec.name} XML expansion lacks group {selector.expansion_group!r}")
                value = value.strip()
                if not value:
                    raise ValueError(f"{spec.name} XML expansion produced an empty value")
                if selector.deduplicate_expansion and value in seen_expansions:
                    continue
                seen_expansions.add(value)
                row_fields.append({**base_fields, selector.expansion_group: value})
        for fields in row_fields:
            row_ordinal = len(records)
            rendered_fields = {
                **fields,
                "ordinal": row_ordinal,
                "input_source_iri": pin.source_iri or "",
                "input_sha256": pin.sha256,
            }
            rendered_fields["source_path"] = _render_pattern_text(
                selector.source_path_template,
                rendered_fields,
            )
            records.append(
                _selector_record(
                    spec=spec,
                    fields=rendered_fields,
                    row_key=selector.row_key,
                    identity_mode=selector.identity_mode,
                    identity_template=selector.identity_template,
                    identity_token=selector.identity_token,
                    recorded_at=selector.recorded_at,
                    source_locator_template=selector.source_locator_template,
                    claim_map=selector.claim_map,
                    native_payload_template_json=selector.native_payload_template_json,
                    native_payload_fields=selector.native_payload_fields,
                    is_skos_concept=selector.is_skos_concept,
                )
            )
    if selector.expected_raw_count is not None and raw_expansion_count != selector.expected_raw_count:
        raise ValueError(
            f"{spec.name} expected {selector.expected_raw_count} raw XML captures, found {raw_expansion_count}"
        )
    if len(records) != selector.expected_count:
        raise ValueError(f"{spec.name} expected {selector.expected_count} XML records, found {len(records)}")
    return _api_capture_view(
        records,
        spec,
        payloads,
        unevaluated_claims=tuple(
            f"authenticated publisher XML field is explicitly unevaluated: {field}"
            for field in selector.declared_unevaluated_fields
        ),
    )

def _json_path(value: Any, path: Sequence[str], label: str) -> Any:
    """Traverse one declared object-only JSON path."""
    current = value
    for part in path:
        if not isinstance(current, Mapping) or part not in current:
            raise ValueError(f"{label} JSON path {'.'.join(path)!r} is absent")
        current = current[part]
    return current

def _read_json_record_selector(
    spec: SourceSpec,
    payloads: Mapping[SourcePin, bytes],
) -> PublisherView:
    """Read one array-shaped JSON record family from declarative paths and fields."""
    selector = spec.json_record
    if selector is None:
        raise ValueError(f"{spec.name} has no JSON record selector")
    pin, payload = _pin_with_role(spec, payloads, selector.input_role)
    document = _json_without_duplicate_keys(payload, spec.name)
    if not isinstance(document, Mapping):
        raise ValueError(f"{spec.name} JSON root must be an object")
    if selector.expected_root_fields and set(document) != set(selector.expected_root_fields):
        raise ValueError(f"{spec.name} JSON root fields changed")
    parent = _json_path(document, selector.record_path[:-1], spec.name)
    if selector.expected_parent_fields and (
        not isinstance(parent, Mapping) or set(parent) != set(selector.expected_parent_fields)
    ):
        raise ValueError(f"{spec.name} JSON record parent fields changed")
    rows = _json_path(document, selector.record_path, spec.name)
    if not isinstance(rows, list):
        raise ValueError(f"{spec.name} JSON record path must select an array")
    if selector.count_path:
        declared_count = _json_path(document, selector.count_path, spec.name)
        if declared_count != selector.expected_count:
            raise ValueError(f"{spec.name} JSON declared count differs: {declared_count!r}")
    if selector.header_path:
        headers = _json_path(document, selector.header_path, spec.name)
        if not isinstance(headers, list) or selector.header_value_field is None:
            raise ValueError(f"{spec.name} JSON headers have an invalid declaration")
        observed_headers = tuple(
            header.get(selector.header_value_field) if isinstance(header, Mapping) else None for header in headers
        )
        if observed_headers != selector.expected_header_fields:
            raise ValueError(f"{spec.name} JSON header fields changed")
    records: list[_ApiCaptureRecord] = []
    seen_keys: set[str] = set()
    for ordinal, row in enumerate(rows):
        if not isinstance(row, list) or len(row) != selector.expected_row_width:
            raise ValueError(f"{spec.name} JSON row {ordinal} width changed")
        if any(value is not None and not isinstance(value, (str, int, float, bool)) for value in row):
            raise ValueError(f"{spec.name} JSON row {ordinal} contains a non-scalar cell")
        fields = {declaration.field: row[declaration.index] for declaration in selector.fields}
        if selector.row_key not in fields:
            raise ValueError(f"{spec.name} JSON selector has no row key field")
        key_value = fields[selector.row_key]
        key = _required_text(key_value, f"{spec.name}[{ordinal}] row key")
        if key != key.strip() or key in seen_keys:
            raise ValueError(f"{spec.name} JSON row {ordinal} has a malformed or repeated key")
        seen_keys.add(key)
        rendered_fields = {
            **fields,
            "ordinal": ordinal,
            "input_source_iri": pin.source_iri or "",
            "input_sha256": pin.sha256,
            "publisher_header_count": len(selector.expected_header_fields),
            "publisher_row_width": len(row),
        }
        rendered_fields["source_path"] = _render_pattern_text(
            selector.source_path_template,
            rendered_fields,
        )
        records.append(
            _selector_record(
                spec=spec,
                fields=rendered_fields,
                row_key=selector.row_key,
                identity_mode=selector.identity_mode,
                identity_template=selector.identity_template,
                identity_token=None,
                recorded_at=None,
                source_locator_template=selector.source_locator_template,
                claim_map=selector.claim_map,
                native_payload_template_json=selector.native_payload_template_json,
                native_payload_fields=selector.native_payload_fields,
                is_skos_concept=selector.is_skos_concept,
            )
        )
    if len(records) != selector.expected_count:
        raise ValueError(f"{spec.name} expected {selector.expected_count} JSON records, found {len(records)}")
    return _api_capture_view(
        records,
        spec,
        payloads,
        unevaluated_claims=tuple(
            f"authenticated publisher JSON field is explicitly unevaluated: {field}"
            for field in selector.declared_unevaluated_fields
        ),
    )

def _csv_decoded_rows(
    payload: bytes,
    selector: CsvRecordSelector,
    label: str,
) -> list[list[str]]:
    """Decode one declared CSV dialect and reject malformed or blank records."""
    try:
        text = payload.decode(selector.encoding)
    except (LookupError, UnicodeDecodeError) as error:
        raise ValueError(f"{label} is not valid {selector.encoding} CSV") from error
    try:
        rows = list(
            csv.reader(
                io.StringIO(text, newline=""),
                delimiter=selector.delimiter,
                quotechar=selector.quotechar,
                strict=True,
            )
        )
    except csv.Error as error:
        raise ValueError(f"{label} is not valid CSV") from error
    if not rows or any(not row for row in rows):
        raise ValueError(f"{label} contains no rows or contains a blank CSV row")
    return rows

def _npi_luhn_valid(value: str) -> bool:
    """Validate the CMS NPI check digit with its published 80840 prefix."""
    if re.fullmatch(r"[1-9][0-9]{9}", value) is None:
        return False
    digits = [int(character) for character in "80840" + value]
    total = 0
    parity = len(digits) % 2
    for index, digit in enumerate(digits):
        if index % 2 == parity:
            digit *= 2
            if digit > 9:
                digit -= 9
        total += digit
    return total % 10 == 0

def _validate_csv_field(
    declaration: CsvFieldValidator,
    fields: Mapping[str, Any],
    label: str,
) -> None:
    """Apply a selector-declared validation without construction-unit code."""
    if declaration.field not in fields:
        raise ValueError(f"{label} validator names unknown field {declaration.field!r}")
    value = fields[declaration.field]
    if not isinstance(value, str):
        raise ValueError(f"{label} validated CSV field must be text")
    if declaration.validation == "allowed-values":
        valid = value in declaration.allowed_values
    elif declaration.validation == "npi-luhn":
        valid = _npi_luhn_valid(value)
    elif declaration.validation.startswith("regex:"):
        valid = (
            re.fullmatch(
                declaration.validation.removeprefix("regex:"),
                value,
            )
            is not None
        )
    else:
        raise ValueError(f"{label} has unsupported CSV validation {declaration.validation!r}")
    if not valid:
        raise ValueError(f"{label} field {declaration.field!r} failed {declaration.validation} validation")

def _read_csv_record_selector(
    spec: SourceSpec,
    payloads: Mapping[SourcePin, bytes],
) -> PublisherView:
    """Read direct, header-field, or distinct CSV rows from selector data."""
    selector = spec.csv_record
    if selector is None:
        raise ValueError(f"{spec.name} has no CSV record selector")
    pin, payload = _pin_with_role(spec, payloads, selector.input_role)
    rows = _csv_decoded_rows(payload, selector, spec.name)

    declared_header: tuple[str, ...] | None = None
    if selector.header_role is not None:
        _, header_payload = _pin_with_role(
            spec,
            payloads,
            selector.header_role,
        )
        header_rows = _csv_decoded_rows(
            header_payload,
            selector,
            f"{spec.name} header",
        )
        if len(header_rows) != 1:
            raise ValueError(f"{spec.name} header input must contain one CSV row")
        declared_header = tuple(header_rows[0])

    selected_rows: list[dict[str, Any]] = []
    for projection in selector.projections:
        projection_start = len(selected_rows)
        if projection.mode == "header-fields":
            if len(rows) != 1:
                raise ValueError(f"{spec.name} header-fields mode requires one CSV row")
            if projection.source_field is not None:
                raise ValueError(f"{spec.name} header-fields mode cannot name a source field")
            selected_rows.extend(
                {
                    "column_name": column,
                    "ordinal": ordinal,
                    **dict(projection.constants),
                }
                for ordinal, column in enumerate(rows[0])
            )
        else:
            header = tuple(rows[0])
            if len(header) != len(set(header)) or any(not value for value in header):
                raise ValueError(f"{spec.name} CSV header is empty or repeated")
            expected = declared_header or selector.expected_header
            if expected and header != expected:
                raise ValueError(f"{spec.name} CSV header differs from its declaration")
            data_rows = rows[1:]
            if selector.expected_data_rows is not None and len(data_rows) != selector.expected_data_rows:
                raise ValueError(
                    f"{spec.name} expected {selector.expected_data_rows} CSV data rows, found {len(data_rows)}"
                )
            if selector.max_data_rows is not None and len(data_rows) > selector.max_data_rows:
                raise ValueError(
                    f"{spec.name} has {len(data_rows)} data rows, above its declared ceiling {selector.max_data_rows}"
                )
            mappings: list[dict[str, str]] = []
            for ordinal, row in enumerate(data_rows):
                if len(row) != len(header):
                    raise ValueError(f"{spec.name} CSV row {ordinal} has {len(row)} fields, expected {len(header)}")
                mappings.append(dict(zip(header, row, strict=True)))
            if projection.mode == "rows":
                selected_rows.extend(
                    {
                        **row,
                        "row_fields": row,
                        "ordinal": ordinal,
                        **dict(projection.constants),
                    }
                    for ordinal, row in enumerate(mappings)
                )
            elif projection.mode == "distinct-values":
                if projection.source_field not in header:
                    raise ValueError(f"{spec.name} distinct projection names unknown field {projection.source_field!r}")
                values = {
                    row[projection.source_field]
                    for row in mappings
                    if not projection.nonempty or row[projection.source_field]
                }
                selected_rows.extend(
                    {
                        "value": value,
                        "source_column": projection.source_field,
                        **dict(projection.constants),
                    }
                    for value in sorted(values)
                )
            else:
                raise ValueError(f"{spec.name} has unsupported CSV projection mode {projection.mode!r}")
        observed = len(selected_rows) - projection_start
        if observed != projection.expected_count:
            raise ValueError(
                f"{spec.name} expected {projection.expected_count} rows from {projection.mode}, found {observed}"
            )

    if len(selected_rows) != selector.expected_count:
        raise ValueError(
            f"{spec.name} expected {selector.expected_count} selected CSV rows, found {len(selected_rows)}"
        )
    projection_total = sum(item.expected_count for item in selector.projections)
    if projection_total != selector.expected_count:
        raise ValueError(f"{spec.name} CSV projection counts do not total the family count")

    records: list[_ApiCaptureRecord] = []
    seen_keys: set[str] = set()
    label_rules = {rule.discriminator_value: rule.fields for rule in selector.label_rules}
    for ordinal, base_fields in enumerate(selected_rows):
        fields = dict(base_fields)
        if label_rules:
            discriminator_field = selector.label_discriminator_field
            if discriminator_field is None:
                raise ValueError(f"{spec.name} CSV label rules lack a discriminator")
            discriminator = fields.get(discriminator_field)
            label_fields = label_rules.get(str(discriminator))
            if label_fields is None:
                raise ValueError(f"{spec.name} CSV row {ordinal} has unsupported label discriminator")
            fields["preferred_label"] = " ".join(
                str(fields.get(name, "")).strip() for name in label_fields if str(fields.get(name, "")).strip()
            )
        fields.update(
            {
                "ordinal": fields.get("ordinal", ordinal),
                "input_source_iri": pin.source_iri or "",
                "input_sha256": pin.sha256,
                "quoted_value": urllib.parse.quote(
                    str(fields.get("value", "")),
                    safe="",
                ),
            }
        )
        fields["ordinal_text"] = str(fields["ordinal"])
        fields["source_path"] = _render_pattern_text(
            selector.source_path_template,
            fields,
        )
        for validator in selector.validators:
            _validate_csv_field(validator, fields, f"{spec.name}[{ordinal}]")
        key = _required_text(fields.get(selector.row_key), f"{spec.name} row key")
        if key in seen_keys:
            raise ValueError(f"{spec.name} repeats CSV row key {key!r}")
        seen_keys.add(key)
        records.append(
            _selector_record(
                spec=spec,
                fields=fields,
                row_key=selector.row_key,
                identity_mode=selector.identity_mode,
                identity_template=selector.identity_template,
                identity_token=selector.identity_token,
                recorded_at=selector.recorded_at,
                source_locator_template=selector.source_locator_template,
                claim_map=selector.claim_map,
                native_payload_template_json=selector.native_payload_template_json,
                native_payload_fields=selector.native_payload_fields,
                is_skos_concept=selector.is_skos_concept,
            )
        )
    return _api_capture_view(
        records,
        spec,
        payloads,
        unevaluated_claims=tuple(
            f"authenticated publisher CSV field is explicitly unevaluated: {field}"
            for field in selector.declared_unevaluated_fields
        ),
    )

def _ooxml_member_path(base: str, target: str) -> str:
    """Resolve an OOXML relationship target without permitting ZIP traversal."""
    path = target.removeprefix("/")
    if not target.startswith("/"):
        path = posixpath.normpath(posixpath.join(posixpath.dirname(base), target))
    if path.startswith("../") or path == ".." or not path.startswith("xl/"):
        raise ValueError(f"OOXML relationship target escapes the workbook: {target!r}")
    return path

def _ooxml_shared_strings(archive: zipfile.ZipFile) -> tuple[str, ...]:
    """Read the standard shared-string table, including rich-text runs."""
    if "xl/sharedStrings.xml" not in archive.namelist():
        return ()
    root = ElementTree.fromstring(archive.read("xl/sharedStrings.xml"))
    return tuple(
        "".join(node.text or "" for node in item.iter(f"{{{_OOXML_MAIN}}}t"))
        for item in root.findall(f"{{{_OOXML_MAIN}}}si")
    )

def _ooxml_workbook_sheets(
    archive: zipfile.ZipFile,
) -> tuple[tuple[str, str], ...]:
    """Return workbook sheet names and resolved worksheet members in order."""
    workbook_path = "xl/workbook.xml"
    relations_path = "xl/_rels/workbook.xml.rels"
    workbook = ElementTree.fromstring(archive.read(workbook_path))
    relations = ElementTree.fromstring(archive.read(relations_path))
    targets = {
        relation.attrib["Id"]: _ooxml_member_path(
            workbook_path,
            relation.attrib["Target"],
        )
        for relation in relations.findall(f"{{{_OOXML_PACKAGE_REL}}}Relationship")
        if relation.attrib.get("TargetMode") != "External" and relation.attrib.get("Type", "").endswith("/worksheet")
    }
    sheets: list[tuple[str, str]] = []
    for sheet in workbook.findall(f".//{{{_OOXML_MAIN}}}sheet"):
        relationship_id = sheet.attrib.get(f"{{{_OOXML_REL}}}id")
        if relationship_id not in targets:
            raise ValueError(f"OOXML worksheet {sheet.attrib.get('name')!r} has no target")
        sheets.append((sheet.attrib["name"], targets[relationship_id]))
    return tuple(sheets)

def _ooxml_column_index(reference: str) -> int:
    match = re.match(r"^([A-Z]+)[1-9][0-9]*$", reference)
    if match is None:
        raise ValueError(f"OOXML cell reference is malformed: {reference!r}")
    value = 0
    for character in match.group(1):
        value = value * 26 + ord(character) - ord("A") + 1
    return value - 1

def _ooxml_cell_value(
    cell: ElementTree.Element,
    shared_strings: Sequence[str],
) -> Any:
    cell_type = cell.attrib.get("t", "n")
    if cell_type == "inlineStr":
        return "".join(node.text or "" for node in cell.iter(f"{{{_OOXML_MAIN}}}t"))
    value_node = cell.find(f"{{{_OOXML_MAIN}}}v")
    if value_node is None or value_node.text is None:
        return None
    value = value_node.text
    if cell_type == "s":
        try:
            return shared_strings[int(value)]
        except (IndexError, ValueError) as error:
            raise ValueError("OOXML shared-string index is invalid") from error
    if cell_type in {"str", "e", "d"}:
        if cell_type == "e":
            raise ValueError(f"OOXML formula cell contains error value {value!r}")
        return value
    if cell_type == "b":
        if value not in {"0", "1"}:
            raise ValueError(f"OOXML boolean cell is malformed: {value!r}")
        return value == "1"
    try:
        number = float(value)
    except ValueError as error:
        raise ValueError(f"OOXML numeric cell is malformed: {value!r}") from error
    return int(number) if number.is_integer() else number

def _ooxml_sheet_rows(
    archive: zipfile.ZipFile,
    member: str,
    shared_strings: Sequence[str],
) -> Iterator[tuple[int, list[Any]]]:
    """Stream worksheet rows and clear parsed XML nodes as they are consumed."""
    with archive.open(member) as handle:
        for _, element in ElementTree.iterparse(handle, events=("end",)):
            if element.tag != f"{{{_OOXML_MAIN}}}row":
                continue
            row_number = int(element.attrib.get("r", "0"))
            values: list[Any] = []
            for cell in element.findall(f"{{{_OOXML_MAIN}}}c"):
                reference = cell.attrib.get("r")
                if reference is None:
                    raise ValueError("OOXML cell has no coordinate")
                column = _ooxml_column_index(reference)
                if column >= len(values):
                    values.extend([None] * (column + 1 - len(values)))
                values[column] = _ooxml_cell_value(cell, shared_strings)
            yield row_number, values
            element.clear()

def _ooxml_cell_text(value: Any) -> str:
    if value is None:
        return ""
    if isinstance(value, bool):
        return str(value)
    if isinstance(value, int):
        return str(value)
    if isinstance(value, float) and value.is_integer():
        return str(int(value))
    return str(value)

def _ooxml_typed_value(value: Any, cell_type: str, label: str) -> Any:
    """Apply a declared worksheet cell type without guessing from a source name."""
    if cell_type == "raw":
        return value
    if cell_type == "cell-text":
        return _ooxml_cell_text(value)
    if cell_type == "text":
        if not isinstance(value, str) or not value:
            raise ValueError(f"{label} must be non-empty text")
        return value
    if cell_type == "stripped-text":
        if not isinstance(value, str) or not value.strip():
            raise ValueError(f"{label} must be non-empty text")
        return value.strip()
    if cell_type == "code-text":
        text = _ooxml_cell_text(value).strip()
        if not text:
            raise ValueError(f"{label} must be a non-empty code")
        return text
    if cell_type == "optional-text":
        if value is None:
            return None
        if not isinstance(value, str) or not value.strip():
            raise ValueError(f"{label} must be text or an empty cell")
        return value.strip()
    if cell_type == "optional-cell-text":
        text = _ooxml_cell_text(value).strip()
        return text or None
    if cell_type == "optional-code3":
        if value is None:
            return None
        text = _ooxml_cell_text(value).strip()
        if not text.isdigit() or len(text) > 3:
            raise ValueError(f"{label} must be an empty or three-digit code")
        return text.zfill(3)
    if cell_type in {"date", "optional-date"}:
        if value is None and cell_type == "optional-date":
            return None
        if isinstance(value, (int, float)) and not isinstance(value, bool):
            return (datetime(1899, 12, 30, tzinfo=UTC) + timedelta(days=float(value))).date().isoformat()
        if isinstance(value, str) and re.fullmatch(r"\d{4}-\d{2}-\d{2}(?:T.*)?", value):
            return value[:10]
        raise ValueError(f"{label} must be an Excel or ISO date")
    raise ValueError(f"{label} has unsupported OOXML cell type {cell_type!r}")

def _apply_ooxml_derived(
    fields: dict[str, Any],
    declaration: OoxmlDerivedField,
    label: str,
) -> None:
    values = [fields.get(name) for name in declaration.inputs]
    if declaration.operation == "template":
        if declaration.template is None:
            raise ValueError(f"{label} template-derived field lacks a template")
        result: Any = _render_pattern_text(declaration.template, fields)
    elif declaration.operation == "strip":
        if len(values) != 1 or not isinstance(values[0], str):
            raise ValueError(f"{label} strip-derived field requires one text input")
        result = values[0].strip()
    elif declaration.operation == "first-nonempty":
        result = next((value for value in values if value not in (None, "")), None)
        if result is None:
            raise ValueError(f"{label} first-nonempty field found no value")
    elif declaration.operation == "regex-capture":
        if len(values) != 1 or not isinstance(values[0], str):
            raise ValueError(f"{label} regex-capture requires one text input")
        if declaration.pattern is None or declaration.group is None:
            raise ValueError(f"{label} regex-capture lacks a pattern or group")
        match = re.fullmatch(declaration.pattern, values[0])
        if match is None:
            raise ValueError(f"{label} input did not match its declared shape")
        result = match.group(declaration.group)
    elif declaration.operation == "regex-map":
        if len(values) != 1 or not isinstance(values[0], str):
            raise ValueError(f"{label} regex-map requires one text input")
        matches = [mapped for pattern, mapped in declaration.cases if re.fullmatch(pattern, values[0])]
        if len(matches) != 1:
            raise ValueError(f"{label} regex-map selected {len(matches)} cases")
        result = matches[0]
    elif declaration.operation == "sha256":
        if len(values) != 1 or not isinstance(values[0], str):
            raise ValueError(f"{label} sha256 requires one text input")
        result = hashlib.sha256(values[0].encode("utf-8")).hexdigest()
    elif declaration.operation == "url-quote":
        if len(values) != 1 or not isinstance(values[0], str):
            raise ValueError(f"{label} url-quote requires one text input")
        result = urllib.parse.quote(values[0], safe="")
    elif declaration.operation == "excel-date":
        if len(values) != 1:
            raise ValueError(f"{label} excel-date requires one input")
        result = _ooxml_typed_value(values[0], "date", label)
    else:
        raise ValueError(f"{label} uses unsupported OOXML derived operation {declaration.operation!r}")
    if declaration.field in fields:
        raise ValueError(f"{label} derived field repeats {declaration.field!r}")
    fields[declaration.field] = result

def _validate_ooxml_row(
    fields: Mapping[str, Any],
    declaration: OoxmlRowValidator,
    ordinal: int,
    label: str,
) -> None:
    value = fields.get(declaration.field)
    if declaration.validation == "sequence-one-based":
        valid = str(value) == str(ordinal + 1)
    elif declaration.validation.startswith("regex:"):
        valid = (
            isinstance(value, str) and re.fullmatch(declaration.validation.removeprefix("regex:"), value) is not None
        )
    else:
        raise ValueError(f"{label} has unsupported OOXML row validation {declaration.validation!r}")
    if not valid:
        raise ValueError(f"{label} field {declaration.field!r} failed {declaration.validation} validation")

def _read_ooxml_table(
    archive: zipfile.ZipFile,
    sheet_members: Mapping[str, str],
    shared_strings: Sequence[str],
    table: OoxmlTable,
    spec_name: str,
) -> list[dict[str, Any]]:
    member = sheet_members.get(table.sheet)
    if member is None:
        raise ValueError(f"{spec_name} table {table.name!r} names an unknown sheet")
    header_seen = False
    rows: list[dict[str, Any]] = []
    for row_number, values in _ooxml_sheet_rows(archive, member, shared_strings):
        if row_number == table.header_row:
            observed = tuple(_ooxml_cell_text(value) for value in values)
            if table.collapse_header_whitespace:
                observed = tuple(" ".join(value.split()) for value in observed)
            expected = tuple(str(value) for value in table.expected_header)
            if observed[: len(expected)] != expected or any(observed[len(expected) :]):
                raise ValueError(f"{spec_name} sheet {table.sheet!r} header changed")
            header_seen = True
            continue
        if row_number <= table.header_row or not any(value is not None for value in values):
            continue
        fields = dict(table.constants)
        for declaration in table.fields:
            raw = values[declaration.column] if declaration.column < len(values) else None
            fields[declaration.field] = _ooxml_typed_value(
                raw,
                declaration.cell_type,
                f"{spec_name}.{table.name}[{row_number}].{declaration.field}",
            )
        for declaration in table.derived_fields:
            _apply_ooxml_derived(
                fields,
                declaration,
                f"{spec_name}.{table.name}[{row_number}]",
            )
        ordinal = len(rows)
        for declaration in table.validators:
            _validate_ooxml_row(
                fields,
                declaration,
                ordinal,
                f"{spec_name}.{table.name}[{row_number}]",
            )
        fields["worksheet_row"] = row_number
        rows.append(fields)
    if not header_seen:
        raise ValueError(f"{spec_name} sheet {table.sheet!r} has no declared header row")
    if len(rows) != table.expected_rows:
        raise ValueError(f"{spec_name} table {table.name!r} expected {table.expected_rows} rows, found {len(rows)}")
    return rows

def _ooxml_filter_matches(row: Mapping[str, Any], item: OoxmlRowFilter) -> bool:
    value = row.get(item.field)
    if item.operation == "equals":
        return value == item.value
    if item.operation == "not-equals":
        return value != item.value
    if item.operation == "is-empty":
        return value in (None, "")
    if item.operation == "is-not-empty":
        return value not in (None, "")
    if item.operation == "regex":
        return isinstance(value, str) and item.value is not None and re.fullmatch(item.value, value) is not None
    raise ValueError(f"unsupported OOXML row filter {item.operation!r}")

def _render_ooxml_aggregate_rows(
    rows: Sequence[Mapping[str, Any]],
    template_json: str | None,
    label: str,
) -> list[Any]:
    if template_json is None:
        raise ValueError(f"{label} aggregate lacks a JSON template")
    template = _json_without_duplicate_keys(template_json.encode(), label)
    return [_render_pattern_value(template, row) for row in rows]

def _read_ooxml_relational(
    spec: SourceSpec,
    payloads: Mapping[SourcePin, bytes],
) -> PublisherView:
    """Read OOXML with stock ZIP/XML and execute one declared relational plan."""
    selector = spec.ooxml_relational
    if selector is None:
        raise ValueError(f"{spec.name} has no OOXML relational selector")
    pin, payload = _pin_with_role(spec, payloads, selector.input_role)
    try:
        archive = zipfile.ZipFile(io.BytesIO(payload))
    except zipfile.BadZipFile as error:
        raise ValueError(f"{spec.name} input is not an OOXML ZIP") from error
    with archive:
        names = archive.namelist()
        if len(names) != len(set(names)) or any(name.startswith("/") or ".." in Path(name).parts for name in names):
            raise ValueError(f"{spec.name} OOXML ZIP member names are unsafe")
        sheets = _ooxml_workbook_sheets(archive)
        if tuple(name for name, _ in sheets) != selector.expected_sheets:
            raise ValueError(f"{spec.name} workbook sheets changed")
        sheet_members = dict(sheets)
        missing_members = sorted(set(sheet_members.values()) - set(names))
        if missing_members:
            raise ValueError(f"{spec.name} workbook omits worksheet members {missing_members}")
        shared_strings = _ooxml_shared_strings(archive)
        table_rows = {
            table.name: _read_ooxml_table(
                archive,
                sheet_members,
                shared_strings,
                table,
                spec.name,
            )
            for table in selector.tables
        }

    primary = table_rows.get(selector.primary_table)
    if primary is None:
        raise ValueError(f"{spec.name} names an unknown primary OOXML table")
    primary = list(primary)
    for table_name in selector.union_tables:
        union_rows = table_rows.get(table_name)
        if union_rows is None:
            raise ValueError(f"{spec.name} names an unknown OOXML union table")
        primary.extend(union_rows)
    filtered = [row for row in primary if all(_ooxml_filter_matches(row, item) for item in selector.filters)]
    if selector.sort_by:
        filtered.sort(key=lambda row: tuple(str(row.get(field, "")) for field in selector.sort_by))

    if selector.group_by:
        groups_by_key: dict[tuple[Any, ...], list[dict[str, Any]]] = defaultdict(list)
        for row in filtered:
            groups_by_key[tuple(row.get(field) for field in selector.group_by)].append(row)
        groups = list(groups_by_key.values())
    else:
        groups = [[row] for row in filtered]

    join_indexes: dict[str, dict[tuple[Any, ...], list[dict[str, Any]]]] = {}
    for join in selector.joins:
        rows = table_rows.get(join.table)
        if rows is None:
            raise ValueError(f"{spec.name} join {join.alias!r} names an unknown table")
        index: dict[tuple[Any, ...], list[dict[str, Any]]] = defaultdict(list)
        for row in rows:
            index[tuple(row.get(field) for field in join.right_fields)].append(row)
        join_indexes[join.alias] = index

    records: list[_ApiCaptureRecord] = []
    matched_join_keys: dict[str, set[tuple[Any, ...]]] = defaultdict(set)
    for ordinal, group_rows in enumerate(groups):
        fields = dict(group_rows[0])
        joined: dict[str, list[dict[str, Any]]] = {}
        for join in selector.joins:
            left_keys = {tuple(row.get(field) for field in join.left_fields) for row in group_rows}
            if len(left_keys) != 1:
                raise ValueError(f"{spec.name} grouped rows disagree on join {join.alias!r}")
            key = next(iter(left_keys))
            matches = join_indexes[join.alias].get(key, [])
            if join.cardinality == "one" and len(matches) != 1:
                raise ValueError(f"{spec.name} join {join.alias!r} expected one row, found {len(matches)}")
            if join.cardinality not in {"one", "many"}:
                raise ValueError(f"{spec.name} join cardinality is unsupported")
            joined[join.alias] = matches
            if matches:
                matched_join_keys[join.alias].add(key)

        for aggregate in selector.aggregates:
            source_rows = group_rows if aggregate.source == "primary" else joined.get(aggregate.source)
            if source_rows is None:
                raise ValueError(f"{spec.name} aggregate names unknown source {aggregate.source!r}")
            if aggregate.operation == "rows":
                value: Any = _render_ooxml_aggregate_rows(
                    source_rows,
                    aggregate.template_json,
                    f"{spec.name}.{aggregate.field}",
                )
            elif aggregate.operation == "count-offset":
                value = len(source_rows) + aggregate.offset
            elif aggregate.operation == "distinct-list":
                if aggregate.value_field is None:
                    raise ValueError(f"{spec.name} distinct-list aggregate has no field")
                value = sorted({row.get(aggregate.value_field) for row in source_rows})
            elif aggregate.operation == "count-by":
                if aggregate.key_field is None:
                    raise ValueError(f"{spec.name} count-by aggregate has no key field")
                counts = Counter(str(row.get(aggregate.key_field)) for row in source_rows)
                value = {key: counts[key] for key in sorted(counts)}
            elif aggregate.operation == "one":
                values = _render_ooxml_aggregate_rows(
                    source_rows,
                    aggregate.template_json,
                    f"{spec.name}.{aggregate.field}",
                )
                if len(values) != 1:
                    raise ValueError(f"{spec.name} one aggregate did not receive one row")
                value = values[0]
            else:
                raise ValueError(f"{spec.name} aggregate operation is unsupported: {aggregate.operation!r}")
            fields[aggregate.field] = value

        for declaration in selector.derived_fields:
            _apply_ooxml_derived(fields, declaration, f"{spec.name}[{ordinal}]")
        fields.update(
            {
                "ordinal": ordinal,
                "input_source_iri": pin.source_iri or "",
                "input_sha256": pin.sha256,
            }
        )
        fields["source_path"] = _render_pattern_text(
            selector.source_path_template,
            fields,
        )
        records.append(
            _selector_record(
                spec=spec,
                fields=fields,
                row_key=selector.row_key,
                identity_mode=selector.identity_mode,
                identity_template=selector.identity_template,
                identity_token=selector.identity_token,
                recorded_at=selector.recorded_at,
                source_locator_template=selector.source_locator_template,
                claim_map=selector.claim_map,
                native_payload_template_json=selector.native_payload_template_json,
                native_payload_fields=selector.native_payload_fields,
                is_skos_concept=selector.is_skos_concept,
            )
        )

    for join in selector.joins:
        if join.require_all_right:
            unmatched = set(join_indexes[join.alias]) - matched_join_keys[join.alias]
            if unmatched:
                raise ValueError(f"{spec.name} join {join.alias!r} left {len(unmatched)} right-side keys unused")
    if len(records) != selector.expected_count:
        raise ValueError(f"{spec.name} expected {selector.expected_count} OOXML result rows, found {len(records)}")
    return _api_capture_view(
        records,
        spec,
        payloads,
        unevaluated_claims=tuple(
            f"authenticated publisher OOXML field is explicitly unevaluated: {field}"
            for field in selector.declared_unevaluated_fields
        ),
    )

def _apply_nrc_derived(
    fields: dict[str, Any],
    declaration: NrcDerivedField,
    label: str,
) -> None:
    if declaration.field in fields:
        raise ValueError(f"{label} repeats NRC derived field {declaration.field!r}")
    if declaration.operation == "template":
        if declaration.template is None:
            raise ValueError(f"{label} NRC template-derived field has no template")
        value: Any = _render_pattern_text(declaration.template, fields)
    elif declaration.operation == "sha256":
        if len(declaration.inputs) != 1:
            raise ValueError(f"{label} NRC sha256-derived field requires one input")
        source = fields.get(declaration.inputs[0])
        if not isinstance(source, str):
            raise ValueError(f"{label} NRC sha256 input must be text")
        value = hashlib.sha256(source.encode("utf-8")).hexdigest()
    else:
        raise ValueError(f"{label} uses unsupported NRC derived operation {declaration.operation!r}")
    fields[declaration.field] = value

def _read_nrc_adams_multi_artifact(
    spec: SourceSpec,
    payloads: Mapping[SourcePin, bytes],
) -> PublisherView:
    """Reconstruct the two NRC unions from six pinned text inputs and patterns."""
    selector = spec.nrc_adams
    if selector is None:
        raise ValueError(f"{spec.name} has no NRC ADAMS multi-artifact selector")
    if len(selector.inputs) != 6 or len({item.name for item in selector.inputs}) != 6:
        raise ValueError(f"{spec.name} NRC selector must name six distinct inputs")
    by_path = {pin.path: (pin, payloads[pin]) for pin in spec.inputs}
    if len(by_path) != len(spec.inputs):
        raise ValueError(f"{spec.name} repeats an authenticated NRC input path")
    declared_paths = {declaration.path for declaration in selector.inputs}
    if declared_paths != set(by_path):
        raise ValueError(
            f"{spec.name} NRC selector paths differ from its authenticated inputs: "
            f"declared={sorted(declared_paths)}, authenticated={sorted(by_path)}"
        )
    inputs: dict[str, tuple[NrcAdamsInput, SourcePin, str]] = {}
    for declaration in selector.inputs:
        matched = by_path.get(declaration.path)
        if matched is None:
            raise ValueError(f"{spec.name} NRC input {declaration.name!r} is absent")
        pin, payload = matched
        try:
            text = payload.decode("utf-8")
        except UnicodeDecodeError as error:
            raise ValueError(f"{spec.name} NRC input {declaration.name!r} is not UTF-8") from error
        inputs[declaration.name] = (declaration, pin, text)

    records: list[_ApiCaptureRecord] = []
    seen_keys: set[str] = set()
    for pattern_index, pattern in enumerate(selector.patterns):
        source = inputs.get(pattern.input_name)
        if source is None:
            raise ValueError(f"{spec.name} NRC pattern {pattern_index} names an unknown input")
        input_declaration, pin, text = source
        region = text
        if pattern.region_pattern is not None:
            region_matches = list(re.finditer(pattern.region_pattern, text, re.DOTALL))
            if len(region_matches) != 1 or "region" not in region_matches[0].groupdict():
                raise ValueError(f"{spec.name} NRC pattern {pattern_index} expected one named region")
            region = region_matches[0].group("region")
        try:
            matches = list(re.finditer(pattern.row_pattern, region, re.DOTALL))
        except re.error as error:
            raise ValueError(f"{spec.name} NRC pattern {pattern_index} is invalid") from error
        if len(matches) != pattern.expected_matches:
            raise ValueError(
                f"{spec.name} NRC pattern {pattern_index} expected "
                f"{pattern.expected_matches} matches, found {len(matches)}"
            )
        covered = "".join(match.group(0) for match in matches)
        if pattern.coverage == "comma-joined":
            covered = ",".join(match.group(0) for match in matches)
        if pattern.coverage in {"whole", "comma-joined"} and covered != region:
            raise ValueError(f"{spec.name} NRC pattern {pattern_index} leaves unparsed selected text")
        if pattern.coverage not in {"whole", "comma-joined", "selected"}:
            raise ValueError(f"{spec.name} NRC pattern {pattern_index} has unsupported coverage")

        captured = [match.groupdict() for match in matches]
        if pattern.projection == "each":
            projected = [dict(row) for row in captured]
        elif pattern.projection == "single":
            projected = [dict(captured[0]) if len(captured) == 1 else {}]
            group_names = sorted({name for row in captured for name in row})
            for name in group_names:
                projected[0][f"{name}_values"] = [row[name] for row in captured]
        else:
            raise ValueError(f"{spec.name} NRC pattern {pattern_index} has unsupported projection")

        for projected_row in projected:
            duplicate_constants = set(projected_row) & {name for name, _ in pattern.constants}
            if duplicate_constants:
                raise ValueError(
                    f"{spec.name} NRC pattern {pattern_index} constants repeat captures {sorted(duplicate_constants)}"
                )
            fields = {**projected_row, **dict(pattern.constants)}
            fields.update(
                {
                    "input_sha256": pin.sha256,
                    "input_source_iri": pin.source_iri or "",
                    "official_source_url": input_declaration.official_source_url,
                    "observed_at": input_declaration.observed_at,
                    "ordinal": len(records),
                }
            )
            for aggregate in pattern.aggregate_templates:
                try:
                    template = _json_without_duplicate_keys(
                        aggregate.template_json.encode("utf-8"),
                        f"{spec.name} NRC aggregate {aggregate.field}",
                    )
                except (UnicodeError, ValueError) as error:
                    raise ValueError(f"{spec.name} NRC aggregate template is invalid: {error}") from error
                if aggregate.mode == "row":
                    fields[aggregate.field] = _render_pattern_value(
                        template,
                        fields,
                    )
                elif aggregate.mode == "collect" and pattern.projection == "single":
                    fields[aggregate.field] = [
                        _render_pattern_value(
                            template,
                            {**row, **dict(pattern.constants)},
                        )
                        for row in captured
                    ]
                else:
                    raise ValueError(
                        f"{spec.name} NRC aggregate {aggregate.field!r} has unsupported mode {aggregate.mode!r}"
                    )
            for declaration in pattern.derived_fields:
                _apply_nrc_derived(
                    fields,
                    declaration,
                    f"{spec.name}.pattern[{pattern_index}]",
                )
            fields["source_path"] = _render_pattern_text(
                pattern.source_path_template,
                fields,
            )
            key = _required_text(
                fields.get(pattern.row_key),
                f"{spec.name} NRC row key",
            )
            if key in seen_keys:
                raise ValueError(f"{spec.name} repeats NRC row key {key!r}")
            seen_keys.add(key)
            records.append(
                _selector_record(
                    spec=spec,
                    fields=fields,
                    row_key=pattern.row_key,
                    identity_mode="publisher-key",
                    identity_template=pattern.identity_template,
                    identity_token=None,
                    recorded_at=None,
                    source_locator_template=pattern.source_locator_template,
                    claim_map=pattern.claim_map,
                    native_payload_template_json=(pattern.native_payload_template_json),
                    native_payload_fields=pattern.native_payload_fields,
                    is_skos_concept=False,
                )
            )
    if len(records) != selector.expected_count:
        raise ValueError(f"{spec.name} expected {selector.expected_count} NRC union rows, found {len(records)}")
    return _api_capture_view(
        records,
        spec,
        payloads,
        unevaluated_claims=tuple(
            f"authenticated NRC artifact field is explicitly unevaluated: {field}"
            for field in selector.declared_unevaluated_fields
        ),
    )

