    if self._open is not None:
        self._buffer.append(" ")

def handle_data(self, data: str) -> None:
    if self._list_depth and self._open is not None:
        self._buffer.append(data)

def finish(self) -> None:
    self.close()
    if self._open is not None:
        raise ValueError(f"CFR title {self.cfr_title} ends with <{self._open}> still open")
    if self._list_depth != 0:
        raise ValueError(f"CFR title {self.cfr_title} ends inside a definition list")
    if self._lists != 1:
        raise ValueError(f"CFR title {self.cfr_title} carries {self._lists} definition lists, expected one")

def _cfr_publisher_text(value: str) -> str:
    """Drop the one trailing full stop the publisher writes after a phrase."""
    return value.removesuffix(".")

def _cfr_part_citation(text: str, cfr_title: int) -> tuple[str, str, Counter[str]] | None:
    """Split one element's text into a CFR part number and its heading.

    Returns ``None`` when the text is not a part citation at all, so the caller
    can decide what the element is from its type. Irregularities the publisher
    left in an otherwise readable citation are counted, never waved through.
    """
    irregularities: Counter[str] = Counter()
    remainder = text
    if remainder.startswith(_CFR_LEAKED_MARKUP_PREFIX):
        irregularities["leakedStrongFragment"] += 1
        remainder = remainder[len(_CFR_LEAKED_MARKUP_PREFIX) :]
    cut = min((remainder.find(mark) for mark in _CFR_CITATION_SEPARATORS if mark in remainder), default=-1)
    if cut < 0:
        return None
    if remainder[cut] != "_":
        irregularities["emDashSeparator"] += 1
    citation = remainder[:cut].split()
    heading = _cfr_publisher_text(remainder[cut + 1 :].strip())
    if len(citation) < 3 or citation[0] != str(cfr_title) or citation[1] != "CFR":
        return None
    words = citation[2:]
    if words[0] in _CFR_PART_KEYWORDS:
        if words[0] != "Part":
            irregularities["misspelledPartKeyword"] += 1
        words = words[1:]
    else:
        irregularities["missingPartKeyword"] += 1
    if len(words) != 1:
        return None
    part = words[0]
    if not part[:1].isdigit() or not part.replace("-", "").replace(".", "").isalnum():
        return None
    if not heading:
        return None
    return part, heading, irregularities

def _read_regulations_gov_agencies_capture(
    spec: SourceSpec,
    payloads: Mapping[SourcePin, bytes],
) -> PublisherView:
    """Reconstruct the complete regulations.gov agency roster independently."""

    pin, payload = _pin_with_role(
        spec,
        payloads,
        "publisherAgencyRoster",
    )
    root = _json_without_duplicate_keys(payload, spec.name)
    if not isinstance(root, Mapping) or set(root) != {"data"}:
        raise ValueError(f"{spec.name} top-level fields drifted")
    values = root["data"]
    if not isinstance(values, list) or len(values) != 331:
        raise ValueError(f"{spec.name} must contain exactly 331 records")

    records: list[_ApiCaptureRecord] = []
    ids: set[str] = set()
    parents: set[str] = set()
    parent_count = 0
    for ordinal, value in enumerate(values):
        label = f"{spec.name}.data[{ordinal}]"
        if not isinstance(value, Mapping) or set(value) != (
            _REGULATIONS_GOV_RECORD_FIELDS
        ):
            raise ValueError(f"{label} fields drifted")
        agency_id = _required_text(value.get("id"), f"{label}.id")
        if _REGULATIONS_GOV_AGENCY_ID.fullmatch(agency_id) is None:
            raise ValueError(f"{label}.id has an unsupported shape")
        if agency_id in ids:
            raise ValueError(f"{spec.name} repeats agency id {agency_id!r}")
        ids.add(agency_id)
        if value.get("type") != "agencies":
            raise ValueError(f"{label}.type must remain 'agencies'")

        attributes = value.get("attributes")
        if not isinstance(attributes, Mapping) or set(attributes) != (
            _REGULATIONS_GOV_ATTRIBUTE_FIELDS
        ):
            raise ValueError(f"{label}.attributes fields drifted")
        parent = attributes.get("parent")
        if parent is not None and (
            not isinstance(parent, str)
            or _REGULATIONS_GOV_AGENCY_ID.fullmatch(parent) is None
        ):
            raise ValueError(f"{label}.attributes.parent is invalid")
        for field_name in ("participate", "partner"):
            if not isinstance(attributes.get(field_name), bool):
                raise ValueError(
                    f"{label}.attributes.{field_name} must be boolean"
                )
        guidelines = attributes.get("postingGuidelines")
        if guidelines is not None and not isinstance(guidelines, str):
            raise ValueError(
                f"{label}.attributes.postingGuidelines must be text or null"
            )
        name = _required_text(attributes.get("name"), f"{label}.attributes.name")
        if attributes.get("agencyType") != "Federal":
            raise ValueError(
                f"{label}.attributes.agencyType must remain 'Federal'"
            )

        links = value.get("links")
        if not isinstance(links, Mapping) or set(links) != (
            _REGULATIONS_GOV_LINK_FIELDS
        ):
            raise ValueError(f"{label}.links fields drifted")
        self_link = _required_text(links.get("self"), f"{label}.links.self")
        expected_link = (
            "https://api.regulations.gov/v4/agencies/" + agency_id
        )
        if self_link != expected_link:
            raise ValueError(f"{label}.links.self differs")

        resource = (
            "urn:ref:regulations-gov-agency:"
            + urllib.parse.quote(agency_id, safe="")
        )
        relations: tuple[tuple[str, str], ...] = ()
        if parent is not None:
            parent_count += 1
            parents.add(parent)
            relations = (
                (
                    _ATLAS_PARENT_ENTITY,
                    "urn:ref:regulations-gov-agency:"
                    + urllib.parse.quote(parent, safe=""),
                ),
            )
        records.append(
            _ApiCaptureRecord(
                resource=resource,
                preferred_label=name,
                notations=(agency_id,),
                source_locator=self_link,
                source_digest=pin.sha256,
                native_payload={
                    "id": agency_id,
                    "type": "agencies",
                    "parent": parent,
                    "participate": attributes["participate"],
                    "partner": attributes["partner"],
                    "postingGuidelines": guidelines,
                    "name": name,
                    "agencyType": attributes["agencyType"],
                    "links": dict(links),
                },
                is_skos_concept=False,
                relations=relations,
            )
        )

    if any(parent not in ids for parent in parents):
        raise ValueError(f"{spec.name} names a parent outside the roster")
    if parent_count != 160 or len(parents) != 17:
        raise ValueError(
            f"{spec.name} parent census differs: "
            f"relations={parent_count}, distinct={len(parents)}"
        )
    return _api_capture_view(records, spec, payloads)

def _agency_roster_view(
    release_key: str,
    payloads: Mapping[SourcePin, bytes],
) -> PublisherView:
    """Re-use one independent roster parser without importing producer code."""

    matches = [spec for spec in SOURCES if spec.release_keys == (release_key,)]
    if len(matches) != 1:
        raise ValueError(
            f"agency identity fidelity expected one roster spec for {release_key!r}"
        )
    roster_spec = matches[0]
    reader = _PUBLISHER_READERS.get(roster_spec.reader)
    if reader is None:
        raise ValueError(
            f"agency identity fidelity lacks roster reader {roster_spec.reader!r}"
        )
    return reader(roster_spec, payloads)

def _agency_identity_resource_digest(
    view: PublisherView,
    resource: str,
) -> str:
    digests = view.resource_input_digests.get(resource, frozenset())
    if len(digests) != 1:
        raise ValueError(
            f"agency identity resource {resource!r} does not select one publisher input"
        )
    return next(iter(digests))

def _read_regulations_gov_agency_identity_mapping(
    spec: SourceSpec,
    payloads: Mapping[SourcePin, bytes],
) -> PublisherView:
    """Reconstruct REF-038 mappings from adjudication JSON and roster bytes."""

    adjudication_pin, adjudication_payload = _pin_with_role(
        spec,
        payloads,
        "ownerAdjudication",
    )
    census = _json_without_duplicate_keys(adjudication_payload, spec.name)
    if not isinstance(census, Mapping):
        raise ValueError(f"{spec.name} adjudication must be a JSON object")
    adjudication = census.get("agencyIdentityAdjudication")
    if not isinstance(adjudication, Mapping):
        raise ValueError(f"{spec.name} lacks agencyIdentityAdjudication")
    if (
        adjudication.get("mappingReleaseKey")
        != "regulations-gov-agency-identity-2026-08-16"
        or adjudication.get("mappingPredicate") != f"{ATLAS}sameEntityAs"
        or adjudication.get("reviewerIri") != _AGENCY_IDENTITY_REVIEWER
        or adjudication.get("decidedAt") != _AGENCY_IDENTITY_DECIDED_AT
        or adjudication.get("finalResolvedValueCount") != 321
        or adjudication.get("finalAbstainedValueCount") != 10
        or adjudication.get("mappingEvidenceRecordCount") != 642
    ):
        raise ValueError(f"{spec.name} adjudication header differs")
    residue_decisions = adjudication.get("decisions")
    if not isinstance(residue_decisions, list) or len(residue_decisions) != 52:
        raise ValueError(f"{spec.name} must contain all 52 residue decisions")
    residue_by_value: dict[str, Mapping[str, Any]] = {}
    for ordinal, decision in enumerate(residue_decisions):
        if not isinstance(decision, Mapping):
            raise ValueError(f"{spec.name} residue decision {ordinal} is not an object")
        source_value = _required_text(
            decision.get("sourceValue"),
            f"{spec.name}.decisions[{ordinal}].sourceValue",
        )
        if source_value in residue_by_value:
            raise ValueError(f"{spec.name} repeats residue value {source_value!r}")
        residue_by_value[source_value] = decision

    release_keys = (
        "federal-register-agencies-roster-2026-08-15",
        "federal-hierarchy-orgs-complete-2026-08-15",
        "ecfr-agencies-roster-2026-08-15",
        "regulations-gov-agencies-roster-2026-08-16",
    )
    views = {key: _agency_roster_view(key, payloads) for key in release_keys}
    fr_key, fh_key, ecfr_key, regs_key = release_keys
    regs_view = views[regs_key]
    regs_resources = {
        str(native["id"]): resource
        for resource, native in regs_view.expected_native_payloads.items()
    }
    if len(regs_resources) != 331:
        raise ValueError(f"{spec.name} regulations.gov roster count differs")

    def acronym_index(release_key: str) -> dict[str, list[str]]:
        result: dict[str, list[str]] = defaultdict(list)
        for resource, native in views[release_key].expected_native_payloads.items():
            value = native.get("short_name")
            if isinstance(value, str) and value:
                result[value].append(resource)
        return result

    fr_acronyms = acronym_index(fr_key)
    ecfr_acronyms = acronym_index(ecfr_key)
    decisions: list[dict[str, Any]] = []
    original_residue: set[str] = set()
    for source_value, source_resource in sorted(regs_resources.items()):
        source_native = regs_view.expected_native_payloads[source_resource]
        source_name = _required_text(source_native.get("name"), source_resource)
        fr_candidates = sorted(fr_acronyms.get(source_value, ()))
        ecfr_candidates = sorted(ecfr_acronyms.get(source_value, ()))
        if len(fr_candidates) == 1:
            target_key = fr_key
            target_resource = fr_candidates[0]
            basis = "federalRegisterShortNameEqualsRegulationsGovAgencyId"
        elif len(ecfr_candidates) == 1:
            target_key = ecfr_key
            target_resource = ecfr_candidates[0]
            basis = "ecfrAgencyShortNameEqualsRegulationsGovAgencyId"
        else:
            original_residue.add(source_value)
            residue = residue_by_value.get(source_value)
            if residue is None:
                raise ValueError(
                    f"{spec.name} lacks a residue decision for {source_value!r}"
                )
            if residue.get("decision") == "abstained":
                continue
            if residue.get("decision") != "adopted":
                raise ValueError(
                    f"{spec.name} has unsupported decision for {source_value!r}"
                )
            target_key = _required_text(
                residue.get("objectReleaseKey"),
                f"{spec.name}.{source_value}.objectReleaseKey",
            )
            target_resource = _required_text(
                residue.get("objectResource"),
                f"{spec.name}.{source_value}.objectResource",
            )
            basis = _required_text(
                residue.get("basis"),
                f"{spec.name}.{source_value}.basis",
            )
        target_view = views.get(target_key)
        if target_view is None or target_resource not in target_view.expected_native_payloads:
            raise ValueError(
                f"{spec.name} decision {source_value!r} names an unheld target"
            )
        target_native = target_view.expected_native_payloads[target_resource]
        if basis == "federalRegisterShortNameEqualsRegulationsGovAgencyId":
            target_field = "short_name"
            target_value = source_value
            target_name = _required_text(target_native.get("name"), target_resource)
            reasoning = (
                f"regulations.gov id {source_value} equals the publisher acronym "
                f"on the Federal Register record; regulations.gov names "
                f"{source_name!r} and the target publisher names {target_name!r}."
            )
        elif basis == "ecfrAgencyShortNameEqualsRegulationsGovAgencyId":
            target_field = "short_name"
            target_value = source_value
            target_name = _required_text(target_native.get("name"), target_resource)
            reasoning = (
                f"regulations.gov id {source_value} equals the publisher acronym "
                f"on the eCFR record; regulations.gov names {source_name!r} and "
                f"the target publisher names {target_name!r}."
            )
        else:
            residue = residue_by_value[source_value]
            target_field = {
                fr_key: "name",
                fh_key: "fhorgname",
                ecfr_key: "name",
            }[target_key]
            target_value = target_name = _required_text(
                residue.get("objectPublisherName"),
                f"{spec.name}.{source_value}.objectPublisherName",
            )
            if target_native.get(target_field) != target_name:
                raise ValueError(
                    f"{spec.name} target publisher name drifted for {source_value!r}"
                )
            if residue.get("sourcePublisherName") != source_name:
                raise ValueError(
                    f"{spec.name} source publisher name drifted for {source_value!r}"
                )
            reasoning = _required_text(
                residue.get("reasoning"),
                f"{spec.name}.{source_value}.reasoning",
            )
        decisions.append(
            {
                "basis": basis,
                "reasoning": reasoning,
                "source_name": source_name,
                "source_resource": source_resource,
                "source_value": source_value,
                "target_field": target_field,
                "target_key": target_key,
                "target_name": target_name,
                "target_resource": target_resource,
                "target_value": target_value,
            }
        )
    if original_residue != set(residue_by_value):
        raise ValueError(f"{spec.name} 52-value residue differs from roster bytes")
    if len(decisions) != 321:
        raise ValueError(f"{spec.name} resolved decision count differs")

    pins_by_digest = {pin.sha256: pin for pin in spec.inputs}
    if len(pins_by_digest) != len(spec.inputs):
        raise ValueError(f"{spec.name} input digests must remain unique")
    predicate = f"{ATLAS}sameEntityAs"
    evidence: dict[
        tuple[str, str, str],
        tuple[ExpectedMappingEvidence, ...],
    ] = {}
    for decision in decisions:
        subject = decision["source_resource"]
        obj = decision["target_resource"]
        relation = (subject, predicate, obj)
        if relation in evidence or (obj, predicate, subject) in evidence:
            raise ValueError(f"{spec.name} repeats or reverses an identity assertion")
        triple = {
            "subjectIri": subject,
            "predicateIri": predicate,
            "objectIri": obj,
        }
        shared = {
            **triple,
            "decidedAt": _AGENCY_IDENTITY_DECIDED_AT,
            "decision": "adopted",
            "decisionBasis": decision["basis"],
            "decisionRecord": _AGENCY_IDENTITY_DECISION_RECORD,
            "evidenceTier": "E4",
            "mappingTripleDigest": _canonical_json_digest(
                {"object": obj, "predicate": predicate, "subject": subject}
            ),
            "nameSimilarityUsed": False,
            "publisherNames": {
                "object": decision["target_name"],
                "subject": decision["source_name"],
            },
            "reasoning": decision["reasoning"],
            "reviewerIri": _AGENCY_IDENTITY_REVIEWER,
        }
        endpoint_rows: list[ExpectedMappingEvidence] = []
        for endpoint_role, release_key, resource, field_name, value, publisher_name in (
            (
                "subject",
                regs_key,
                subject,
                "attributes.id",
                decision["source_value"],
                decision["source_name"],
            ),
            (
                "object",
                decision["target_key"],
                obj,
                decision["target_field"],
                decision["target_value"],
                decision["target_name"],
            ),
        ):
            endpoint_view = views[release_key]
            source_digest = _agency_identity_resource_digest(endpoint_view, resource)
            pin = pins_by_digest.get(source_digest)
            if pin is None:
                raise ValueError(
                    f"{spec.name} endpoint {resource!r} lacks a declared input"
                )
            endpoint_rows.append(
                ExpectedMappingEvidence(
                    source_locator=(
                        pin.source_iri
                        + "#agency-identity-resource="
                        + urllib.parse.quote(resource, safe="")
                    ),
                    source_digest=source_digest,
                    native_payload={
                        **shared,
                        "endpointRecord": {
                            "field": field_name,
                            "publisher": _AGENCY_IDENTITY_PUBLISHERS[release_key],
                            "publisherName": publisher_name,
                            "releaseDigest": _AGENCY_IDENTITY_ROSTER_DIGESTS[release_key],
                            "releaseKey": release_key,
                            "resourceIri": resource,
                            "sourceDigest": source_digest,
                            "sourceLocator": endpoint_view.resource_locators[resource],
                            "value": value,
                        },
                        "endpointRole": endpoint_role,
                    },
                )
            )
        evidence[relation] = (endpoint_rows[0], endpoint_rows[1])
    if adjudication_pin.sha256 not in pins_by_digest:
        raise ValueError(f"{spec.name} owner adjudication is not a declared input")
    return _mapping_view(evidence, spec.inputs, evidence)

def _gsdm_cell_lines(cell: Any) -> tuple[str, ...]:
    if not isinstance(cell, str):
        return ()
    return tuple(line for line in (raw.replace(_GSDM_DOMAIN_CR_TOKEN, "").strip() for raw in cell.split("\n")) if line)

def _gsdm_domain_triples(
    lines: Sequence[str],
    label: str,
) -> list[tuple[str, str | None, str]] | None:
    """Parse one cell's lines into (group, code, text) triples.

    Returns ``None`` when no line is a ``CODE = LABEL`` pair: the cell is
    publisher domain text, not an enumeration. Placeholder lines are dropped;
    a line that is neither a pair, a group heading, nor a dash pair continues
    the previous value's wrapped label text.
    """
    if not any(_GSDM_DOMAIN_PAIR_LINE.match(line) for line in lines):
        return None
    triples: list[tuple[str, str | None, str]] = []
    group = ""
    for line in lines:
        pair = _GSDM_DOMAIN_PAIR_LINE.match(line)
        if pair is not None:
            code = pair.group("code").strip()
            text = pair.group("text").strip()
            if _GSDM_DOMAIN_PLACEHOLDER_CODE.match(code):
                continue
            if code == _GSDM_DOMAIN_CODELESS_MARKER:
                triples.append((group, None, text))
            else:
                triples.append((group, code, text))
            continue
        heading = _GSDM_DOMAIN_GROUP_LINE.match(line)
        if heading is not None:
            group = heading.group("name")
            continue
        dash = _GSDM_DOMAIN_DASH_LINE.match(line)
        if dash is not None:
            triples.append((group, dash.group("code"), dash.group("text").strip()))
            continue
        if not triples:
            raise ValueError(f"{label} domain values start with an unrecognized line: {line!r}")
        previous_group, previous_code, previous_text = triples[-1]
        triples[-1] = (previous_group, previous_code, previous_text + " " + line)
    return triples

def _read_gsdm_capture(
    spec: SourceSpec,
    payloads: Mapping[SourcePin, bytes],
) -> PublisherView:
    pin, payload = _single_pin(spec, payloads)
    root = _json_without_duplicate_keys(payload, spec.name)
    if not isinstance(root, Mapping) or not isinstance(root.get("document"), Mapping):
        raise ValueError(f"{spec.name} must contain one document object")
    document = root["document"]
    raw_headers = document.get("headers")
    if not isinstance(raw_headers, list) or not all(
        isinstance(header, Mapping) and isinstance(header.get("raw"), str) for header in raw_headers
    ):
        raise ValueError(f"{spec.name}.document.headers must be raw/display objects")
    header_positions = {header["raw"]: position for position, header in enumerate(raw_headers)}
    for header in (_GSDM_DOMAIN_VALUES_HEADER, _GSDM_DOMAIN_DESCRIPTION_HEADER):
        if header not in header_positions:
            raise ValueError(f"{spec.name} lost its {header!r} column")
    value_position = header_positions[_GSDM_DOMAIN_VALUES_HEADER]
    description_position = header_positions[_GSDM_DOMAIN_DESCRIPTION_HEADER]
    raw_rows = document.get("rows")
    if not isinstance(raw_rows, list) or any(not isinstance(row, list) for row in raw_rows):
        raise ValueError(f"{spec.name}.document.rows must be an array of arrays")

    enumerated_elements = 0
    reference_only = 0
    empty = 0
    records: list[_ApiCaptureRecord] = []
    seen_elements: set[str] = set()
    for row_ordinal, row in enumerate(raw_rows):
        values = list(row)
        if len(values) != _GSDM_DOMAIN_ROW_WIDTH:
            raise ValueError(f"{spec.name}.document.rows[{row_ordinal}] has {len(values)} columns")
        element = values[0]
        if not isinstance(element, str) or not element.strip() or element in seen_elements:
            raise ValueError(f"{spec.name}.document.rows[{row_ordinal}] element name is invalid or repeated")
        seen_elements.add(element)
        lines = _gsdm_cell_lines(values[value_position])
        if not lines:
            empty += 1
            continue
        row_label = f"{spec.name}.{element}"
        triples = _gsdm_domain_triples(lines, row_label)
        description_lines = _gsdm_cell_lines(values[description_position])
        if triples is None:
            # A cell with no pairs is enumerable in exactly one publisher
            # shape: a bare value list whose description cell pairs every
            # listed value with its definition.
            described = _gsdm_domain_triples(description_lines, row_label) if description_lines else None
            if described is not None and [code for _group, code, _text in described] == list(lines):
                if len(lines) != len(set(lines)):
                    raise ValueError(f"{row_label} bare domain value list repeats a value")
                triples = [("", None, line) for line in lines]
            else:
                reference_only += 1
                continue
        enumerated_elements += 1
        identities = [(group, code if code is not None else text) for group, code, text in triples]
        if len(identities) != len(set(identities)):
            raise ValueError(f"{row_label} domain values repeat a (group, identity) pair")
        emitted = set(identities)
        descriptions: dict[tuple[str, str], str] = {}
        described = _gsdm_domain_triples(description_lines, row_label) if description_lines else None
        if described is not None:
            for group, code, text in described:
                identity = code if code is not None else text
                if (group, identity) in emitted:
                    descriptions[(group, identity)] = text
        for group, code, text in triples:
            identity = code if code is not None else text
            group_token = group or "default"
            resource = (
                "urn:ref:gsdm:domain-value:"
                f"{urllib.parse.quote(element, safe='')}:"
                f"{urllib.parse.quote(group_token, safe='')}:"
                f"{urllib.parse.quote(identity, safe='')}"
            )
            code_description = descriptions.get((group, identity))
            native = {
                "gsdmElement": element,
                "rowOrdinal": row_ordinal,
                "domainGroup": group,
                "code": code,
                "value": text,
                "codeDescription": code_description,
            }
            records.append(
                _ApiCaptureRecord(
                    resource=resource,
                    preferred_label=text,
                    notations=(code,) if code is not None else (),
                    source_locator=pin.source_iri or "",
                    source_digest=pin.sha256,
                    native_payload=native,
                    definition=code_description,
                )
            )
    if enumerated_elements + reference_only + empty != len(raw_rows):
        raise ValueError(f"{spec.name} domain value accounting does not cover every row")
    if len(records) != _GSDM_EXPECTED_DOMAIN_VALUE_COUNT:
        raise ValueError(
            f"{spec.name} domain value enumeration drifted: "
            f"expected {_GSDM_EXPECTED_DOMAIN_VALUE_COUNT}, got {len(records)}"
        )
    return _api_capture_view(
        records,
        spec,
        payloads,
        unevaluated_claims=(
            "elements whose domain cell only cites an external code source are not enumerations",
            "elements publishing no domain text enumerate nothing",
            "publisher placeholder lines for future codes are not domain values",
        ),
    )

def _fr_schema_enum(
    root: Any,
    schema_name: str,
    pattern: re.Pattern[str],
    label: str,
) -> tuple[str, ...]:
    if not isinstance(root, Mapping):
        raise ValueError(f"{label} root must be an object")
    components = root.get("components")
    if not isinstance(components, Mapping) or not isinstance(components.get("schemas"), Mapping):
        raise ValueError(f"{label} has no components.schemas object")
    schema = components["schemas"].get(schema_name)
    if not isinstance(schema, Mapping) or not isinstance(schema.get("items"), Mapping):
        raise ValueError(f"{label} schema {schema_name} is not an array schema")
    enum = schema["items"].get("enum")
    if not isinstance(enum, list) or not enum:
        raise ValueError(f"{label} schema {schema_name} declares no enum")
    values: list[str] = []
    for ordinal, value in enumerate(enum):
        if not isinstance(value, str) or pattern.fullmatch(value) is None:
            raise ValueError(f"{label} {schema_name} enum value {ordinal} has an unsupported shape: {value!r}")
        values.append(value)
    if len(set(values)) != len(values):
        raise ValueError(f"{label} {schema_name} enum repeats a value")
    return tuple(values)

def _read_fr_documented_types_capture(
    spec: SourceSpec,
    payloads: Mapping[SourcePin, bytes],
) -> PublisherView:
    documentation_pin, documentation_payload = _pin_with_role(spec, payloads, "publisherApiDescription")
    _facets_pin, facets_payload = _pin_with_role(spec, payloads, "publisherDisplayNames")
    root = _json_without_duplicate_keys(documentation_payload, spec.name)
    codes = _fr_schema_enum(root, "DocumentType", _FR_TYPE_CODE, spec.name)
    facets = _json_without_duplicate_keys(facets_payload, f"{spec.name} facets")
    if not isinstance(facets, Mapping) or set(facets) != set(codes):
        raise ValueError(f"{spec.name} facets keys differ from the documented DocumentType enum")
    records: list[_ApiCaptureRecord] = []
    for code in codes:
        facet = facets[code]
        if not isinstance(facet, Mapping) or set(facet) != {"count", "name"}:
            raise ValueError(f"{spec.name} facet {code} fields drifted")
        name = facet["name"]
        if not isinstance(name, str) or not name.strip() or name != name.strip():
            raise ValueError(f"{spec.name} facet {code} has a malformed display name")
        native = {
            "code": code,
            "displayName": name,
            "enumPath": _FR_DOCUMENT_TYPE_ENUM_PATH,
        }
        records.append(
            _ApiCaptureRecord(
                resource="urn:ref:federal-register-document-type:" + urllib.parse.quote(code, safe=""),
                preferred_label=name,
                notations=(code,),
                source_locator=documentation_pin.source_iri or "",
                source_digest=documentation_pin.sha256,
                native_payload=native,
            )
        )
    if len({record.preferred_label for record in records}) != len(records):
        raise ValueError(f"{spec.name} facets repeat a display name")
    if len(records) != 4:
        raise ValueError(f"{spec.name} documented type enumeration drifted: {len(records)}")
    return _api_capture_view(
        records,
        spec,
        payloads,
        unevaluated_claims=("per-type facet document counts are corpus counts at capture time, not members",),
    )

