def _counter_differences(
    source: str,
    label: str,
    expected: Mapping[str, int],
    observed: Mapping[str, int],
) -> list[str]:
    failures: list[str] = []
    for value in sorted(set(expected) | set(observed)):
        expected_count = expected.get(value, 0)
        observed_count = observed.get(value, 0)
        if expected_count != observed_count:
            failures.append(
                f"{source}: {label} count for {value!r} differs -- "
                f"publisher {expected_count}, observed {observed_count}"
            )
    return failures

def _capture_value_counts(
    source: str,
    capture: Mapping[str, Any],
) -> tuple[dict[str, int], list[str]]:
    failures: list[str] = []
    values = capture.get("values")
    if not isinstance(values, list):
        return {}, [f"{source}: normalized control capture values must be an array"]
    result: dict[str, int] = {}
    for index, row in enumerate(values):
        if not isinstance(row, Mapping) or set(row) != {"count", "value"}:
            failures.append(
                f"{source}: normalized control capture values[{index}] must contain exactly count and value"
            )
            continue
        value = row.get("value")
        count = row.get("count")
        if not isinstance(value, str) or not value.strip():
            failures.append(f"{source}: normalized control capture values[{index}].value must be nonblank text")
            continue
        if not isinstance(count, int) or isinstance(count, bool) or count <= 0:
            failures.append(f"{source}: normalized control capture count for {value!r} must be positive")
            continue
        if value in result:
            failures.append(f"{source}: normalized control capture repeats value {value!r}")
            continue
        result[value] = count
    if list(result) != sorted(result):
        failures.append(f"{source}: normalized control capture values are not in lexical order")
    return result, failures

