def _short(iri: str) -> str:
    """Abbreviate a well-known IRI for readable failure text."""
    for namespace, prefix in (
        (SKOS, "skos"),
        (SKOSXL, "skosxl"),
        (ATLAS, "atlas"),
        (RKAF, "rkaf"),
        (RDF, "rdf"),
    ):
        if iri.startswith(namespace):
            return f"{prefix}:{iri[len(namespace) :]}"
    return f"<{iri}>"

